// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":138,"question":"أحيانًا يأتي بلاغٌ عاجلٌ عن وقوع حادث حريقٍ أو غرقٍ أو نحوهما يستدعي انتقال فرقة الدِّفاع المدني، ويكون الأفراد أثناء حدوث البلاغ يُؤدون الصلاة جماعةً، فما الحكم؟ وهل تُقطع الصلاة أو يستمرون في أدائها، ومن ثَمَّ أداؤها بعد نهاية المهمة؟","title":"حكم قطع الصلاة لتفادي الخطر أو إنقاذ نفس","answer":"الجواب: يجب تقديم الخطر، فإذا كان هناك خطر غرقٍ أو حريق؛ لا مانع من قطع الصلاة، بل قد يجب قطعها إذا كان يتحقق في الخطر، فتُقطع وتُقْضَى بعد ذلك، هذا هو الصواب، فالنبي ﷺ لما اشتدَّت الحربُ مع الأحزاب يوم الأحزاب أخَّر الظهر والعصر حتى صلاها بعد المغرب؛ لشدَّة الحرب، والصحابة يوم تُستر في قتال فارس لما اشتدَّت بهم الحرب أذان الفجر، وصار بعضُهم على أبواب البلد، وبعضهم على الأسوار؛ أخَّروا صلاة الفجر وصلوها ضُحًى.\nوالحريق مضرَّته عظيمة، والغرق كذلك، فإذا جاء الخبرُ أن الحريق حاصلٌ، وأن الغرق حاصلٌ، فليُبادر ولو بقطع الصلاة، أما إذا كان يُخشى أن يكون غريقًا، أو يُخشى، ما بعد صار شيء؛ يُكملوا الصلاة، أما إذا صار الخبرُ أنه وقع فالواجب البدار والمُسارعة إلى إنقاذ مَن أصابه ذلك، ولو أخَّر الصلاة، والحمد لله، فيُؤخِّر الصلاة.\nوالصلاة يجوز تأخيرها للضَّرورة، والضَّرورة تعني: في مصلحة المسلمين، لا في مصلحته هو، لا، فيجب أن يُصلي في الوقت، لكن تأخيرها لمصلحة المسلمين العامَّة الضَّرورية -كالحريق والقتال والغرق- فيجب أن تُقدم المصلحة العامَّة، ولا بأس أن يؤخر عن الوقت، أما مصلحته هو فلا، يجب أن يُصلي في الوقت ولا يُؤخِّر لأجل تجارته، أو حساب تجارته، أو غير ذلك من أموره في الدنيا.","link":"https://binbaz.org.sa/fatwas/3674/حكم-قطع-الصلاة-لتفادي-الخطر-او-انقاذ-نفس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0130.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":239,"question":"ما رأي الشيخ في قضية التَّصوير؟ وما رأي الشيخ لو كان يُصور وهو لا يعلم؟","title":"ما الذي يُستثنى من التصوير المحرم؟","answer":"الجواب: أصل التصوير محرم، هذا الأصل في التَّصوير، قال ﷺ: أشد الناس عذابًا المُصورون، وقال عليه الصلاة والسلام: إنَّ أصحاب هذه الصور يُعذَّبون يوم القيامة ويُقال لهم: أحيوا ما خلقتُم.\nفالتصوير لا يجوز، لا للذكرى ولا لغير هذا من الشؤون التي ليس لها ضرورةٌ، أما للضَّرورة مثل: تصوير الإنسان عند الحاجة إلى الجنسية التابعية المعروفة، أو رخصة القيادة في السيارة، ما يُعطى إلا بذلك؛ فهذا يُعفى عنه للضَّرورة، فهو كالمُكْرَه، وهكذا ما يُصور من النَّدوات والمُحاضرات التي يُرجى فيها مزيدٌ من العلم والخير والفضل، هذا محلُّ نظرٍ، ولا أعلم مَن يمنع ذلك؛ لقصد نفع المسلمين، وإشاعة الخير بين المسلمين، ونشر الدعوة، هذا واقعٌ للمصلحة العامَّة.\nفإذا جاز للتابعية ورخصة القيادة والشهادة الغربية الضَّرورية؛ فالشيء الذي ينفع المجتمع وينفع المسلمين ويكون وسيلةً إلى هداية كثيرٍ من الناس وانتفاعهم هذا يكون أوْلى بالجواز؛ لهذا الغرض النبيل العظيم، ولهذا أقررناه في مجالس الرابطة، وفي مواضع كثيرةٍ لهذه المصلحة العظمى، وإن كنتُ لا أُحبُّ التَّصوير مطلقًا، ولا آذنه مطلقًا إلا للضَّرورة كما سمعنا، والضرورة أمرٌ يُحتاج إليه، وهكذا تصوير المجرمين ليُحْذَروا وليُمْسَكوا إذا وُجِدُوا، وما أشبه ذلك من الحاجات.","link":"https://binbaz.org.sa/fatwas/4117/ما-الذي-يستثنى-من-التصوير-المحرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0249.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":298,"question":"كيف يكون وضع الغُترة وأكمام الثوب في الصلاة؟ وما الدليل على ذلك؟ وهل يجب إسدال الغُترة في الصلاة؟ ومَن لم يفعل ذلك فما الحكم؟","title":"هل يجب إسدال الغُترة وأكمام الثوب في الصلاة","answer":"الجواب: المشروع للمؤمن إسدال كميه وعمامته وغُترته، كلها يتركها، لا يكفتها في الصلاة؛ فالنبي ﷺ قال: أُمرتُ بالسجود على سبعة أعظم، وألا أكُفَّ شعرًا، ولا ثوبًا، هكذا يقول ﷺ: أُمرتُ أن أسجد على سبعة أعظم، وألا أكُفَّ شعرًا، ولا ثوبًا، فالسنة أن تطرح كُمّيك، وتطرح العمامة أو الغُترة معك، لا تكف شيئًا.","link":"https://binbaz.org.sa/fatwas/4300/هل-يجب-اسدال-الغترة-واكمام-الثوب-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0347.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":310,"question":"أرسلوا إليَّ أناسًا مسلمين في بلاد الكفر، وهم في مدرسةٍ داخليةٍ، ولا يستطيعون أن يُصلّوا في أوقاتها خشية أن يروهم ويُفصلون من هذه المدرسة، أرجو من سماحتكم التَّفضل بالإجابة على هذا السؤال، وماذا يفعلون لكي نرد عليهم؟","title":"حكم من يخشى إظهار صلاته في بلد كُفر","answer":"الجواب: إذا كان المسلمون في بلاد الكفرة ويخشون إذا أظهروا صلاتهم أن يُعذَّبوا؛ جاز لهم أن يُصلوا في البيوت، أو في المدرسة، ولا حرج عليهم في ذلك: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا أمِنُوا وجب عليهم إظهار الصلاة، وإذا لم يأمنوا صلوا في بيوتهم، وفي مدارسهم؛ حتى يُسهل الله لهم الهجرة والانتقال إلى بلاد المسلمين، فمتى استطاعوا الهجرة إلى بلدٍ يستطيعون فيها إظهار دينهم وجبت عليهم الهجرة، وما داموا عاجزين فعليهم تقوى الله، وإذا عجزوا عن الصلاة جهرةً صلوا في بيوتهم، وفي مدارسهم.","link":"https://binbaz.org.sa/fatwas/4313/حكم-من-يخشى-اظهار-صلاته-في-بلد-كفر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0360.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":315,"question":"ما حكم وضع المناكير على الأظافر؟","title":"ما حكم وضع المناكير على الأظافر؟","answer":"الجواب: المناكير على اسمها، ما ينبغي فعلها؛ لأنها مُستوردة لهم، لا حاجة إليها، فالأوْلى تركها، والأحوط تركها؛ لأنَّ لها جسمًا، لها جرمًا يُغطِّي الأظافر، ويمنع الماء، لكن مَن فعلتها من النساء تُزيلها عند الوضوء، والحناء يكفي عنها.\nلكن الناس مفتونون بما يرد إليهم من الخارج، مفتونون فتنةً عمياء، وإلا فلا حاجة إلى المناكير، ويكفي عنها الحناء والحمد لله، لكن مَن وضعتها فعليها أن تُزيلها عند الوضوء، كلما توضَّأت تُزيلها عن أظفارها.\nس: وإذا وضعتها.....؟\nالشيخ: تُزيلها عند الوضوء الثاني.","link":"https://binbaz.org.sa/fatwas/4341/ما-حكم-وضع-المناكير-على-الاظافر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0366.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":722,"question":"س: ما رأيكم في المجلات التي تُباع في الأسواق وعليها صورة نساء مُتبرجات فاتنات؟ وهل يجوز بيعها؟","title":"حكم بيع المجلات التي عليها صور نساء","answer":"الجواب: صور المجلات والصحف اليومية والأسبوعية كلها يجب أن تُمنع إذا كانت تشتمل على صور النساء؛ لأنها فتنة، وقد وجّه للدولة في ذلك، ولوزير الإعلام في ذلك ما يقتضي هذا، ونُبّه الجميع على وجوب حماية المسلمين من هذه المجلات والصَّحافة التي تنشر الرذائل والصور الخليعة، سواء في الغلاف أو في داخل المجلة، كل هذا منكرٌ لا يجوز.\nفالواجب على وزارة الإعلام وعلى الرقابة الدينية منع ذلك، وعلى الدولة -وفَّقها الله- منع ذلك، وليس لهم السَّماح بذلك؛ لأنَّ هذا يضرُّ المجتمع كثيرًا، فلا يجوز استيراد أي مجلةٍ ولا أي صحيفةٍ تكون فيها مقالات ضدّ الإسلام، أو صور خليعة، بل يجب منعها، أو قطع تلك الصور وإزالتها قبل الدخول، إما أن تُزال المقالات الضَّارة والصور الخليعة منها، أو تُمنع منعًا باتًّا، ولا يجوز استخدامها أبدًا، ولا يجوز للدولة ولا لوزارة الإعلام ولا للمُراقبين الدِّينيين التَّسامح في هذا الأمر، بل يجب عليهم أن يكونوا نشيطين وأقوياء في هذا الأمر؛ حمايةً للمجتمع الإسلامي في هذه البلاد من هذه البلايا والمحن التي تضرُّ المجتمع ضررًا كبيرًا.","link":"https://binbaz.org.sa/fatwas/20559/حكم-بيع-المجلات-التي-عليها-صور-نساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0517فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":740,"question":"توجد بعض الملابس عليها صور صغيرة، فما حكم الصلاة فيها؟","title":"حكم الصلاة بملابس عليها صور","answer":"الجواب: الملابس التي فيها صور لا يُصلَّى بها، ويُنهى عن الصلاة فيها، سواء كانت الصور كبيرة أو صغيرة، طيور صغيرة أو كبيرة، أو حيوانات أخرى، إلا إذا كانت في محلٍّ يُمتهن، إذا كانت في البُسُط والوسائد الممتهنة فلا بأس بذلك، أما أن يُلبس على الرجال أو النساء أو الأطفال، أو يُنصب في الجدران، أو يُعلّق على أي شيءٍ، هذا يُمنع؛ لأنَّ فيه إظهارًا للصور، والنبي ﷺ لما رأى سترًا عند عائشة فيه تصاوير هتكه وغضب وقال: إنَّ أصحاب هذه الصور يُعذَّبون يوم القيامة، ويُقال لهم: أحيوا ما خلقتم، قالت عائشة: فاتَّخذنا من ذلك الستر وسادتين يرتفق بهما النبيُّ ﷺ.\nوفي الحديث الصحيح أيضًا: أنَّ جبرائيل كان على موعدٍ مع النبي ﷺ، فتأخَّر عن ذلك، فسأله النبيُّ ﷺ عن التأخُّر فقال: إنَّ في البيت تمثالًا وسترًا فيه تصاوير وكلبًا، وقال له جبرائيل: مُرْ بالكلب أن يُخرج، وبالتمثال أن يُقطع رأسه، وبالستر أن يُقطع منه وسادتان منتبذتان تُوطآن، ففعل النبيُّ ﷺ، فدخل جبرائيل عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/20620/حكم-الصلاة-بملابس-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0551بعض الملابس عليها صور صغيرة فما حكم الصلاة فيها؟فتاوى المحاضرات.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":949,"question":"هل يجوز إبقاء التَّماثيل التي على هيئة حيوانات في المنزل بعد قطع رؤوسها؟","title":"ما حكم تماثيل الحيوانات بعد قطع رؤوسها؟","answer":"الجواب: إذا أُزيل الرأس ولم يبقَ إلا الجسم من دون رأسٍ؛ لا بأس، كما في الحديث الصحيح: أن النبي ﷺ واعده جبرائيل ذات يومٍ، فجاء ولم يدخل، فسأله النبيُّ عن ذلك فقال: إنَّ في البيت تمثالًا وسترًا فيه تصاوير وكلبًا، ثم قال: مُرْ برأس التمثال أن يُقطع حتى يكون كهيئة الشجرة، وبالستر أن يُتَّخذ منه وسادتان مُنتبذتان تُوطآن، وبالكلب أن يُخرج، فأمر النبي بذلك، فدخل جبرائيل عليه الصلاة والسلام؛ لأنه إذا زال الرأسُ ما بقيت صورة إنسان، ولا صورة حيوان.","link":"https://binbaz.org.sa/fatwas/20988/ما-حكم-تماثيل-الحيوانات-بعد-قطع-رووسها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0784هل يجوز أبقاء التماثيل التي على هيئة حيوانات في المنزل بعد قطع رؤوسها؟ ابن باز فتاوى المحاضرات.mp3","categories":["الصور والتصوير"]},{"id":1123,"question":"إنَّ في يدي وَشْمًا، وهي صورة طير، فهل هذا يضرُّ على العبادة؟ وما الواجب فعله حيث يصعب إزالته؟","title":"ما حكم صلاة من بيده وَشْم بصورة طير؟","answer":"الجواب:\nالذي في يده وَشْمٌ أو في خديه ليس عليه من هذا شيءٌ، الإثم على مَن فعله به من أهله؛ لأنه ما فعله، فُعِلَ به لصغره، لكن إذا استطاع أن يُزيله بطريقةٍ لا تضرُّه من طريق الأطباء والجراحين، أو بأي شيءٍ؛ يفعل ذلك، وأما إذا لم يستطع فلا شيء عليه: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، سواء كان الوشمُ جروحًا –شخوط- أو صورة طائر، أو حشرة، أو غير ذلك، إذا استطاع إزالتها بأي شيءٍ؛ وجب عليه أن يُزيلها بشيءٍ إذا استطاع ذلك، بدون مضرَّةٍ كبيرةٍ، أما إذا كان فيه مضرَّة ولا يستطيع: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ، ولعلَّ هذا يكفي.\nوفَّق الله الجميع، وصلَّى الله وسلَّم على نبينا محمدٍ.","link":"https://binbaz.org.sa/fatwas/21181/ما-حكم-صلاة-من-بيده-وشم-بصورة-طير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0977أن في يدي وشم على صورة طير فهل يضر على العبادة وما والواجب فعله حيث يصعب إزالته؟.mp3","categories":["الصور والتصوير"]},{"id":1912,"question":"يقول السائل: يسأل رجلٌ عنده جهاز كاميرا تصوير فيديو، ويريد بيع هذا الجهاز والحج بثمنه، علمًا بأن التصوير المستخدم فقط مناظر طبيعية وحفلات زواج قبائل، فما الحكم في بيعه والحج بثمنه؟","title":"حكم الحج بثمن بيع آلة تصوير فيديو","answer":"الجواب:\nإذا كان يُصور ذوات الأرواح تصوير يَثْبُت في القراطيس أو في الخِرَق أو في الحجر فلا يجوز، إلا إذا كان التصوير للضرورة: للتابعيات، للشهادات العلمية، للضرورة؛ فلا بأس. أما جهاز يصور للناس مَن أراد: يصور فلان وفلان وفلان، لا، ما يجوز هذا، هذا من التعاون على الإثم والعدوان. أما إذا صوَّر شيئًا تدعو له الضرورة: مثلما يؤخذ عليه في التابعية صورة، ومثل الشهادات العلمية حيث يقولون: ما نُعطيك إيَّاها إلا بصورةٍ؛ فلا بأس، والله يقول: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119].\nس: يُصور منظر الطبيعة مثلًا؟\nج: الذي ما يَثْبُت ما يصير صورةً، مثل: الصورة في المرآة ما تَثْبُت.\nس: هذه صورة متحركة؟\nج: إذا كانت ما تَثْبُت في ورقةٍ ولا في قرطاسٍ.\nس: نعم لا تَثْبُت؟\nج: لا تصير صورةً.\nس: يبيعها ويحج بثمنها؟\nج: إذا لم تكن تُصور صورةً تَثْبُت؛ ما يضر.  الممنوع صورة تَثْبُت في ورقةٍ أو في خرقةٍ.","link":"https://binbaz.org.sa/fatwas/22025/حكم-الحج-بثمن-بيع-الة-تصوير-فيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم بيع جهاز كاميرا تصوير فيديو والحج بثمنه.mp3","categories":["الصور والتصوير"]},{"id":1919,"question":"في ترجمة الباب قال: تحريم تصوير الحيوان في بساطٍ أو حجرٍ أو ثوبٍ أو مخدةٍ أو دينارٍ؟","title":"ما ضابط الامتهان المبيح لاستعمال الصور؟","answer":"الجواب:\nفي كل شيء.\nس: لكنه ما ذكر الامتهان؟\nج: الامتهان معروف، يمكن أن يأتي في بابٍ آخر، فالنبي ﷺ أنه اتّخذ وسادةً أو وسادتين ترك هذا، وفي حديث أبي هريرة: أنه ﷺ واعد جبرائيل، فتأخَّر جبرائيل، فخرج إليه فقال: إنَّ في البيت تمثالًا، وقِرامًا فيه صورة، وكلبًا، فأمر برأس التمثال أن يُقطع حتى يكون كهيئة الشجرة، وأمر بالقِرَام أن يُبسط وسادتين مُنتبذتين، وأمر بالكلب أن يُخرج، ففعل النبي ﷺ؛ فدخل جبرائيل عليه الصلاة والسلام.\nس: هل يستدل من قوله ﷺ في الحديث: فليخلقوا ذَرَّة على منع التصوير مطلقاً؟\nج: لا، الذي عليه عامَّةُ العلماء ما عدا ذوات الأرواح؛ لأنَّ هذا من باب التَّحدي، والنبي ﷺ إنما حرَّم ذوات الأرواح، أما تصوير حجرٍ -مثلما قال ابنُ عباس- أو جبلٍ أو جنةٍ فلا بأس.\nس: إذا صوَّر صورةً ووضع خطًّا على الرقبة؟\nج: ما يكفي، لا بدَّ من إزالة الرأس، الخط ما يكفي، لا بدّ أن يُزال الرأس كله.\nس: أفلام الفيديو التي فيها رسوم متحركة للأولاد؟\nج: التصوير لا يجوز مطلقًا، لا للأولاد ولا غيرهم، أما ما كان مثل الذي يُرَى في المرآة فلا يُسمَّى صورة.\nس: بالنسبة لما في البساط؟\nج: الذي يُرَى ولا يُصوَّر ما فيه شيء.\nس: بالنسبة للبساط أو المفروشات تكون الصورة ظاهرةً أحيانًا في المخدات أو الأكياس؟\nج: الإثم على مَن صوَّرها، أما أنت فما عليك شيء.\nس: طيب، وشاريها ما يدخل في النَّهي؟\nج: شاريها ما عليه شيء، ما دام البساطُ يُمتهن ما يضرّ، لكن الذي يُعلّق أو يُلْبَس هو الذي يُمْنَع ولا يجوز.\nس: ولو صلَّى عليها؟\nج: لو صلَّى عليها ما يضرّ، لكن فقط بها نُقوش قد تُشوش عليه صلاته، فكون السجادة خالية من النقوش حتى غير الصور أفضل.\nس: ما هي نقوش، ولكنها صورة؟\nج: أقول: أشد من النقوش، ولا يُصلِّي عليها حتى لا تُشوش عليه صلاته، من باب الأفضلية.\nس: لكن لو صلَّى هل الصلاة صحيحة؟\nج: ما في شيء.\nس: البطانيات والمخادع؟\nج: كذلك البطانية ممتهنة مثل الوسادة.","link":"https://binbaz.org.sa/fatwas/22032/ما-ضابط-الامتهان-المبيح-لاستعمال-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة الصتويرة والامتهان في الصور.mp3","categories":["الصور والتصوير"]},{"id":1920,"question":"مَن دُعِي إلى منزلٍ ووجد فيه صورةً أو كلبًا، هل يجوز له أن يمتنع من الدخول؟","title":"حكم مَن دُعِي لمنزلٍ فوجد به صُوَرًا أو كلبًا","answer":"الجواب:\nلا، ينصحهم أولًا.\nس: وإذا رفضوا؟\nج: إذا رفضوا يمتنع، من باب الهجر.","link":"https://binbaz.org.sa/fatwas/22033/حكم-من-دعي-لمنزل-فوجد-به-صورا-او-كلبا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دُعِي إلى منزلٍ به صُوَرًا أو كلبًا.mp3","categories":["الصور والتصوير"]},{"id":1921,"question":"الآن القصص الخاصة بالتاريخ الإسلامي ونحوه: تكون هناك شخصية تاريخية يُصوّرونها، ثم يُصوّرونها على نحو فيلم، وهي صور يدوية؟","title":"حكم تصوير قصص التاريخ الإسلامي كأفلام","answer":"الجواب:\nالمقصود أن الصور ممنوعة إلا ما كان للضرورة؛ لأن الله قال: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ  [الأنعام:119]، ما اضطررنا إليه من صورة تابعية، أو شهادة علمية ما حصلت إلا بذلك؛ فيُعفى عن ذلك لأجل الضرورة.","link":"https://binbaz.org.sa/fatwas/22034/حكم-تصوير-قصص-التاريخ-الاسلامي-كافلام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تصوير القصص الخاصة بالتاريخ الإسلامي على نحو فيلم.mp3","categories":["الصور والتصوير"]},{"id":1922,"question":"البضائع التي عليها صور مثل الملابس وغيرها؟","title":"حكم الصور التي في الملابس ونحوها","answer":"الجواب:\nتُمسح وتُزال، فتُقطع الرأس وتُستعمل، فتُمسح الرأس بشيءٍ حتى لا يبين منها شيء ولو بصبغٍ.\nس: قد يستوردون عشرة آلاف مثلًا، فيكون من الصعب طمس الصور؟\nج: يجتهد، فالمطلوب هو طمس الرؤوس فقط، ما هو بالصورة كلها، فالرأس إذا طمسها يكفي.\nس: إذا طمسها فالزبائن لا يشترونه؟\nج: حتى ما يُورِّده بعد ذلك، فلعله يتوب ولا يُورِّده.","link":"https://binbaz.org.sa/fatwas/22035/حكم-الصور-التي-في-الملابس-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصور التي في الملابس وغيرها.mp3","categories":["الصور والتصوير"]},{"id":1923,"question":"الصور الفوتوغرافية؟","title":"حكم الصور الشمسية (الفوتوغرافية)","answer":"الجواب:\nنعم، الذي في القِرام والورق يُسمَّى \"فوتوغرافي\"، يعني: ما له جسم.\nس: والشمسية حاليًّا؟\nج: هي الفوتوغرافية.\nس: صغيرة ما تمنع؟\nج: كل شيءٍ يُعلَّق يمنع، أما ما يُداس ويُمتهن فهو الذي ما يمنع.\nس: في جيوب الملابس؟\nج: يعمّها المنع، إذا قُطع الرأس زال حكم الصورة أو طُمِسَ، لكن قطعها أوْلى، فكونه يُزال بالكلية أوْلى، كما أمر النبيُّ ﷺ حيث أمر برأس التمثال أن يُقطع، يعني: يُزال بالكلية، ما عاد يبقى إلا جثة بلا رأس.","link":"https://binbaz.org.sa/fatwas/22036/حكم-الصور-الشمسية-الفوتوغرافية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصور الشمسية الفوتوغرافية.mp3","categories":["الصور والتصوير"]},{"id":1924,"question":"الصورة في بطاقة الأحوال يرجى...؟","title":"حكم الصور في التعليم والضرورات المستجدة","answer":"الجواب:\nإذا كان للضرورة، فالله قال: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] ما يتعلق بالشهادة العلمية، أو بالجنسية وكونهم ما يُعطونه الجنسية إلا بصورةٍ، أو شهادة إلا بصورة، يكون من باب الضَّرورات.\nس: بعض القواميس فيها صور؟\nج: إذا طُبِّقَ ولم يُفتح نرجو أن يكون سهلًا، لكن كونه يُفتح أو تُعلَّق صوره على الجدران هذا هو الممنوع، أما كونه يُغلق حتى تجيء الحاجة إليه فيُراجع فالأمر سهل إن شاء الله، وإذا قُطِعَ الرأسُ يكون أسلم وأحوط.\nس: بالنسبة لمدرس التربية الفنية: إذا رسم للطلاب على السبورة بيَّن لهم أنَّ هذه صورة كذا وكذا ثم يمسحها هل يأثم؟\nج: الرأس ما يجوز، لا يرسم لهم شيئًا فيه رأس، أما بدون رأسٍ فلا بأس، أما أن يرسم لهم صورةً كاملةً مثل رسمها بالقرطاس فلا.\nس: يُوضحها للطلاب ثم يُزيلها؟\nج: لا، يُوضِّح لهم بالحدس، ما هو بالصورة، الكلام يكفي، فهو الذي كفى الأولين.\nس: هل تجب إزالة ما زاد عن الصورة الشَّمسية؛ لأنه معروف إذا صورت يُصورون سبع صورٍ معًا، والحاجة قد تكون إلى ثنتين أو ثلاثة؟\nج: تُبقي الشيء المضطر إليه، والباقي يُتْلَف.","link":"https://binbaz.org.sa/fatwas/22037/حكم-الصور-في-التعليم-والضرورات-المستجدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصور في حال الضرورة والتعليم ونحوها.mp3","categories":["الصور والتصوير"]},{"id":2263,"question":"هل يدخل في التَّصاوير: التَّماثيل التي تكون في الورق؟","title":"حكم التصاوير على الورق والوسائد ونحوها","answer":"الجواب:\nالتصاوير تكون في ورقٍ، أو في خِرَقٍ، أو في جدرانٍ، أو في حجرٍ، أو مستقلةً.\nس: التَّصاوير إذا كانت في وسادةٍ أو في فِراشٍ يُمتهن هل لا تدخل الملائكةُ البيتَ؟\nج: لا، ما تمنع دخول الملائكة إذا كانت تُمتهن، إذا كانت في وسادةٍ أو بساطٍ ما تمنع دخول الملائكة.\nس: والصَّلاة عليها؟\nج: لا حرج، إذا جاز بسطها جازت الصلاةُ عليها، لكن الصلاة على الشيء الذي ما فيه نقوش ولا فيه شيء يُشوش أحسن، فالشيء الخالي من النقوش والزخارف أحسن؛ حتى لا يتشوش المصلّي.","link":"https://binbaz.org.sa/fatwas/22386/حكم-التصاوير-على-الورق-والوساىد-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل التماثيل تدخل في التصاوير.mp3","categories":["الصور والتصوير"]},{"id":2409,"question":"التصوير الفيو؟","title":"حكم التصوير وتعليم الناس بواسطة الصور","answer":"الجواب:\nالظاهر أنه داخل فيه لأنه يثبت في الورق.\n...........\nالظاهر أنه يثبت في الورق، إذا كان التصوير يثبت وإن كان ما يثبت يؤخذ من غير ثبات، يوضع من غير ثبات، هذا ما يضر، أما إذا كان يثبت في ورقة أو في خرقة أو في شيء لا يجوز.\nس: هو يثبت في شريط أسود، لكن إذا ظهر في التلفزيون ظهر فيه صوت؟\nالشيخ: الظاهر أنه تعمه الأخبار، يسمى مصور لأنه ظهر صورة بين الناس يسمى صاحبه مصور لأنه ظهرت الصورة بين الناس رجال ونساء كلاب حمير وشجر وحجر. لأن المقصود هو الصورة -صورة ظاهرة- والرسول ﷺ لعن كل مصور، وهذا تظهر فالصورة كاملة أمام الناس\nس: لكن من باب تعليم الدين؟\nالشيخ: يعلم مثل ما علم النبي ﷺ الأمة، الرسول علم الأمة من دون تصوير، والصحابة علموا الأمة من دون تصوير، الذي كفى الأولين يكفي الآخرين.","link":"https://binbaz.org.sa/fatwas/22536/حكم-التصوير-وتعليم-الناس-بواسطة-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التصوير وتعليم الناس بواسطة الصور.mp3","categories":["الصور والتصوير"]},{"id":2464,"question":"تعليق الصورة في المسجد؟","title":"ما حكم تعليق الصورة في المسجد؟","answer":"الجواب:\nالصورة ما تجوز، لا في المسجد ولا في البيت، حتى في البيت ما يجوز، سواء صورة إنسان وإلا حيوان.\nس: مثل الجرائد؟\nالشيخ: لا، ما يجوز إذا صار عنده يمسح رأسها ولا يعلقها في الجدار.\nس: بعضهم يعلّق صور الفقراء ويضع عليها ورقة: تصدقوا، وآيات تحث على الصدقة؟\nالشيخ: لا ما يجوز، يدعو للصدقة من دون صور، يدعو للصدقة على الفقراء من دون صور.","link":"https://binbaz.org.sa/fatwas/22593/ما-حكم-تعليق-الصورة-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تعليق الصورة في المسجد.mp3","categories":["الصور والتصوير","المساجد ومواضع السجود"]},{"id":2538,"question":"رجل يعمل في تصوير النساء والرجال؟","title":"حكم مَنْ يعمل في تصوير النساء والرجال","answer":"الجواب: هذا مُنْكَر، كَسْبُه خبيث.\nس: يجوز أكل ذبيحته؟\nالشيخ: إذا كان من هذا الكسب لا، أما إذا كان له أكساب أخرى لا بأس.\nس: إذا كان له كَسْبٌ آخر؟\nالشيخ: لا بأس، مثل اليهود لهم كسب آخر، وأكل النبي ﷺ طعامهم.\nس: حكم معاشرته؟\nالشيخ: ينبغي أن يُنصح ويُوجّه إلى الخير مثل سائر العصاة، لا يتخذ صاحبًا ولا عشيرًا، يُنصح بأن هذا ما يجوز يا عبد الله جزاك الله خيرًا، اتق الله، الرسول ﷺ لعن المصوِّرين.","link":"https://binbaz.org.sa/fatwas/22669/حكم-من-يعمل-في-تصوير-النساء-والرجال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/العمل في تصوير النساء والرجال وحكم ذبيحته.mp3","categories":["الصور والتصوير"]},{"id":2539,"question":"التصوير في التلفزيون؟","title":"حكم التصوير في التلفزيون والحرم ونحوه","answer":"الجواب: سواء في التلفزيون وإلا غير التلفزيون.\nس: وتصوير الحرم؟\nالشيخ: لا يجوز تصوير كل ذوات الأرواح.\nس: حتى في الحرم.\nالشيخ: نعم، أي تصوير. هذا ما هو بتصوير، هذا يأخذونه بدون صورة، ما هو بشيء يَثْبُت، هذا نقل الصلوات في التلفاز هذا ما هو بصورة ثابتة كأنها مرآة تُنْصب ويشوفها الناس، الذي ما له ثبات مثل المرآة.  أما الذي يَثْبُت في الورقة أو خِرْقة أو جدار أو خَشَبة؛ هذا مُنْكَر.","link":"https://binbaz.org.sa/fatwas/22670/حكم-التصوير-في-التلفزيون-والحرم-ونحوه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التصوير في التلفزيون والحرم ونحوه..mp3","categories":["الصور والتصوير"]},{"id":2566,"question":"بعض المصوِّرين يصوِّر جسم إنسان ويطمس الوجه؟","title":"حكم تصوير جسم إنسان مع طمس الوجه","answer":"الجواب: لا، لا بدّ من قطع الرأس، إذا كان بدون رأس يزول الرأس بالكلية.\nس: ولكن ليس العبرة بأنه ما يرسم..؟\nالشيخ: النبي ﷺ أمر بقطع الرأس.\nس: حتى الأطفال؟\nالشيخ: حتى الأطفال لا يُلبسهم ملابس فيها صور.","link":"https://binbaz.org.sa/fatwas/22698/حكم-تصوير-جسم-انسان-مع-طمس-الوجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم تصوير جسم إنسان مع طمس الوجه.mp3","categories":["الصور والتصوير"]},{"id":2641,"question":"هل طمس الصورة أو قطع رأسها:: مثلًا مزيل يقطع الرأس...؟","title":"ما كيفية طمس صور ذوات الأرواح؟","answer":"الجواب: إذا أزيل مرة، قُضي عليه كُلّه، ما هو بس يَخُطّ، لا، يُزال، لا بد يُزال.","link":"https://binbaz.org.sa/fatwas/22776/ما-كيفية-طمس-صور-ذوات-الارواح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/طمس الصورة أو قطع رأسها.mp3","categories":["الصور والتصوير"]},{"id":2839,"question":"الصُّحف التي فيها صور هل البيت لا يدخله الملائكة؟","title":"هل صور الصُّحف مما يمنع دخول الملائكة؟","answer":"الجواب: يُخشى، لكن الأحْوَط للمؤمن أن يقطع رؤوسها، يمسحها بشيء، الرؤوس يضع عليها صبغًا حتى تزول، أو يقطعها.\nس: كل الصور التي في الصحيفة؟\nالشيخ: رؤوسها، يكون أبعد، وإلا هي مصفوطة ومدفونة أسهل، لكن كونه يقطع رؤوسها بإزالتها أو صبغ بوضع حبر عليها أو صبغ عليها يزيلها.\nس: إذا كان يقرؤها ويرميها بعد أن ينتهي منها؟\nالشيخ: إذا كان ما فيها فائدة يمزقها أو يدفنها.","link":"https://binbaz.org.sa/fatwas/22989/هل-صور-الصحف-مما-يمنع-دخول-الملاىكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الملائكة لا تدخل بيتا في صور في الصحف.mp3","categories":["الصور والتصوير"]},{"id":2895,"question":"الصورة متى يقال أنها مُمْتَهنة؟","title":"متى تُعتبر الصورة مُمْتَهنة؟","answer":"الجواب: إذا كانت في الفُرُش والوسائد، هذه المُمْتهنة.","link":"https://binbaz.org.sa/fatwas/23050/متى-تعتبر-الصورة-ممتهنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/متى تكون الصورة ممتهنة.mp3","categories":["الصور والتصوير"]},{"id":3724,"question":"نظر المرأة إلى صورة في التلفاز..؟","title":"حكم نظر المرأة إلى صورة في التلفاز","answer":"الجواب: التلفاز نفسه فيه خطر، ويجب الحذر، يجب البعد من شره وفساده، اللهم إلا النظر فيما ينفع المسلمين من محاضرات وأعمال تنفع المسلمين، وأما هي فإذا نظرت بغير شهوة ولا ريبة وإنما نظر عام لا يضر.\nس: التلفزيون إذا كان تحت مراقبة محكمة فينظر إلى البرامج العلمية؟\nالشيخ: على كل حال إذا كان الرجل يُحْكِمُ ذلك فلا بأس، لكن هو خطير ويجب الحذر.","link":"https://binbaz.org.sa/fatwas/23916/حكم-نظر-المراة-الى-صورة-في-التلفاز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/نظر المرأة إلى صورة في التلفاز.mp3","categories":["الصور والتصوير"]},{"id":3901,"question":"الصور التي في المجلات؟","title":"حكم الصور التي في المجلات","answer":"الجواب: محل نظر؛ لأنها تُغطَّى ولا تُعلَّق، وإذا احتاط الإنسانُ ومحا الرؤوس كفى؛ لأنها قد تكون كتبًا مؤلفة يحتاج إليها، قد تكون مجلات يحتاج إليها أهلُ العلم، فهي محتملة أن تُلحق بالممتهن، ومحتملة أن تُلحق بالمغطَّى الذي عليه غطاء آخر، تكون مُغطاة بأوراق أو بخرقٍ أخرى فلا تظهر، فإذا كانت لا تظهر كالمعدومة.","link":"https://binbaz.org.sa/fatwas/24117/حكم-الصور-التي-في-المجلات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصور التي في المجلات.mp3","categories":["الصور والتصوير"]},{"id":3902,"question":"رسم بعض أعضاء الإنسان غير الرأس كاليد والرجل، هل يدخل في حكم التصوير؟","title":"حكم رسم أعضاء الإنسان غير الرأس","answer":"الجواب: الرأس هو عين الصورة -صورة الرأس- أما غيره ما هو بداخل، النبي ﷺ أمره جبريل أن يأمر بقطع رأس التمثال حتى يكون كهيئة الشجرة، تصوير اليد أو الرجل أو أي عضو للنظر فيه أو التأمل: كالقلب أو الرئة للنظر في بعضها، أو لحاجةٍ من الحاجات؛ ما يدخل في الصورة الكاملة، أما الرأس فهو داخل..\nس: الطمس؟\nج: يحط عليه حبر أو بُوية.\nس: رسمه باليد؟\nج: باليد وإلا بغيره كله تصوير.","link":"https://binbaz.org.sa/fatwas/24118/حكم-رسم-اعضاء-الانسان-غير-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم رسم أعضاء الإنسان كاليد والرجل هل يدخل في حكم التصوير.mp3","categories":["الصور والتصوير"]},{"id":3908,"question":"إذا عزمه واحد، دعاه إنسان في بيته، وفيه صور؟","title":"ما يفعل من وجد صورًا في بيت من دعاه؟","answer":"الجواب: إذا كانت معلّقة يمتنع، ولا يدخله إلا إذا كانت تمتهن.","link":"https://binbaz.org.sa/fatwas/24125/ما-يفعل-من-وجد-صورا-في-بيت-من-دعاه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الحكم في إذا عُزِم واحد، دعاه إنسان في بيته وفيه صور.mp3","categories":["الصور والتصوير"]},{"id":3910,"question":"الصور في الثياب؟","title":"حكم الصور في الثياب","answer":"الجواب: ما تجوز الثياب الملبوسة؛ لأنها في حكم المنصوبة: يقف فيها الإنسان، ويمشي فيها الإنسان، ما هي في حكم الممتهنة، ما هي في حكم البساط، ما يجوز لبس الثياب المصورة.","link":"https://binbaz.org.sa/fatwas/24128/حكم-الصور-في-الثياب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصور في الثياب.mp3","categories":["الصور والتصوير"]},{"id":3956,"question":"لو اقتناها الإنسان لبناته (الألعاب التي فيها مضاهاة لخلق الله) لكنه أحرق وجهها وغَيَّر؟","title":"حكم ألعاب البنات التي فيها مضاهاة لخلق الله","answer":"الجواب: ما يحصل به المقصود إذا أحرق وجهها، إلا إذا راح الرأس ما في خلاف، أو وُجد بنات بدون رأس ما في شيء، جائز. الكلام مع رؤوسهن.","link":"https://binbaz.org.sa/fatwas/24181/حكم-العاب-البنات-التي-فيها-مضاهاة-لخلق-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز اقتناء الألعاب التي فيها مضاهاه لخلق الله مع أحراق الوجه.mp3","categories":["الصور والتصوير"]},{"id":4301,"question":"بالنسبة للذين صوروا صور الصالحين قوم نوح هل في شريعتهم الصورة عندهم غير محرمة؟","title":"هل كانت التصاوير محرمة فيمن كان قبلنا؟","answer":"الجواب: ما أدري عنهم، لكن صارت سببًا لوقوع الشرك، أما كونها في شريعتهم جائزة الله أعلم، لكن مقتضى ذم الناس لهم أنها غير جائزة؛ لأن ذمهم على هذا يقتضي أنها ممنوعة في حقهم ولهذا ذُموا عليها.","link":"https://binbaz.org.sa/fatwas/24575/هل-كانت-التصاوير-محرمة-فيمن-كان-قبلنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل كانت التصاوير في من كان قبلنا محرمة.mp3","categories":["الصور والتصوير"]},{"id":4522,"question":"الصور التي في كتب المناهج؟","title":"ما حكم الصور التي في الكتب الدراسية؟","answer":"الجواب: هذا محل نظر، محل احتمال، والذي يظهر والأقرب -والله أعلم- أنه ينبغي مسح الرؤوس، فليس مما يُعظَّم، ولكنها فيها شيء من مُشابهة الشيء الذي يُعلَّق؛ لأنه يُشال ويحط ويرفع، فإذا تيسر طمس الرؤوس فهو أحوط، وقد يُشبه الوسادة من بعض الوجوه؛ لأنه قد يوضع على الأرض، وقد يوضع عليه شيء، وقد يكون فيه نوع من عدم الاعتزاز وعدم الاحترام، ولكن ما كان في الكتب والمجلات قد يُحترم، وقد يُوضع في محلٍّ رفيع، وقد يتداوله الناسُ، كونه يمسح -تُمسح الرؤوس- أولى كما في حديث عليٍّ: لا تدع صورةً إلا طمستها، كونه يمسح الرأس أو يقطع الرأس هذا أحوط في المجلات والتي فيها فائدة، أو الكتب التي فيها فائدة، أو يُوضع عليه شيء، يعني: ورقة تُلصق على الرأس.\nس: وكونه مطبق ما يكفي؟\nج: فيه نظر؛ لأنَّ المطبق ما يستمر، يفتش ويرفع، فكونه يُجعل عليه شيء أحوط، فليس من الستر المعلَّق، وليس من جنس الستر المرسوم على الباب والجدار، فهو شيء يعني: مستور في الغالب، إلا إذا أُريدت الفائدة فُتح، أما ما يكون على الغلاف هذا يجب إزالته؛ لأنه مكشوف ما يكون على الغلاف هذا يجب إزالته.\nس: يشترط [في] الصورة [أن] تكون كاملةً أو جزءًا؟\nج: المهم الرأس، إذا وجد الرأس.","link":"https://binbaz.org.sa/fatwas/24802/ما-حكم-الصور-التي-في-الكتب-الدراسية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الصور التي في كتب المناهج.mp3","categories":["الصور والتصوير"]},{"id":4523,"question":"كثير من المواد الاستهلاكية عليها صور؟","title":"حكم الصور في العلب والمواد الاستهلاكية","answer":"الجواب: هذه أسهل، هذه العلب التي تُلقى هذه ممتهنة، هذه أمرها من جنس أمر البساط مُمتهن، الشيء الذي يُمتهن غير داخلٍ في هذا.\nوفي حديث ابن عباس الدلالة على أنَّ ما لا روح له لا بأس بتصويره: كالجبل، والسيارة، والشجرة، وأشباه ذلك مثلما قال ابن عباس، أو هذا محل إجماع بين أهل العلم، ولا حرج في ذلك، والله أعلم.","link":"https://binbaz.org.sa/fatwas/24803/حكم-الصور-في-العلب-والمواد-الاستهلاكية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الصور التي لا روح لها والتي في المواد الاستهلاكية.mp3","categories":["الصور والتصوير"]},{"id":4524,"question":"هل ما يُصور في الجوازات، وهذا يكون .....؟","title":"ما ضابط الضرورة في إباحة الصور؟","answer":"الجواب: الذي للضَّرورة يُعفى عنه، الذي للضَّرورة وما هو باختيار الإنسان في حكم المكره، مثل: التابعية، ومثل: الجواز، ومثل: المتطرفين، ومثل: صورة المجرمين الذين يطلب إمساكهم وحفظهم.","link":"https://binbaz.org.sa/fatwas/24804/ما-ضابط-الضرورة-في-اباحة-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصور التي للضرورة.mp3","categories":["الصور والتصوير"]},{"id":4525,"question":"العرائس؟","title":"هل عرائس البنات من الصور الممنوعة؟","answer":"الجواب: فيها خلاف بين أهل العلم: منهم مَن رآها جائزة؛ لأنه وُجد عند عائشة بنات لها، كما في الحديث الصحيح، وكان النبيُّ ﷺ يُسرّب إليها بناتها، وكانت عندها بعض الصور.  وحكى القاضي عياض عن الجمهور أنه يُسمح بصور البنات الصغار لتعليم البنات -وهن العرائس-. وقال آخرون أنها يعمّها المنع، والذي فعلته عائشة كان قبل المنع، وأن بعد المنع يمنع حتى العرائس، حتى صور الجواري الصغار البنات يتعلمّن عليها، وهذا أحوط إذا تيسر منع ذلك، وأن يُجعل لهن صور خاصَّة من جنس الذي يفعلها ..... سابقًا، صور ما هي مصورة، كأن يكون لهم كذا خياطات أو عظام يُجعل عليها لباس أو أعواد أو كذا لبنات لهم، غير مصورة تصوير قبيح شنيع، نسأل الله العافية، والأحوط ترك هذا، والخلاف فيه مشهور.","link":"https://binbaz.org.sa/fatwas/24805/هل-عراىس-البنات-من-الصور-الممنوعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تدخل عرائس البنات في الصور، وما حكمها.mp3","categories":["الصور والتصوير"]},{"id":4526,"question":"الأجسام المُجسدة دون الرأس؟","title":"حكم الصورة المُجسدة دون الرأس","answer":"الجواب: إذا أبعد الرأس، ما هو فقط خط كما يفعل بعضُ الناس، خط لا يبعد بالمرة، يزال.\nس: ما يكون من الرسم لذوات الأرواح؟\nج: إذا أُزيل الرأس بالكلية ولا وجد مثل... قطع رأسه، أزاله يعني حتى كانت كالشجرة.\nس: وضع فاصل بين الرأس والجسم؟\nج: ما يكفي، لا، ما يكفي.","link":"https://binbaz.org.sa/fatwas/24806/حكم-الصورة-المجسدة-دون-الراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الأجسام المُجسدة دون الرأس.mp3","categories":["الصور والتصوير"]},{"id":4667,"question":"... العطورات الحديثة هل فيها كحول؟","title":"حكم العطورات الحديثة التي فيها كحول","answer":"الجواب: الطيب مطلوب بجميع أنواع الطيب، إلا إذا عرف أنَّ نوعًا منها يُسكر، فما أسكر كثيره فقليله حرام، مثل: الكالونيا مسكرة لا تُستعمل؛ لأنَّ فيها ما يحصل به الإسكار، فيجتنبها، وهكذا لو وجد طيبًا آخر فيه ما يُسكر يمنع. أما الطيب السليم فالسنة التَّطيب، وهو مشروع، وكان يُحب الطيبَ عليه الصلاة والسلام، ويتطيب، ومشروع للمؤمن أن يتطيَّب. س: ما يخلو من نسبةٍ ولو قليلة من الكحول؟ ج: ما أسكر كثيره فقليله حرام، إذا كان يُسكر كثيره فهذا الممنوع، أما إذا كان لا يُسكر فلا يُمنع.","link":"https://binbaz.org.sa/fatwas/24959/حكم-العطورات-الحديثة-التي-فيها-كحول","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم العطورات الحديثة التي فيها كحول.mp3","categories":["الصور والتصوير"]},{"id":4986,"question":"الراجح في لعب الأطفال هل يترخص فيها لأجل أنهم أطفال إذا كانت على وجه؟","title":"ما حكم صورة الوجه في لُعَب الأطفال؟","answer":"الجواب: فيه خلاف بين العلماء، منها حديث عائشة رضي الله عنها: \"أنها كانت عندها بنيّات لها\" بعض أهل العلم قال يُتسامح فيها؛ لأنها ممتهنة، وبعض أهل العلم قال: لا، الذي عند عائشة البنات العادية التي عند العرب، يخيطون..... أشياء ما هي بصور. \nفالأحْوَط عدم الصور، الأحوط تركُها؛ عملًا بالأحاديث لعن رسول الله المصوِّرين وقال: إنهم أشد الناس عذابًا يوم القيامة، وقال لعلي: لا تدع صورة إلا طمستها؛ فالأحاديث عامة، ويُحمل ما عند عائشة من البنيّات أنها ما هي من الصور المعتادة، الصور اللي يصوِّرها المصوِّرون، خِرَق يَحُطُّون لها عودًا، يَحُطُّون فيه خرقًا، يحطون كذا، كأنها صورة.","link":"https://binbaz.org.sa/fatwas/28498/ما-حكم-صورة-الوجه-في لعب-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما حكم صورة الوجه في لعب الأطفال؟.mp3","categories":["الصور والتصوير"]},{"id":5037,"question":"الصور التي تُجعل للأطفال: بعض الناس يتوسَّع في هذا، وأصبح الآن ياشيخ أفلام فيها صور يا شيخ؟","title":"حكم الصور والأفلام التي تُجعل للأطفال","answer":"الجواب: الأحوط إتلافها، بعض أهل العلم يُجيزها؛ لأنها ممتهنة عند الأطفال، ويحتجون بقصة عائشة أنها قالت للنبي ﷺ لما ذكر لُعَبها وبناتها: \"إنَّ عندي لعبةً في صورة خيلٍ لها أجنحة\"، فضحك النبيُّ ﷺ وقال: خيلٌ لها أجنحة؟! احتجوا به، لكن هذا محمولٌ على أنه كان قبل النَّهي عنه، قبل المنع، أو الصور التي يفعلها الناسُ بأيديهم فليست هي حقيقية، يعبث بعضُ الناس يُصَلَّح خِرَقًا ويُصوِّرها ويُصوِّر القطن، ما هي بصورة هذه.","link":"https://binbaz.org.sa/fatwas/28970/حكم-الصور-والافلام التي-تجعل-للاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الصور والأفلام التي تجعل للأطفال.mp3","categories":["الصور والتصوير"]},{"id":5292,"question":"ما حكم بيع آلات التصوير وأفلامها؟","title":"ما حكم بيع آلات التصوير وتوابعها؟","answer":"الجواب: بيع آلات التصوير لا بأس بها؛ لأنها قد تستعمل للضرورة، وتصوير ما لا روح له كالشجر ونحوه، والتصوير الذي يحتاجه الناس للتابعيات وغيرها للضرورة، لكن لا يصور إلا ما فيه ضرورة، وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] كما يحتاجه أصحاب التوابع..... أو الشهادات العلمية..... صورة أو تصوير الجمادات من شجر أو أودية أو أحجار أو سيارات أو غير ذلك.[1]","link":"https://binbaz.org.sa/fatwas/30940/ما-حكم-بيع-الات-التصوير-وتوابعها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 012.mp3","categories":["الصور والتصوير"]},{"id":5614,"question":"اتّخاذ الصورة من دون تعليقٍ؟","title":"ما حكم اتّخاذ الصورة دون تعليقها؟","answer":"الجواب: الواجب إتلافها، إلا إذا كان من حاجةٍ: كصورةٍ يحتاجها في الجنسية، يضطر إليها.\nس: إذا صور مجموعة من الصور للرخصة، ثم أبقى بعضها يقول: ربما يحتاجها في المُعاملات؟\nج: الذي يظهر لي أنه ما يجوز إلا واحدة للضَّرورة.[1]","link":"https://binbaz.org.sa/fatwas/31582/ما-حكم-اتخاذ-الصورة-دون-تعليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 054.mp3","categories":["الصور والتصوير"]},{"id":5615,"question":"ألعاب الأطفال، هذه التي على شكل مجسمات صورة؟","title":"هل تدخل صور وألعاب الأطفال في المنهي عنها؟","answer":"الجواب: ألعاب الأطفال فيها خلاف: بعضهم يراها لا بأس بها؛ لأنه يُروى عن عائشة أنه كان عندها بعض اللعب، والأحوط ترك ذلك، الأحوط لا يبقي شيئًا من الصور، لا ألعاب ولا غيرها.\nس: جاء في الحديث: إلا رقمًا في ثوبٍ؟\nج: النقش، النقوش، الرقم بالنقش، ما هو بالصورة.\nس: الصور في ملابس الأطفال؟\nج: لا ينبغي.\nس: صور التلفاز؟\nج: هذه ما هي صور، هذه عارضة، ما هي ثابتة.\nس: لكن تُحفظ في شريط فيديو على شكل صورةٍ؟\nج: إن كانت تُرى ما يصلح، وإن كانت ما تُرى ما يضرّ.\nس: تُرى على الشاشة وبالفيديو؟\nج: هذه ما تُسمى صورة، إذا كانت ما تُرى في ثوبٍ، ولا في لباسٍ، ولا في قرطاسٍ، ولا في شيءٍ فلا بأس.\nس: متى يكون محرمًا...؟\nج: إذا كان للضَّرورة ويعرف أنها للضَّرورة؛ فلا بأس، وإلا فلا يُصور.\nس: صور التلفاز أليست من ذوات الأرواح؟\nج: الله أعلم.[1]","link":"https://binbaz.org.sa/fatwas/31584/هل-تدخل-صور-والعاب-الاطفال-في-المنهي-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al rawth_almuraba 055.mp3","categories":["الصور والتصوير"]},{"id":5738,"question":"التصوير التلفزيوني؟","title":"حكم التصوير التلفزيوني","answer":"الجواب:  هو من هذا الباب، قد يقال لعظم الفائدة، يعني: أنها مرجحة على الصورة من باب تفويت كبرى المفسدتين بارتكاب أدناهما، وأن يقاس على تصوير العاملين في المصانع، أو في الأشياء التي يحتاجها المسلمون، ويحصل لهم به الهداية، قد يقال: إن هذا من باب التعليم، فيغتفر ما فيه من التصوير لمصلحة كبرى لتعلم الأشياء التي لها أهمية.  أما كونه يصور المرأة، ويصور فلانًا، وفلانًا لخرافات، وأفلام، فهذا ما هو عذر شرعي، هذا ليس بعذر، في الصناعات في الطب في أشباه ذلك عند بعض أهل العلم من باب ارتكاب أدنى المفسدتين. أما التوسع في هذا في الدروس، أو في التلفاز، أو في غيره ما أعلم له وجهًا يوجب الإباحة؛ لأنهم توسعوا في هذا من دون عذر شرعي.","link":"https://binbaz.org.sa/fatwas/1052/حكم-التصوير-التلفزيوني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_69.mp3","categories":["الصور والتصوير"]},{"id":5743,"question":"مدرس علوم في إحدى المدارس الابتدائية يطلب من التلاميذ رسم لبعض الحيوانات على دفتر علومهم، فهل هذا مناف للدين الإسلامي؟","title":"رسم الطلاب للحيوانات في دراستهم","answer":"الجواب: هذا ما ينافي الدين الإسلامي، لكنه معصية، هذا ما هو كفر، رسم الصور محرم ومنكر، صور الحيوان، وصور الإنسان، البهيمة، الطائر لا يجوز، لكن تساهل الناس في هذا، ولا حول ولا قوة إلا بالله، حتى صار كأنه مباح لما توسع الناس صار التصوير كأنه مباح، ما صار لها قيمة عند الناس؛ لأنهم اعتادوا هذا، وكثر بينهم هذا في المجتمعات وغيرها، فصار كأنه شيء مباح، والنبي -عليه الصلاة والسلام- لعن آكل الربا وموكله، ولعن المصور وقال: أشد الناس عذابًا يوم القيامة المصورون.  لكن بعض العلماء تأول هذا على أن المراد الصور المجسمة ذات الظل، كأن يصورها من حديد، أو من خشب، أو من كذا أو من كذا على حيوان، ولكن هذا قول ضعيف مرجوح، والذي عليه عامة العلماء وأكثرهم أن التصوير يعم المجسم من الظل، ويعم غير المجسم وهو ما لا ظل له كالشمس، وما يكون في الخرق، وما يكون في الجدران وغير ذلك، هذا هو المعتمد عند الأكثر، فينبغي توقي هذا.  وبعض الناس تأول تأولًا آخر وقالوا: إن هذا ما صور إنما هو يحبس الصورة مثل الصورة في المرآة، يحبسها فهو ما صور، وإنما أمسك خلق الله بهذه الكاميرا، وقالوا ما صور، وهذا فيما يظهر لي تأويل لا وجه له، فالتصوير محرم سواء بالكاميرا، أو بغير الكاميرا، فلا يليق فعل ذلك أبدًا. السؤال: أنا برضه مدرس علوم، وبعدين المنهج طبعته كدا، مثلًا أرسم السمكة حتى أرسم الشيء الذي هو داخل السمكة، الجهاز الهضمي، الجهاز الدوري، التنفسي، حتى نبين للطالب مكان كل عضو فما الطريقة ؟ الجواب: يمكن أن يستعان على هذا بأجزاء مقطعة، مثل اليد يعني يعلمه، مثل الطبيب يعلمه كل عضو. السؤال: مثل الضفادع؟ الجواب: ما يجوز قتل الضفادع، لكن ميتة، أو شيء مباح قتله مثل السمك، يأخذها من الماء فتموت، مثل الشاة البعير يذبحه، ثم يعلم على أجزائه ما يصور، يعلم على أجزائه، وصوره يصور الأجزاء على قطع قطع حتى لا يكون صورة قائمة.","link":"https://binbaz.org.sa/fatwas/1056/رسم-الطلاب-للحيوانات-في-دراستهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_73.mp3","categories":["الصور والتصوير"]},{"id":5881,"question":"يوجد في بعض المكاتب صور بعض الزعماء، والملوك مبروزة، هل هذه الصور يجوز في هذه المكاتب أن توضع؟","title":"حكم تعليق صور الملوك والزعماء","answer":"الجواب:  هذه الصور مما لا يجوز، وقد نبه ولاة الأمور على ذلك، ونسأل الله لهم التوفيق، فنصب الصور في المكاتب، والدوائر لا يجوز ذلك، ويخشى أن يكون ذلك وسيلة للشرك؛ لأن كثيرًا من الدول غير المسلمة ينصبون هذه الصور في الميادين، في المحلات التي يريدون، ويخشى منها أن يقع فيها الشرك بعد حين، كما فعل قوم نوح.   قوم نوح جاءهم الشيطان لما مات خمسة صالحون، وكانوا على التوحيد، فلما مات فيهم خمسة من الصالحين، وهم: ود، وسواع، ويغوث، ويعوق، ونسرًا، دس عليهم الشيطان لما رأى حزنهم، وبكاءهم عليهم دس عليهم الشيطان، وقال: صوروا صورهم، وانصبوها في مجالسهم حتى تذكروا عباداتهم، وتذكروا أعمالهم، فصورها، ثم طالت حتى عبدوهم من دون الله، نسأل الله السلامة. فيخشى من هذه الصور أن يطول الأمد، أن تعبد من دون الله، ولاسيما مع الجهل الكثير في الناس، ولاسيما مع حب الدنيا، والحرص على التقرب إليها بكل وسيلة.  فالذي نعتقد: أن هذا لا يجوز نصب هذه الصور في المكاتب، ولا في الدوائر، ولا في الميادين، والواجب على ولاة الأمور إزالتها، ونسأل الله أن يوفقهم لذلك، وأن يعينهم على كل خير، وأن يوفقهم لما فيه صلاح العباد، والبلاد.","link":"https://binbaz.org.sa/fatwas/1206/حكم-تعليق-صور-الملوك-والزعماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_202.mp3","categories":["الصور والتصوير","قضايا معاصرة"]},{"id":5888,"question":"يوجد في بعض المكاتب صور بعض الزعماء، والملوك مبروزة، هل هذه الصور يجوز في هذه المكاتب أن توضع؟","title":"حكم تعليق صور الملوك والزعماء","answer":"الجواب:  هذه الصور مما لا يجوز، وقد نبه ولاة الأمور على ذلك، ونسأل الله لهم التوفيق، فنصب الصور في المكاتب، والدوائر لا يجوز ذلك، ويخشى أن يكون ذلك وسيلة للشرك؛ لأن كثيرًا من الدول غير المسلمة ينصبون هذه الصور في الميادين، في المحلات التي يريدون، ويخشى منها أن يقع فيها الشرك بعد حين، كما فعل قوم نوح.   قوم نوح جاءهم الشيطان لما مات خمسة صالحون، وكانوا على التوحيد، فلما مات فيهم خمسة من الصالحين، وهم: ود، وسواع، ويغوث، ويعوق، ونسرًا، دس عليهم الشيطان لما رأى حزنهم، وبكاءهم عليهم دس عليهم الشيطان، وقال: صوروا صورهم، وانصبوها في مجالسهم حتى تذكروا عباداتهم، وتذكروا أعمالهم، فصورها، ثم طالت حتى عبدوهم من دون الله، نسأل الله السلامة. فيخشى من هذه الصور أن يطول الأمد، أن تعبد من دون الله، ولاسيما مع الجهل الكثير في الناس، ولاسيما مع حب الدنيا، والحرص على التقرب إليها بكل وسيلة.  فالذي نعتقد: أن هذا لا يجوز نصب هذه الصور في المكاتب، ولا في الدوائر، ولا في الميادين، والواجب على ولاة الأمور إزالتها، ونسأل الله أن يوفقهم لذلك، وأن يعينهم على كل خير، وأن يوفقهم لما فيه صلاح العباد، والبلاد.","link":"https://binbaz.org.sa/fatwas/1206/حكم-تعليق-صور-الملوك-والزعماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_202.mp3","categories":["الصور والتصوير","قضايا معاصرة"]},{"id":6029,"question":"هذا بعض المدرسين في درس العلوم، يأمروا الطلاب أن يصوروا ذوات الأرواح من الدجاج، والبعير؟","title":"حكم تصوير ذوات الأرواح من أجل التعليم","answer":"الجواب: لا، التصوير ما يجوز لا للصغار، ولا للكبار، النبي ﷺ لعن المصورين، وتوعد المصورين بالنار، وأخبر أنهم أشد الناس عذابًا يوم القيامة، فلا يجوز التصوير، لا من الطلبة، ولا من غير الطلبة.","link":"https://binbaz.org.sa/fatwas/1435/حكم-تصوير-ذوات-الارواح-من-اجل-التعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_372.mp3","categories":["الصور والتصوير","مسائل متفرقة في العقيدة"]},{"id":6037,"question":"هذا بعض المدرسين في درس العلوم، يأمروا الطلاب أن يصوروا ذوات الأرواح من الدجاج، والبعير؟","title":"حكم تصوير ذوات الأرواح من أجل التعليم","answer":"الجواب: لا، التصوير ما يجوز لا للصغار، ولا للكبار، النبي ﷺ لعن المصورين، وتوعد المصورين بالنار، وأخبر أنهم أشد الناس عذابًا يوم القيامة، فلا يجوز التصوير، لا من الطلبة، ولا من غير الطلبة.","link":"https://binbaz.org.sa/fatwas/1435/حكم-تصوير-ذوات-الارواح-من-اجل-التعليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_372.mp3","categories":["الصور والتصوير","مسائل متفرقة في العقيدة"]},{"id":6072,"question":"كثر في هذه الأيام الصور المجسمة على بعض العمائر، ومنها: صورة الأسد من شعار ساعات، أورينت، شمال هذا المسجد، وغيره فما حكم ذلك؟","title":"حكم الصور المجسمة من الحيوانات","answer":"الجواب: لا يجوز اتخاذ الصور، لا من الحيوانات البهيمية، ولا من بني آدم، لا على البيوت، ولا على غير البيوت، كالأبواب، وأشباه الأبواب، بل يجب النهي عن هذا، النبي ﷺ قال: لا تدع صورة إلا طمستها ونهى عن الصور في البيت، أو يصنع ذلك، فلا يجوز أن تعلق الصور على الجدران، لا مجسمة، ولا غير مجسمة، يجب النهي عن هذا، ولا بدّ أن يبلغ ولاة الأمور عن المنكر هذا، لا بدّ أن يبلغ ولاة الأمور، ونسعى في إزالة هذا الشيء  .. نسأل الله أن يعين الجميع.","link":"https://binbaz.org.sa/fatwas/1483/حكم-الصور-المجسمة-من-الحيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_413.mp3","categories":["الصور والتصوير","مسائل متفرقة في العقيدة"]},{"id":7396,"question":"حكم لُعب الأولاد التي على شكل حيوانات؟","title":"حكم ألعاب الأطفال التي على شكل حيوانات","answer":"الجواب: هذه فيها خلاف بين أهل العلم، لعب الأطفال منهم من أجاز ذلك، ومنهم من حرم ذلك، والأحوط للمؤمن ألا يتخذ الصور المعروفة المجسدة التي يتعاطها الأطفال، ينبغي له ألا يتخذها وأن يعوضهم الصور العادية التي يفعلها الناس قبل ذلك، في أعواد عود يحطون فيه شيء أو أشباه ذلك مما ليس له صورة مجسدة تشبه الصور التي لعن الرسول من فعلها، يعني صورًا عادية ليس فيها الصورة التي يصدق عليها الحديث، صورة كاملة في رأس وعين وأنف ونحو ذلك، كذا العرب سابقًا يجعلون أعوادًا أو عظامًا يجعل عليهم ثيابًا وعودًا معترضًا كأنه يديه، هذه أشياء لا تشبه الصورة.  أما الصورة الموجودة الآن فهي واضحة في التشبيه بخلق الله، فبعض أهل العلم منع ذلك ولو في حق الأطفال، وبعض أهل العلم سوغ ذلك في حق الأطفال؛ لأنه ثبت أنه كان عند عائشة -رضي الله عنها- بنات يعني لعب وهي عند النبي -عليه الصلاة والسلام- فأقرها عليها.","link":"https://binbaz.org.sa/fatwas/3500/حكم-العاب-الاطفال-التي-على-شكل-حيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1804.mp3","categories":["الصور والتصوير","مسائل متفرقة في العقيدة"]},{"id":7415,"question":"حكم لُعب الأولاد التي على شكل حيوانات؟","title":"حكم ألعاب الأطفال التي على شكل حيوانات","answer":"الجواب: هذه فيها خلاف بين أهل العلم، لعب الأطفال منهم من أجاز ذلك، ومنهم من حرم ذلك، والأحوط للمؤمن ألا يتخذ الصور المعروفة المجسدة التي يتعاطها الأطفال، ينبغي له ألا يتخذها وأن يعوضهم الصور العادية التي يفعلها الناس قبل ذلك، في أعواد عود يحطون فيه شيء أو أشباه ذلك مما ليس له صورة مجسدة تشبه الصور التي لعن الرسول من فعلها، يعني صورًا عادية ليس فيها الصورة التي يصدق عليها الحديث، صورة كاملة في رأس وعين وأنف ونحو ذلك، كذا العرب سابقًا يجعلون أعوادًا أو عظامًا يجعل عليهم ثيابًا وعودًا معترضًا كأنه يديه، هذه أشياء لا تشبه الصورة.  أما الصورة الموجودة الآن فهي واضحة في التشبيه بخلق الله، فبعض أهل العلم منع ذلك ولو في حق الأطفال، وبعض أهل العلم سوغ ذلك في حق الأطفال؛ لأنه ثبت أنه كان عند عائشة -رضي الله عنها- بنات يعني لعب وهي عند النبي -عليه الصلاة والسلام- فأقرها عليها.","link":"https://binbaz.org.sa/fatwas/3500/حكم-العاب-الاطفال-التي-على-شكل-حيوانات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1804.mp3","categories":["الصور والتصوير","مسائل متفرقة في العقيدة"]},{"id":7508,"question":"هذه رسالة من المرسلات: ليلى وريماء القاضي تقول المستمعة ليلى وريماء: ما حكم جمع الصور من أجل الذكرى فقط؟","title":"لا يجوز التصوير للذكرى","answer":"الجواب: التصوير لذوات الأرواح محرم ولا يجوز عند أهل العلم، سواء كان ذا الروح إنساناً أو بهيمة أو طيراً، كله لا يجوز؛ لقول النبي ﷺ في الحديث الصحيح: أشد الناس عذاباً يوم القيامة المصورون وقال عليه الصلاة والسلام: كل مصور في النار الحديث، وقال: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ فالأحاديث صريحة في تحريم التصوير لذوات الأرواح من بني آدم وغيرهم، فلا يجوز التصوير لا للذكرى ولا لغير الذكرى، ليس للمسلم أن يصور ولده أو زوجته أو أقاربه للذكرى، بل ذلك منكر ولا يجوز، لكن قد يعفى عن الرجل يصور عند الحاجة والضرورة مثل التابعية، مثل رخصة القيادة؛ قيادة السيارات، مثل أشباه ذلك مما تدعو الضرورة إليه، وليس له مندوحة من ذلك ولا يستطيع السلام من ذلك؛ لأن الدولة تلزم بذلك، فهذا وأشباهه لا بأس للضرورة والحاجة الملحة، وهو في حكم المكره في هذه الأشياء، في حكم المكره، لا حرج عليه إن شاء الله، ولكن لا ينبغي أن يتخذ الصور يعني للتلذذ بها، أو للذكرى، أو للعبث، أو للتساهل بذلك، أو ما أشبه هذا، لا، كل هذا منكر لا يجوز؛ لكن للضرورة لا حرج إن شاء الله، مثل ما تقدم؛ مثل التابعية... ما تيسر له التابعية إلا بالصورة، ما تيسر له قيادة السيارة إلا بالصورة، مثل مريض، ما تيسر له العلاج إلا بالصورة، فهو كالمكره في هذه الأحوال. نعم.","link":"https://binbaz.org.sa/fatwas/4469/لا-يجوز-التصوير-للذكرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_008/00807.mp3","categories":["الصور والتصوير"]},{"id":7614,"question":"هذه الرسالة من ياسين البوزان من سوريا من مدينة حلب يقول فيها: ما حكم تعليق الصور الفوتوغرافية على الجدران، وهل يجوز تعليق صورة الأخ أو الأب أو ما شاكلهما؟","title":"حكم تعليق الصور الفوتوغرافية على الجدران","answer":"الجواب: تعليق الصور ذوات الأرواح على الجدران أمر لا يجوز، سواء كان ذلك في بيت أو مجلس أو مكتب أو شارع أو غير ذلك، كله منكر، وكله من عمل الجاهلية، والرسول ﷺ قال: أشد الناس عذاباً يوم القيامة المصورون وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال:أحيوا ما خلقتم وبعث علياً  قائلاً له لا تدع صورة إلا طمستها، ولا قبراً مشرفاً إلا سويته ونهى عن الصور في البيت وأن يصنع ذلك. \nفالواجب طمسها ولا يجوز تعليقها، ولما رأى في بيت عائشة صورة معلقة في الستر غضب وتغير وجهه، وهتكها عليه الصلاة والسلام، فدل ذلك على أنه لا يجوز تعليق الصور سواء كانت صور الملوك أو الزعماء أو العباد أو العلماء أو الطيور أو الحيوانات الأخرى، كله لا يجوز، كل ذي روح تصويره محرم، وتعليق صورته في الجدران أو في المكاتب كله محرم، ولا يجوز التأسي بمن فعل ذلك، والواجب على أمراء المسلمين وعلى علماء المسلمين وعلى كل مسلم أن يدع ذلك وأن يحذر ذلك، وأن يحذر منه طاعة لله ولرسوله عليه الصلاة والسلام، وعملاً بشرع الله في ذلك، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/4667/حكم-تعليق-الصور-الفوتوغرافية-على-الجدران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_023/02303.mp3","categories":["الصور والتصوير"]},{"id":7854,"question":"هذه الرسالة وردتنا من جدة من المملكة العربية السعودية يقول: محمد عبد الله الدعجاني ، المكرم سماحة الشيخ: عبد العزيز بن عبد الله بن باز المحترم! السلام عليكم ورحمة الله وبركاته، وبعد: يا سماحة الشيخ! لنا سؤال نرجو الإجابة عليه عن طريق نور على الدرب، يقول: إن مجموعة من الناس مجتمعون في زواج وقام البعض يريد أن يصور العريس وبعض الجالسين، فاعترضه البعض الآخر وقال: إنه لا يجوز التصوير، وطال الكلام بينهم ولا يمكن إلا أن صور الجالسين جميع عناد وتكبر منه عندما سمع أنه حرام، فنرجو التوضيح في ذلك، وفقكم الله؟","title":"حكم التصوير في الأعراس","answer":"الجواب: هذا لا يجوز، لا يجوز أن يصور الناس لا برضاهم ولا بغير رضاهم، وإذا كان بغير رضاهم صار أكبر في الإثم، فالتصوير محرم لذوات الأرواح لبني آدم أو غيرهم من ذوات الأرواح، لأن الرسول ﷺ لعن المصورين، وقال: كل مصور في النار يجعل له بكل صورة صورها نفس يعذب بها في جهنم، وقال عليه الصلاة والسلام: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ، فالحاصل أن التصوير محرم لذوات الأرواح، فلا يجوز لإنسان أن يصور الجالسين في العرس لا رجل ولا امرأة، ليس له أن يصورهم ولو رضوا؛ لأن التصوير منكر؛ ولأن هذا يفضي إلى عرض نساء عاريات أو شبه عاريات يعني غير متحجبات، أو شبه عاريات بسبب تساهلن في الملابس وظهور الرءوس، وظهور الوجه، وظهور الأذرع وغير ذلك، فالحاصل أنه لا يجوز، التصوير منكر ومحرم وفيه فساد فيما يتعلق بتصوير .... النساء في الزواج، فإنهن يتجملن ويتزين، فإذا صورهن فقد سعى في الفتنة بعرض هذه الصور على الناس، ويجب أن يشكى إلى المحكمة أو إلى إمارة البلد حتى يؤدب عن تعاطي هذا الأمر. نعم.","link":"https://binbaz.org.sa/fatwas/5268/حكم-التصوير-في-الاعراس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_055/05505.mp3","categories":["الصور والتصوير"]},{"id":7855,"question":"أيضاً يقول في رسالته: السؤال الثاني هو: عند اجتماع العروس بالعريس في المنصة المعدة لهما بين النساء الحاضرات، تقوم إحدى النساء أو أحد الرجال يصور العروس والعريس معاً، وتكون قريبة منهم، وبعض العرسان يكون قليل الحياء فيمسك بالزوجة ويسلم عليها بين أهل الحفل والمصور يصور بهذه الحالة، وأيضاً يرجو التعليق منكم على ذلك؟","title":"حكم تصوير العروسين","answer":"الجواب: هذا أقبح من الذي قبله، هذا لا يجوز أيضاً؛ لأن هذا يسبب فتنة وربما أفضى إلى شر كثير بالزوجة المصورة والزوج المصور، فالحاصل أن هذا لا يجوز، التصوير منكر، ولا يجوز لذوات الأرواح لما تقدم من الأحاديث الصحيحة عن رسول الله عليه الصلاة والسلام، ومنها قوله: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم، وقوله ﷺ: كل مصور في النار، يجعل له بكل صورة صورها نفس يعذب بها في جهنم، فالحاصل أن التصوير منكر، وفي هذه الحالة أشد نكارة، أن يصور العروس والزوج وربما صور من حولهما من النساء، وربما صورها وهو يسلم عليها أو يقبلها؛ لأن بعض الأزواج لا يبالي ولا يستحي، هذا كله منكر والواجب أن يؤدب هذا المصور أو هذه المصورة تأديباً يردعهم وأمثالهم عن هذا العمل السيئ، وينبغي لأصحاب البيت أو لغير أصحاب البيت ممن له غيرة أن يرفع هذا إلى إمارة البلد أو إلى المحكمة حتى يعاقب من فعل هذا الشيء، حتى يكون عبرة لغيره. نعم.","link":"https://binbaz.org.sa/fatwas/5269/حكم-تصوير-العروسين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_055/05506.mp3","categories":["الصور والتصوير"]},{"id":7876,"question":"أيضاً يقول: يوجد بعض البطانيات وعلب الحليب وكل الأغراض اللازمة والأشياء التي ندخلها في بيوتنا فيها صور هل ترفض هذه الأشياء من أجل صورها أم لا؟","title":"حكم الصور الموجودة في الأغراض المستعملة داخل البيت","answer":"الجواب: لا. يعفى عنها؛ لأنها ممتهنة الفراش ممتهن، الوسادة ممتهنة، وحق الصلصة الذي هو قوطي الصلصة يمتهن يلقى في القمامة فلا يضر إن شاء الله؛ لأن هذا ممتهن. نعم.\nالمقدم: شكراً أثابكم الله!","link":"https://binbaz.org.sa/fatwas/5349/حكم-الصور-الموجودة-في-الاغراض-المستعملة-داخل-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_057/05707.mp3","categories":["الصور والتصوير"]},{"id":8132,"question":"سؤالها الثاني تقول: ما تفسير هذا الحديث -في الحقيقية هي تسأل عن التصوير ويأتينا رسائل كثيرة جداً جداً وللمشائخ أيضاً إجابات كثيرة- تقول: ما تفسير هذا الحديث: كل مصور في النار، يجعل له بكل صورة صورها نفس فتعذبه في جهنم، ما تفسيره وفقكم الله؟","title":"معنى حديث : (كل مصور في النار)","answer":"الجواب: هذا على ظاهره يدل على تحريم التصوير وأنه لا يجوز، وأن المصور يعذب بالصور التي صورها في جهنم، وهذه الصور التي فعلها عذاباً عليه يوم القيامة، وفي الحديث الآخر: أشد الناس عذاباً يوم القيامة المصورون، وفي الحديث الثاني: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم، هذا نوع من التعذيب بها، والتصوير للحيوانات التي ذات الأرواح كالإبل والغنم البقر وبني آدم والطيور، أما تصوير ما لا روح له كالجبل والسيارة والشجرة، فلا حرج في ذلك، واختلف علماء العصر في التصوير الشمسي هذا المعروف الموجود بالكاميرة، فبعضهم قال: إنه ليس بتصوير وإنما هو إمساك الظل وتسامح في ذلك، والمعروف عند أهل العلم والبصيرة التحقيق أنه تصوير وأنه لا يجوز، وأن حكمه حكم التصوير باليد الفني المعروف، هذا التصوير لا يجوز لذوات الأرواح، إلا من حاجة من ضرورة كالتابعية، أو تصوير الجناة الذين يخاف شرهم، أو قيادة السيارة للحاجة، فهذا إذا دعت الحاجة إليه، ولم يتيسر له أخذ تابعية أو رخصة إلا بالصورة، فنرجو أن لا حرج عليه للضرورة.\nالمقدم: شكراً لفضيلة الشيخ عبد العزيز بن عبد الله بن باز .","link":"https://binbaz.org.sa/fatwas/5940/معنى-حديث-كل-مصور-في-النار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_088/08809.mp3","categories":["الصور والتصوير"]},{"id":8176,"question":"أخونا عبد الله عوض العازمي من عفيف بعث بخمسة أسئلة سماحة الشيخ.سؤاله الأول يقول: ما حكم تجميع الصور الفوتوغرافية لذوات الأرواح للذكرى؟","title":"حكم الاحتفاظ بالصور للذكرى","answer":"الجواب: لا يجوز جمع الصور ذوات الأرواح للذكرى بل يجب إتلافها لأن الرسول عليه الصلاة والسلام قال لـعلي : لا تدع صورة إلا طمستها ولما ثبت في حديث جابر عند الترمذي وغيره أن النبي ﷺ نهى عن الصور في البيت وأن يصنع ذلك فجميع الصور التي للذكرى تتلف بالتمزيق أو الإحراق وإنما يحتفظ بالصورة التي لها ضرورة كالتابعية الصورة التي في التابعية وما أشبه ذلك مما يكون هناك ضرورة لحفظه وإلا في الواجب إتلافها. نعم.","link":"https://binbaz.org.sa/fatwas/5983/حكم-الاحتفاظ-بالصور-للذكرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_105/10504.mp3","categories":["الصور والتصوير"]},{"id":8252,"question":"رجل عنده استديو؛ دكان فيه آلات التصوير، وعلم أن التصوير حرام؛ فكيف يتصرف فيها بحيث يمكنه التجنب من الخسارة، وإذا باعها على مسلم أليس يكون ذلك مساعداً على نشر المعصية؟ وما حكم ما يأتيه من كسب ذلك من المال هل يجوز صرفه عليه وعلى أهله؟","title":"الواجب على من يملك استديو تصوير ثم علم بتحريمه","answer":"الجواب: هذا فيه تفصيل: فإن الاستديو يصور الجائز والممنوع، فإذا صور فيه ما هو جائز من السيارات والطائرات والجبال وغير ذلك من أشجار وغير هذا من كل ما ليس فيه روح فلا بأس أن يبيع ذلك ويصور هذه الأشياء التي قد يحتاجها الناس وليس فيها روح، أما تصوير ذوات الأرواح من بني الإنسان أو الدواب أو الطيور فلا، وإذا صور فيها شيء يحتاجه الناس يضطرون إليه كالتابعية التي يحتاجها الناس في حفيظة النفوس فلا بأس.\nفالمقصود: أنه لا يشتغل فيه إلا الشيء الجائز، وإذا باعه على الناس فلا بأس ببيعه؛ لأنه يباع ويستعمل في الطيب وفي الخبيث مثلما يبيع الإنسان السلاح.. يبيع السيف.. يبيع السكين، والسكين تستعمل في الخير والشر، وهكذا السلاح، فهو غير مسئول عن هذا الشيء إلا إذا كان يعلم أن المشتري يضر به الناس لا يبيع عليه لا سلاحاً ولا غيره، أما إذا كان لا يعلم إنما هو في السوق العامة التي ليس فيها علم بمن يستعمله في الشر أو في الخير فلا يضره ذلك، والإثم على من استعمله في الشر.","link":"https://binbaz.org.sa/fatwas/6066/الواجب-على-من-يملك-استديو-تصوير-ثم-علم-بتحريمه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/09807.mp3","categories":["الصور والتصوير"]},{"id":8256,"question":"رجل شريك في دكان لآلات التصوير وقد تاب، فكيف ينهي شراكته فيه بحيث لا يخسر وما حكم ما يأتيه من كسب هذا الدكان؟","title":"حكم المال المكتسب من محل تصوير","answer":"الجواب: مثل ما تقدم؛ ينهيه بالتقويم، يقوم عليه ويتصالح هو وياه على القيمة التي يرضاها الشخصان جميعاً، وما دخل عليه من ذلك فهو مباح له؛ إلا إذا كان من قيمته تصوير ذوات الأرواح فيتأمل يقدر قسطها ويتصدق بها على بعض الفقراء، قسط ما صور به ذوات الأرواح من المصورات الأخرى، فيقدر الربع أو الثلث أو أكثر أو أقل مما دخل عليه ثم ينفقه في وجوه الخير براءة للذمة وبعداً عن الحرام.\nالمقدم: طيب، بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6067/حكم-المال-المكتسب-من-محل-تصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_098/098008.mp3","categories":["الصور والتصوير"]},{"id":8285,"question":"إذاً ننتقل إلى رسالة أخينا حيدر عبد الله أبو دياب من السودان. أخونا يقول: هل يجوز للمرأة أن تخطب في جمع من الناس فيه رجال ونساء، وبواسطة مكبرات الصوت باسم الدين، وتصوير تلك الندوة كما يسمونها بأفلام الفيديو، ويتم توزيعها داخل وخارج البلد، وكل ذلك باسم الدين؟ وهل في الإسلام قاعدة اسمها: الغاية تبرر الوسيلة؟","title":"حكم محاضرة المرأة للرجال وتصوير المحاضرة","answer":"الجواب: هذه الخطبة لا حرج فيها، كون المرأة تخطب الناس وتذكر الناس وإن كان فيهم رجال، لا مانع من ذلك بالصوت العادي، لا بالخضوع ولا بصوت آخر منكر كما قال جل وعلا: يَا نِسَاءَ النَّبِيِّ لَسْتُنَّ كَأَحَدٍ مِنَ النِّسَاءِ إِنِ اتَّقَيْتُنَّ فَلا تَخْضَعْنَ بِالْقَوْلِ فَيَطْمَعَ الَّذِي فِي قَلْبِهِ مَرَضٌ وَقُلْنَ قَوْلًا مَعْرُوفًا [الأحزاب:32].\nفإذا كانت الخطبة قولاً معروفاً ليس فيه شيء مما يعتبر خضوعاً في القول، والمقصود النصيحة، فقد نصح الصحابيات وغير الصحابيات نصحوا الرجال ونصحوا النساء، والله يقول سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، ويقول سبحانه: وَمَنْ أَحْسَنُ قَوْلًا مِمَّنْ دَعَا إِلَى اللَّهِ وَعَمِلَ صَالِحًا [فصلت:33] وهذا يعم الرجال والنساء جميعاً، فإذا خطبت وذكرت ودعت إلى الله فلا بأس بذلك بشرط الصيانة والبعد عن الخلوة بأي رجل من غير محارمها، ومع الحجاب، كل هذا لا بأس به.\nأما التصوير فهذا هو الذي ينكر، فإنها لا تصور إلا إذا كان تصويرها وهي مستورة متحجبة في وجهها وكل شيء هذا لا يضر تصويرها، لكن جنس التصوير ينبغي ألا يفعل في هذه المسائل، بل ينبغي أن يسجل سماعاً من دون صورة؛ لأن الصورة أصلها ممنوع ومحرم كما قال النبي ﷺ: أشد الناس عذاباً يوم القيامة المصورون فلا حاجة إلى التصوير، ولا حاجة إلى تصويرها ولكن يسجل الكلام، تسجل الخطبة والموعظة وينفع الله بها من يشاء من دون حاجة إلى التصوير. نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: نعم.","link":"https://binbaz.org.sa/fatwas/6093/حكم-محاضرة-المراة-للرجال-وتصوير-المحاضرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_100/10006.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":8360,"question":"لدينا صور فوتوغرافية كثيرة، وأكثرها صور للعائلة والأصدقاء، وأنا محتفظ بها من أمد طويل للذكرى، فهل أنا آثم على جمعها؟","title":"حكم الاحتفاظ بالصور الفوتوغرافية للذكرى","answer":"الجواب: نعم، عليك أن تتلفها وتزيلها، ولا تحتفظ بها؛ لقول النبي ﷺ: لا تدع صورة إلا طمستها ولأنه نهى عن الصور في البيت عليه الصلاة والسلام.\nفينبغي لك أن تتلفها ولا حاجة إلى الذكرى بالصور، يكفي ذكر أقاربك وأصحابك بالقلب، لا حاجة إلى الصور، هداك الله ووفقنا وإياك.","link":"https://binbaz.org.sa/fatwas/6209/حكم-الاحتفاظ-بالصور-الفوتوغرافية-للذكرى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_113/11317.mp3","categories":["الصور والتصوير"]},{"id":8391,"question":"المقدم: أخونا -سماحة الشيخ- بعث بقصاصة من إحدى المجلات، وسماها، وفيها فتاوى، ويسأل رأيكم عما في تلك الفتاوى، هل نعرضها سماحة الشيخ؟الشيخ: نعم. هنا في مجلة اليقظة، سماها، الأختان الفاضلتان نهى الطاهر وغالية الغرياني تقولان:أولاً: سمعنا أن بعض العلماء رفض الخروج من بلده، حتى لا يضطر إلى التقاط صورة له، لوضعها في جواز السفر، فلماذا تضع صورتك في المجلة؟ثانياً: جاء في الحديث: لأن يطعن أحدكم بمخيطٍ في رأسه، خير له من أن يمس امرأةً لا تحل له فهل هذا الحديث صحيح؟ثالثاً: ما حكم سماع الغناء؟هذه الأسئلة، والفتاوى تقول:قلت مستعيناً بالله تعالى: أولاً: المحرم بلا خلاف إنما هو الصور المجسمة -التماثيل- أما الرسوم والتصوير الفوتوغرافي ففيهما خلاف بين العلماء، والراجح قول القائلين بالإباحة، وذلك بالنظر إلى مجموع الأدلة الواردة في المسألة، وقد فصلت ذلك في أكثر من عدد من المجلة.لكم تعليق على هذه الفتوى سماحة الشيخ؟","title":"حكم التصوير المجسم والفوتوغرافي","answer":"الجواب: هذا المفتي صادق في أن الصور ........ التي لها ظل وهي المجسمة قد أجمع العلماء على تحريمها، وصادق في أن التصوير الشمسي فيه خلاف؛ لكن كون الراجح الجواز. ليس هذا هو الصواب، الراجح هو المنع والتحريم، وهو قول جماهير أهل العلم، كما ذكر ذلك النووي وغيره، جمهور أهل العلم على المنع، من التصوير الشمسي كالتصوير الذي له ظل، فلا يجوز التصوير الشمسي، لا في الملابس، ولا في القرطاس، ولا في غير ذلك؛ لأن الأحاديث عامة عن النبي ﷺ، كلها تدل على تحريم التصوير، يقول ﷺ: أشد الناس عذاباً يوم القيامة المصورون وهذا عام، وثبت في الصحيح عنه ﷺ أنه: لعن آكل الربا، وموكله،، والواشمة، والمستوشمة، والمصور ولم يستثن مصوراً دون مصور، ولما رأى ستراً عند عائشة فيه تصاوير غضب وهتكه، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم خرجه مسلم في صحيحه.\nومعلوم أن الصور التي في الستر، هي من جنس الصور الشمسية، إنما هي أصباغ، ومع هذا غضب لما رآها ﷺوهتك الستر، فهذا يدل على تحريم التصوير مطلقاً، وكذلك قوله ﷺ: لا تدع صورة إلا طمستها عام، ولما دخل الكعبة رأى في جدرانها صور،، فأخذ ماءً وثوباً فمحاها عليه الصلاة والسلام، ومعلوم أن الصور في الجدران، من جنس الصور الشمسية، ومع هذا محاها صلى الله عليه وسلم، وبين أن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم هذا كله يدل على تحريم التصوير مطلقاً، إلا من علة، كالتصوير الذي يضطر أصحاب المسئولية عن المجرمين، حتى يعرفوا المجرمين، حتى يطاردوهم، لمصلحة المسلمين.\nكذلك تصوير الإنسان عند الحاجة لحفيظة النفوس، إذا لم يتيسر له ذلك إلا بها، ولن يعطى حفيظة إلا بها، فهو مضطر لذلك، أما التصوير من حيث الجملة فهو محرم، هذا هو الأصل. نعم.\nالمقدم: بارك الله فيكم. وبالنسبة لجواز السفر، سماحة الشيخ كحفيظة النفوس؟\nالشيخ: كذلك إذا لم يتيسر إلا بهذا..\nالمقدم: فهو كذلك؟","link":"https://binbaz.org.sa/fatwas/6257/حكم-التصوير-المجسم-والفوتوغرافي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11610.mp3","categories":["الصور والتصوير"]},{"id":8488,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول: معالي أختنا الواقع تثير قضية لعل الكثير من الناس شاهدها، تلكم هي وضع ألعاب للأطفال بالفول والأرز والعدس وأشياء أخرى من نعم الله، تستخدم في عمل وسائل إيضاح أيضاً، مثل الخرائط أو غيرها ومن ثم صبغها بألوان فهل ذلك جائز، كذلك إذا استخدمت في الرسوم وترجو التوجيه سماحة الشيخ؟","title":"حكم الرسوم التوضيحية في المأكولات أو لعب الأطفال","answer":"الجواب: الذي يظهر لي من هذا أنه لا يجوز؛ لأن ذلك أمر فيه استهانة بهذه النعم، وفيه أيضاً إضاعة للمال بلا حاجة، فهو جامع لإضاعة المال والاستهانة بهذه النعم التي في الإمكان الانتفاع بها في غير هذا الشيء، هذا هو الأظهر لي والأقرب لي والله أعلم. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6547/حكم-الرسوم-التوضيحية-في-الماكولات-او-لعب-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12602.mp3","categories":["الصور والتصوير"]},{"id":8504,"question":"أختنا تسأل تقول: هل لها أن تدخل في مجلس عليه صور وليس لها الحق في نزعها؟","title":"حكم دخول الأماكن التي فيها صور","answer":"الجواب: نعم، إذا كان لها حاجة، فيه حاكم يقضي، فيه باعة يبيعون ويشترون، تشتري منهم حاجاتها ما يضرها، أما إذا كان ما لها حاجة فعدم الدخول أولى، أما إذا كان هناك حاجة؛ لأنه في محل بيع وشراء في محل حلقة علم، في محل قاضي محتاجين إلى الدخول عليه، محل أمير يحتاجون إلى رفع شكواهم إليه إذا كانت لحاجة لا بأس.","link":"https://binbaz.org.sa/fatwas/6572/حكم-دخول-الاماكن-التي-فيها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_127/12704.mp3","categories":["الصور والتصوير"]},{"id":8609,"question":"يسأل في رسالته ويقول: زوجتي مقيمة معي في السعودية وتريد أن ترسل صورتها لوالدتها بمصر لتطمئن عليها، وقد سمعت فتوى بأن التصوير بآلات التصوير حرام، فهل هذا من الضرورات التي تبيح المحظورات؟","title":"حكم إرسال المغترب صوره لأقاربه","answer":"الجواب: ليس هذا من الضرورات، ليس لها أن ترسل صورتها إلى أمها ولا إلى غير أمها، وليس هذا ضرورة، تكاتبها تكلمها بالهاتف والحمد لله، أما إرسال الصورة فلا تجوز ....... نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6750/حكم-ارسال-المغترب-صوره-لاقاربه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_210/21016.mp3","categories":["الصور والتصوير"]},{"id":8680,"question":"وهذه رسالة وردتنا من السائلة هدى علي محمد من اليمن الجنوبي محافظة لحج، تقول في رسالتها: هل يجوز للفتاة المصلية أن تنطب حاجبيها -هكذا كتبت- رغم أني شابة مصلية وأؤدي الصلاة في أوقاتها، ولي صديقة تؤدي الصلاة وتنطب حاجبيها، وقد قلت لها: إن هذا حرام، فقالت: لا، ليس حراماً لأن الحاجب زينة المرأة، فهل هي مخطئة أم مصيبة، أفيدوني أفادكم الله؟","title":"حكم أخذ شعر الحاجبين","answer":"الجواب: الحاجبان لا يجوز نتفهما ولا نقشهما بالمنقاش، الرسول ﷺ: لعن النامصة والمتنمصة قال أئمة اللغة: النمص: أخذ شعر الحاجبين، فلا يجوز أخذ شعر الحاجبين ولا نتف شعر الوجه لا بالمنقاش ولا بغيره؛ لأنه مثلة فلا يصلح، فإن كانت تقصد السائلة بالنطب غير هذا الشيء فلا نعرف النطب ما هو، لكن نبين لها أن أخذ الحاجبين، يعني: شعر الحاجبين بالمنقاش أو بغيره هذا لا يجوز، وهكذا شعر الوجه المعتاد ليس لها أخذه.\nأما لو نبت لها لحية أو نبت لها شارب فهذا مثلة لها أن تأخذ هذا؛ لأنه يشوه خلقتها، فقد ذكر العلماء أنه لا بأس بأخذ الشارب أو اللحية التي تنبت للمرأة، أما شعر الحاجبين لا. لا تأخذ شعر الحاجبين لا تنتفه لا بالمنقاش ولا بغيره؛ لأن الرسول ﷺ: لعن النامصة والمتنمصة والنمص: هو أخذ شعر الحاجبين، وهكذا شعر الوجه المعتاد الذي ليس فيه تشويه لا يؤخذ. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6818/حكم-اخذ-شعر-الحاجبين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_215/21505.mp3","categories":["الصور والتصوير"]},{"id":8798,"question":"السؤال الثاني يقولون فيه: فينا من يحب فن الرسم، وهو يرسم مراراً، فنريد أيضاً معرفة موقف الإسلام من الرسم؟ وكذلك من الألعاب الرياضية وخاصةً كرة القدم، أفيدونا أفادكم الله؟","title":"حكم الرسم والتصوير","answer":"الجواب: الرسم له معنيان: أحدهما: رسم الصور ذوات الأرواح، هذا جاءت السنة بتحريمه، فلا يجوز الرسم الذي هو رسم ذوات الأرواح؛ لقول النبي ﷺ في الحديث الصحيح: كل مصور في النار، وقوله ﷺ: أشد الناس عذاباً يوم القيامة المصورون الذين يضاهون بخلق الله؛ ولقوله ﷺ: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم؛ ولأنه ﷺ: لعن آكل الربا وموكله ولعن المصور، فدل ذلك على تحريم التصوير، وقد فسر العلماء ذلك: بأنه تصوير ذوات الأرواح من الدواب والإنسان والطيور.\nأما رسم ما لا روح فيه وهو المعنى الثاني، فهذا لا حرج فيه كرسم جبل والشجر والطائرة والسيارة وأشباه ذلك هذا لا حرج فيه عند أهل العلم.\nويستثنى من الرسم المحرم ما تدعو الضرورة إليه، مثل رسم صور المجرمين حتى يحذروا وحتى يمسكوا، أو صور صاحب حفيظة النفوس التي لابد منها، ولا يستطيع الحصول عليها إلا بذلك، فهو معذور لأنه بحاجة إلى حفيظة النفوس، وهكذا ما تدعو الضرورة إليه، فإذا رأى ولي الأمر أن هذا الشيء تدعو الضرورة إلى تصويره لخطورته، ولقصد سلامة المسلمين من شره حتى يعرف، أو لأسباب أخرى فلا بأس، قال الله : وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119]. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/6950/حكم-الرسم-والتصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_221/22103.mp3","categories":["الصور والتصوير"]},{"id":8838,"question":"في جدران غرفتي من الداخل توجد بعض من اللوحات المرسومة باليد، وهي مختلفة الأشكال، في ذات يوم نظر إليها أحد الشيوخ فقال لي: أنزلهن جميعًا، فقلت: ما السبب؟ قال: اسأل من هو أدرى مني، ولكن أعرف أنها تقلل الرحمة من المنزل، أرجو إفادتي أفادكم الله؟","title":"حكم تعليق الصور على الجدران","answer":"الجواب: هذا شيء فيه التفصيل، إن كانت اللوحات هذه فيها صور فقد صدق من قال لك: أنزلها، فالصور لا تعلق ولا يجوز تعليقها، وقد أزالها النبي ﷺ من جدران الكعبة، لما دخل الكعبة عام الفتح فوجد فيها صور في الجدران محاها بالماء عليه الصلاة والسلام ومسحها بثوب حتى أزالها، وكسر الأصنام التي حول الكعبة، ولما جاء من سفر في بعض الأحيان ورأى عند عائشة سترًا على بعض حجرها هتكه وغضب، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم.\nفقوله ﷺ: إن أصحاب هذه الصور يعذبون يدل على تحريم بقاء الستور واللوحات التي فيها الصور، بل يجب أن تزال.\nأما إن كانت الألواح ما فيها إلا آيات أو أحاديث عن النبي ﷺ صحيحة أو أشعار طيبة، فلا حرج في ذلك.\nالقول الصواب: أنه لا حرج في ذلك، أن يعلق لوح فيه آيات أو أحاديث صحيحة أو كلمات طيبة من باب التذكير للداخل، ومن باب التذكير للجلساء ليستفيدوا ليس هناك قصد سوى هذا فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/6993/حكم-تعليق-الصور-على-الجدران","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_165/16508.mp3","categories":["الصور والتصوير"]},{"id":8886,"question":"من السودان هذه الرسالة باعثها أحد الإخوة يقول (ع. أ. ع) أخونا يقول: سمعت بأن الملائكة لا تدخل منزلًا فيه صور أو كلب، أرجو أن تشرحوا لي هذا، وإذا كان الكلب يحتاج إليه صاحب الدار فما الحكم؟","title":"حكم تعليق الصور وإدخال الكلاب البيت","answer":"الجواب: نعم، صح عن رسول الله ﷺ أنه قال: لا تدخل الملائكة بيتًا فيه صورة ولا كلب هكذا جاء في الحديث الصحيح، والصورة التي تمنع هي الممنوعة كالتي تنصب على الجدران وعلى أبواب البيوت وكالمجسمة التي توجد في البيت مجسمة صورة إنسان أو حيوان أو طير هذه تمنع دخول الملائكة ولا يجوز تعليقها ولا نصبها في البيت؛ لقول النبي ﷺ لـعلي : لا تدع صورة إلا طمستها ولأنه ﷺ لما رأى على باب عائشة ... بعض غرفها سترًا فيه صورة هتكه وغضب وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم فدل ذلك على أن الصور لا تعلق في الجدران ولا تنصب إذا كانت ذات جسم لا تبقى في البيت بل يجب أن تزال؛ لأنها محرمة والواجب إزالتها؛ ولأنها تمنع من دخول الملائكة، فيجب أن تزال، وقال أيضًا عليه الصلاة والسلام: أشد الناس عذابًا يوم القيامة المصورون وثبت عنه ﷺ: أنه لعن المصورين.\nفوجب الحذر من ذلك ومع وجود الصور في المحل يجب أن يقضى عليها بالكسر والإزالة حتى يتم أمر الله فيها وينفذ فيها أمر رسوله عليه الصلاة والسلام، حيث قال: لا تدع صورة إلا طمستها، ولا قبرًا مشرفًا إلا سويته.\nلكن إذا كانت الصورة في محل يمتهن مثل البساط والوسائد والأرض التي تخطط فيها الصورة هذه لا تمنع لأنها مهانة، وقد ثبت عن رسول الله عليه الصلاة والسلام أنه لما أنكر على عائشة ذلك الستر قالت عائشة: جعلته وسادتين يرتفق بهما النبي ﷺ وثبت من حديث أبي هريرة عند النسائي وغيره أن النبي ﷺ واعد جبرائيل فتأخر عليه فخرج ينتظره فقال له جبرائيل وافاه جبرائيل وقال له: إن في البيت تمثالًا وسترًا فيه تصاوير وإن فيه كلبًا، فأمر برأس التمثال أن يقطع وأمر بالستر أن يتخذ منه وسادتان منتبذتان توطآن، وأمر بالكلب أن يخرج، قال: ففعل النبي صلى الله عليه وسلم ذلك -أي: فعل ما قاله جبرائيل فقطع رأس التمثال وأمر بجعل الستر وسادتين وأخرج الكلب وجدوا جروًا عند في ... لهم للحسن أو الحسين فأخرجوه- فلما نفذ النبي ﷺ ما قال جبرائيل دخل جبرائيل فدل ذلك على أن الصورة التي في الستر الذي يعلق تمنع من دخول الملائكة، ومثلها الصورة المنصوبة في مرآة في الجدار أو مجسمة في البيت كل هذه تمنع ومحرمة لا تجوز.\nأما ما كان في الأرض أو في الوسائد أو في البسط التي توطأ وتمتهن فإن هذا لا يمنع من دخول الملائكة، وهكذا الكلب الذي لا مسوغ له هو الذي يمنع من دخول الملائكة، أما إذا كان له مسوغ مثل كلب الصيد .. كلب الماشية .. كلب الزرع هذا لا يمنع؛ لأنه مأذون فيه، وما أذن الله به لا يمنع الخير، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/7043/حكم-تعليق-الصور-وادخال-الكلاب-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_167/16704.mp3","categories":["الصور والتصوير"]},{"id":8915,"question":"السؤال الثاني: في رسالة الأخت (أ. م) من المنطقة الشرقية الخبر تقول فيه: في منزلنا توجد التصاوير، وأنا أعلم أن المنزل الذي توجد فيه تصاوير لا تدخله الملائكة، وأعرف الأحاديث عن ذلك، وقلت للأهل وأكرر، لكني أواجه منهم المعارضة وقد غضبوا، فهل أكون آثمة بعد ذلك مع العلم أن الغرفة التي أجلس فيها ليس فيها أي صورة، وجهوني جزاكم الله خيرًا، ولا سيما عن حكم الصلاة في ذلكم المكان الذي فيه صور، هل تكون صحيحة أو لا؟","title":"حكم تصوير ذوات الأرواح","answer":"الجواب: الحكم مثل ما ذكرت، الصور محرمة وهي صور ذوات الأرواح من بني آدم أو من الحيوانات الأخرى أو من الطير كلها محرمة؛ لقول النبي ﷺ: أشد الناس عذابًا يوم القيامة المصورون متفق على صحته، ولما رأى سترًا عند عائشة فيه تصاوير معلقة على بعض أبوابها، غضب عليه الصلاة والسلام وهتك الستر وقال: «إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم»، وقال عليه الصلاة والسلام: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ، وقال عليه الصلاة والسلام أيضًا لـعلي : لا تدع صورة إلا طمستها لما بعثه إلى المدينة: لا تدع صورة إلا طمستها ولا قبرًا مشرفًا إلا سويته، وثبت عنه ﷺ أيضًا: أنه لعن آكل الربا وموكله، والواشمة والمستوشمة، ولعن المصور، واللعن يدل على شدة الخطر وأنها من الكبائر العظيمة، أن هذا التصوير من الكبائر العظيمة.\nوأنت جزاك الله خيرًا قد نصحت الأهل وأنكرت المنكر فقد أحسنت في هذا، وهذا هو الواجب عليك وعلى أمثالك؛ لقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ [التوبة:71]، فدل على أن الواجب لا يختص بالرجال بل هو عام للرجال والنساء، هذا هو الواجب في إنكار المنكر والأمر بالمعروف، يعم الجميع.\nوهكذا قوله ﷺ: من رأى منكم منكرًا فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه وذلك أضعف الإيمان خرجه الإمام مسلم في صحيحه، وهذا أيضًا يعم الرجال والنساء، فإن لم يستجيبوا لك فأنت معذورة، ولكن عليك أن تستمري في النصيحة، ولا تملي ولا تيأسي، وعليك أن تشجعي من فيه الخير من أهلك على مساعدتك في ذلك، وهكذا من ترين فيه الخير من الأقارب تحثينه على إنكار هذا المنكر، وإذا كانت غرفتك سليمة فالحمد لله، ونرجو أن تدخلها الملائكة؛ لأنها سليمة.\nوالصلاة في المحل الذي فيه صور صلاة صحيحة، لكن فعلها في غير محل الذي فيه الصور يكون أولى وأفضل؛ لأن الصور قد تشوش على المصلي، وقد تشغله عن صلاته؛ ولأن الصلاة في المحل المعلق فيه الصور فيه نوع تشبه من عباد الأصنام، نوع تشبه بعباد الأصنام، فأقل الأحوال في ذلك الكراهة، لكن الصلاة صحيحة، وعليك أن تستمري في النصيحة، ونسأل الله لأهلك الهداية والتوفيق.\nويستثنى من هذا ما تدعو الضرورة إليه فإن الإنسان غير ممنوع منه، كالذي يحتاج إلى التابعية، ولا يعطى إياها إلا بالصورة فإنه يعفى عنه في هذا للضرورة، إذا كان في حاجة إلى التابعية -يعني: الحفيظة- ولم يتيسر أخذها إلا بصورة؛ فإنه يعفى عنه للحاجة، وهكذا ما أشبه ذلك كالشهادة العلمية التي لا تحصل له إلا بذلك، ومثل: شهادة قيادة السيارات؛ فإن الناس بحاجة إلى هذه القيادة، فإذا لم تتيسر الرخصة إلا بهذا فلا حرج، ومثل: تصوير المجرمين المعروفين بالإجرام؛ ليعرفوا حتى يقبض عليهم وحتى ينفذ فيهم حكم الله أينما وجدوا.\nوإذا قطع الرأس أو محي الرأس من الصورة زال حكمها؛ لما ثبت عند النسائي وغيره من حديث أبي هريرة  عن النبي ﷺ أنه وعده جبرائيل بأن يزوره فأبطأ عليه، فخرج عليه الصلاة والسلام إلى خارج البيت ينظر مجيئه، فصادفه وقال: ما منعك يا جبرائيل أن تدخل؟ قال: إن في البيت كلبًا وتمثالًا وصورة في ستر فسأله النبي ﷺ: ماذا يفعل؟ فقال: اقطع رأس التمثال حتى يكون كهيئة الشجرة، ومر بالستر أن يتخذ منه وسادتان منتبذتان توطآن، ومر بالكلب أن يخرج، ففعل النبي ﷺ ما قاله جبرائيل ، فوجدوا الكلب جروًا تحت نضد في البيت للحسن أو الحسين فأخرج وقطع الستر وجعل وسادتين، وقطع رأس التمثال فدخل جبرائيل عليه الصلاة والسلام. فهذا يدل على أنه إذا كانت الصورة في شيء يمتهن كالبساط والوسادة، أو كانت بلا رأس قد زيل رأسها بكلية وأزيل ما يكفي الخط بين الرأس والبدن، لابد بإزالته بالكلية أو مسحه بالكلية حتى لا يبقى له صورة فإنه إذا زال الرأس يعفى عن بقية الجثة، ولا تمنع دخول الملائكة. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7072/حكم-تصوير-ذوات-الارواح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_170/17002.mp3","categories":["الصور والتصوير"]},{"id":8939,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمعة (هـ. ف. م) من المنطقة الشرقية أختنا تسأل مجموعة من الأسئلة من بينها سؤال يقول: ما حكم الصلاة بالملابس المطبوع عليها صور؟","title":"حكم الصلاة بالملابس المطبوع عليها صور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالصلاة في الملابس التي فيها صور من صور الحيوانات لا تجوز؛ لأن الرسول ﷺ لما رأى عند عائشة رضي الله عنها سترًا فيه تصاوير غضب وهتكه، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم ولما رأى صورًا في جدران الكعبة محاها عليه الصلاة والسلام ونهى عن الصور في البيت وقال لـعلي: لا تدع صورة إلا طمستها ولا قبرًا مشرفًا إلا سويته.\nفالخلاصة: أنه لا يجوز للمؤمن ولا للمؤمنة الصلاة في ثوب فيه تصاوير، ولا يجوز أيضًا للمؤمنة أن تجعل لأولادها وأطفالها ملابس فيها تصاوير كل هذا لا يجوز، وإذا أزيل الرأس كفى، إذا جعل على الرأس رقعة خيط على الرأس رقعة تخفيه فلا بأس زال المحذور والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/7097/حكم-الصلاة-بالملابس-المطبوع-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_172/17201.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":8977,"question":"أخونا يسأل ويقول: ما حكم الاحتفاظ ببعض الصور لأناس ميتين؟","title":"حكم الاحتفاظ بصور ذوات الأرواح","answer":"الجواب: الصور يجب إتلافها، أعني صور بني آدم أو صور الحيوانات يعني صور ذي الروح، هذا لا يجوز الاحتفاظ به، هذه الصور لا يجوز الاحتفاظ بها بل يجب إتلافها؛ لقول النبي ﷺ: لا تدع صورة إلا طمستها، هكذا قال لـعلي ، وهكذا علي أوصى من بعده، أوصى أبا الهياج أن يفعل ذلك.\nوقال ﷺ: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم، ولما رأى صورة عند عائشة في ستر لها هتكه وقطعه، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم ، قالت عائشة: فاتخذنا منها وسادتين يرتفق بهما الرسول ﷺ، فإذا كانت الصور في وسادة أو في بساط هذا ممتهن لا بأس، يكون ممتهنًا محتقرًا لا بأس، أما صورة تحفظ في البيت لإنسان مات، أو لأطفال أو لزوج أو لغير ذلك فهذا لا يجوز بل يجب إتلافها. نعم.","link":"https://binbaz.org.sa/fatwas/7135/حكم-الاحتفاظ-بصور-ذوات-الارواح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_174/17402.mp3","categories":["الصور والتصوير"]},{"id":8992,"question":"لدي بعض الصور الفوتغرافية محتفظة بها في البوم، فهل في ذلك حرمة؟","title":"حكم الاحتفاظ بالصور الفوتغرافية","answer":"الجواب: نعم، ليس لك ولا لغيرك الاحتفاظ بالصور من ذوات الأرواح، سواء كانت صورة الزوج أو الولد أو الأب أو غيرهم؛ لقول النبي ﷺ لـعلي : لا تدع صورة إلا طمستها، ولأنه عليه السلام نهى عن الصور في البيت، ولما رأى صورة في ستر عند عائشة هتكه فغضب وقال عليه الصلاة والسلام: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم. نعم.","link":"https://binbaz.org.sa/fatwas/7150/حكم-الاحتفاظ-بالصور-الفوتغرافية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_176/17603.mp3","categories":["الصور والتصوير"]},{"id":9119,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ: طالب علم، يقول في رسالته وفي بدايتها:بسم الله الرحمن الرحيم، السلام عليكم ورحمة الله تعالى وبركاته.الشيخ: وعليكم السلام ورحمة الله وبركاته.السؤال الأول يقول فيه: هل هذه الأحاديث الآتية صحيحة أم لا، مع توضيح معنى الحديث لو تكرمتم، الحديث الأول: قال رسول الله ﷺ: إن الذين يضعون هذه الصور يعذبون يوم القيامة، يقال لهم: أحيوا ما خلقتم إذا كان هذا الحديث صحيح فما حكم الصور المتداولة بين الناس اليوم في الأسواق والمنازل والسيارات والصور المطلوبة في المدارس والجامعات وجميع الصور بأنواعها، وما هي الصور المحللة في الدين أفيدونا أفادكم الله؟","title":"النصوص الدالة على تحريم التصوير","answer":"الجواب: نعم هذا الحديث صحيح رواه البخاري رحمه الله في الصحيح وغيره عن عائشة رضي الله عنها، وفي الباب أحاديث أخرى، يقول فيها النبي ﷺ: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم.\nوكان سبب ذلك أنه ﷺ قدم من سفر فرأى على بيت فيه عائشة ستراً فيه تصاوير ثوباً فيه تصاوير فغضب وهتك الستر وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم وقال عليه الصلاة والسلام: أشد الناس عذاباً يوم القيامة المصورون وقال عليه الصلاة والسلام: كل مصور في النار يجعل له في كل صورة صورها نفس يعذب بها في جهنم.\nوقال أيضا عليه الصلاة والسلام: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ\nفهي دالة على تحريم تصوير ذوات الأرواح، من الدواب والطيور وبني الإنسان كل هذا ممنوع، إلا للضرورة فقد قال : وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119].\nالضرورة التي لا بد منها فلا حرج في ذلك مثل تصوير من يعطى حفيظة النفوس حتى يتبين هل هو من هذه الدولة أو من هذه الدولة، وحتى لا يشتبه بغيره وحتى لا تستعمل الرعوية لمن ليس من أهلها، فإذا وجدت الصورة لم يستطع غير صاحبها أن ينسبها إلى نفسه، وهكذا عند الحاجة الأخرى مثل أصحاب الجرائم المعروفين إذا صورهم ولاة الأمور ونشروا صورهم بين الحراس في أطراف البلاد حتى يعرفوهم ويمسكوهم أو ما أشبهه من الحاجات المهمة الضرورية العظيمة، فلا حرج في ذلك.\nوإلا فالواجب عدم التصوير وطمس الصور، ثبت في الصحيح عن علي  -أمير المؤمنين- عن النبي ﷺ أنه قال: لا تدع صورة إلا طمستها هكذا يقول النبي ﷺ لـعلي  لا تدع صورة إلا طمستها ولا قبراً مشرفاً إلا سويته خرجه مسلم في الصحيح.\nفهذا يدل على طمس الصور، وأنك إذا رأيت الصورة في بيتك تطمسها تزيلها سواء في جدار أو مستقلة محفوظة عند أهلك أو كذا تزيلها تطمسها تتلفها وهكذا القبور المشرفة تهدم، لا يبنى على قبر لا مسجد ولا قبة ولا غير ذلك.\nولهذا ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لعن الله اليهود والنصارى اتخذوا قبور أنبيائهم مساجد وقالت عائشة رضي الله عنها: يحذر ما صنعوا وقال عليه الصلاة والسلام: ألا وإن من كان قبلكم كانوا يتخذون قبور أنبيائهم وصالحيهم مساجد ألا فلا تتخذوا القبور المساجد فإني أنهاكم عن ذلك أخرجه مسلم في الصحيح عن جندب بن عبد الله البجلي .\nوثبت في الصحيح عن جابر رضي الله عنه قال: نهى رسول الله ﷺ عن تجصيص القبور والقعود عليها والبناء عليها فلا يبنى على القبر قبة ولا مسجد ولا حجرة، بل يكون مفتوحاً أمام السماء مثل قبور الصحابة في البقيع قبور المسلمين في البلاد السليمة من هذا البلاء، تكون مفتوحة مكشوفة يرفع القبر عن الأرض قدر شبر، ولا يبنى عليه شيء بل يكون مكشوفاً ليس عليه سقف ولا بناء.\nوهكذا قبور المسلمين ترفع من الأرض قدر شبر بالتراب الذي خرج من اللحد يكون فوق القبر حتى يعرف أنه قبر، حتى لا يوطأ ولا يمتهن ولا يبنى عليه قبة ولا مسجد ولا حجرة ولا غير ذلك، هكذا أمر النبي ﷺ، وهكذا حذرنا من التشبه بغيرنا.\nوأما الصورة التي في الفراش الذي يوطأ فلا حرج فيها لو كان في فراش يطؤه الناس فلا حرج في ذلك؛ لأنه ثبت عن رسول الله ﷺ: أنه رأى عند عائشة قراماً فيه تصاوير فهتكه، قالت عائشة رضي الله عنها: فجعلته وسادتين يرتفق بهما النبي ﷺ.\nفهذا يدل على أن الصورة التي تمتهن في الفراش والوسادة لا تمنع دخول الملائكة، لكن لا يجوز التصوير ليس لأحد أن يصورها في الفراش ولا في الوسادة ولا في الخرق، لكن لو جاءت إليك خرقه مصورة أو بساط مصور فلا بأس أن تجعله وسادة ولا بأس أن تجعل الفراش في بيتك تطؤه تجلس عليه لا حرج في ذلك والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/7283/النصوص-الدالة-على-تحريم-التصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_228/28808.mp3","categories":["الصور والتصوير"]},{"id":9195,"question":"أخونا أيضًا يسأل عن الفيديو والسينما وما حكم ذلك، ويسأل عن الموسيقى سماحة الشيخ؟","title":"حكم استعمال الفيديو والسينما وسماع الموسيقى","answer":"الجواب: هذه الآلات الفيديو والسينما فيها خطر عظيم، ولكن إذا كان الفيديو لم يشتمل إلا على أشرطة سليمة ليس فيها محذور شرعًا، لا نساء عاريات ولا أغاني وملاهي ولا غير ذلك، إنما هي أشرطة سليمة تنفع العبد في دنياه وأخراه فلا بأس، وهكذا السينما لو وجد شيء سليم ليس فيه ما يخالف الشرع المطهر لم يكن فيها بأس، ولكن لما كان المعروف من الناس الآن أن السينما تجمع شرًا كثيرًا، وهكذا الفيديو في الغالب يسجل فيه الأغاني والملاهي والنساء الكاسيات العاريات وشبه ذلك حرم ذلك.\nفالحاصل: أنها حرمت لما فيها من الشر ولما يكون فيها من الشر ويعرض فيها من الباطل، فلو وجد فيديو سليم أو سينما سليمة ليس فيها ما يخالف الشرع المطهر لم تحرم، ولكن بسبب ما يقع فيها من الشرور والفساد والصور العارية والاجتماع على الأغاني والملاهي حرمت بسبب ذلك، وهكذا الموسيقى؛ لأنها من آلات الملاهي فلا يجوز تعاطيها. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7355/حكم-استعمال-الفيديو-والسينما-وسماع-الموسيقى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_181/18105.mp3","categories":["الصور والتصوير","الشعر والأغاني"]},{"id":9225,"question":"السؤال الخامس والأخير في رسالة المستمع (ش. ل. ي) سوداني مقيم بالعراق، يقول فيه: ما هو الحكم في عملية التصوير بالكاميرا داخل البيت، أو في مناظر من الأشجار وتذكار بيني وبين الأسرة فقط، هل يجوز ذلك أم لا، أفيدونا أفادكم الله؟","title":"حكم تصوير مناظر الطبيعة","answer":"الجواب: التصوير في الأصل لذوات الأرواح أمر منكر، هذا هو الأصل، تصوير ذوات الأرواح من بني آدم ومن الحيوانات لا يجوز؛ لقول النبي ﷺ في الحديث الصحيح: أشد الناس عذاباً يوم القيامة المصورون وفي اللفظ الآخر يقول ﷺ: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم وروى جابر في الحديث الصحيح أن الرسول ﷺ: لعن آكل الربا، وموكله، ولعن المصور والأحاديث في هذا المعنى كثيرة، فالتصوير لا يجوز لذوات الأرواح.\nأما التصوير للشجر والجبل والسيارة والسفينة، فلا بأس بذلك، وهكذا إذا دعت الحاجة للصورة، مثل إنساناً يريد حفيظة نفوس ولا تحصل له إلا بالصورة فلا بأس للحاجة الشديدة، فهو مضطر، هكذا إذا رأى ولي الأمر تصوير المجرمين حتى ينقب عنهم، وحتى يتقى شرهم، أو لأسباب شرعية دعت الحاجة إلى ذلك لمصلحة المسلمين، فلا بأس بذلك. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7385/حكم-تصوير-مناظر-الطبيعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_233/23305.mp3","categories":["الصور والتصوير"]},{"id":9281,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلينا من السودان كسلة، باعثها أحد الإخوة من هناك يقول: أبو عمار محمد نور محمود، أخونا بدأ رسالته يقول: نحن جماعة أنصار السنة المحمدية بالسودان كسلة، لدينا جهاز فيديو استعملناه لتصوير المتأثرين بالجفاف والتصحر لإنفاق المحسنين عليهم، وقد أدى بالفعل دوره ورد عليهم أموالًا حسنت من أحوالهم من جميع الدول العربية، ثم استعملناه في نقل المحاضرات التي يقيمها الدعاة السلفيون من الجماعة والمحاضرات والمؤتمرات وأسابيع للعقيدة التي تقيمها الجماعة هناك نسبة لأن هذا الجهاز موجود في الأسر، لكن يستعمل في الشيء الفاسد، فبدأنا بتسليف المحاضرات للأسر التي بحوزتها هذا الجهاز لينتفعوا به وبالدعوة من خلال الأشرطة المسجلة، وسؤالنا: ما حكم الإسلام إذا عرض هذا الجهاز لتلك المحاضرات في وسط النساء وأنتم تعلمون أن المحاضر من الرجال، جزاكم الله خيرا؟","title":"حكم التصوير بالفيديو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فلا شك أن تسجيل المحاضرات والندوات العلمية من طريق الأشرطة فيه فائدة كبيرة ونفع كبير للناس؛ لأنهم يسمعون الصوت الذي يعرفون صاحبه فينتفعون بذلك أكثر من مجرد الشيء المكتوب، لكن ما يتعلق بالأفلام لأنها تشتمل على الصور، ينبغي عدم استعمال ذلك لعدم الحاجة إليه، فالشريط الذي يحفظ الصوت يحصل به الكفاية والحمد لله.\nوأما تصوير النساء في الأفلام فمضرته كبيرة وخطره عظيم فلا يجوز ذلك، وإنما يستعمل الشريط المعروف الذي يحفظ الصوت من دون صورة؛ لأنه يحصل به المقصود والحمد لله. نعم.\nالمقدم: بارك الله فيكم! يستعينون بهذا التصوير -سماحة الشيخ- على إيضاح الأحوال التي وصل إليها حال بعض الناس من المجاعة وقلة الأمطار؟\nالشيخ: هذا انتهى، هذا ذكروا أنه انتهى والحمد لله، فلا حاجة إلى بقائه بعد ذلك. نعم.\nالمقدم: لكن فيما إذا وجد في مناطق أخرى؟\nالشيخ: نرجو أن لا يكون هناك بأس ولكن ليس بضرورة؛ لأن وصف أحوال المتضررين بالكلام يكفي، فليس هناك ضرورة فيما أعتقد إلى التصوير، وإنما الكلام عنهم وبيان حاجاتهم وأنهم أصابهم كذا، وأصابهم كذا كاف إن شاء الله؛ لأن الوعيد في التصوير شأنه عظيم وخطير، والرسول ﷺ شدد في التصوير فلا يصار إليه إلا للضرورة القصوى، والنبي عليه الصلاة والسلام لعن آكل الربا وموكله، ولعن الواشمة والمستوشمة، ولعن المصور، وقال: أشد الناس عذابًا يوم القيامة المصورون هكذا قال عليه الصلاة والسلام، وقال أيضًا عليه الصلاة والسلام: كل مصور في النار يجعل له بكل صورة صورها نفس يعذب بها في جهنم فهذه تدل على شدة الوعيد وأن هذا من أعظم الكبائر، فلا يجوز أن يصار إليه إلا لضرورة لا حيلة فيها. نعم.\nالمقدم: بارك الله فيكم، إذًا والحالة هذه التصوير بالكلمة يغني؟\nالشيخ: يكفي. نعم.\nالمقدم: جزاكم الله خيرا.","link":"https://binbaz.org.sa/fatwas/7444/حكم-التصوير-بالفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18401.mp3","categories":["الصور والتصوير"]},{"id":9290,"question":"إحدى الأخوات المستمعات بعثت برسالة إلى البرنامج تقول فيه: مستمعة إلى البرنامج، هذا هو ما رمزت به إلى اسمها، ثم تقول في رسالتها: أنا طالبة في كلية الفنون الجميلة في السنة الثالثة، ودراستي في الكلية تحتاج إلى رسم الأشخاص، وقد علمت أن دراستي في هذه الكلية حرام بسبب الرسم والاختلاط، وذلك بعد أن التزمت بالزي الشرعي، وبناء على ذلك تركت الكلية؛ ولكن لم أخبر أهلي بذلك؛ لأنهم سوف يعارضون وأذهب في ميعاد الكلية إلى إحدى الأخوات لنقرأ ونتعلم علم الفريضة في أمور ديننا.وسؤالي: هل يجوز لي الكذب على أهلي في هذه الحالة أم هو إثم فعله مع العلم بأن الكلية تمنعنا من لبس النقاب، أرجو الإفاضة في هذا الموضوع؛ لأنه يقلقني جزاكم الله خيرا؟","title":"حكم الدراسة في كلية الفنون الجميلة","answer":"الجواب: قد أحسنت فيما فعلت ما دامت الكلية على ما ذكرت من الاختلاط وتصوير الأشخاص فقد أحسنت في تركها والاجتماع بالأخوات في الله لتعلم الدين والتفقه في الدين، وقراءة القرآن والأحاديث النبوية عن رسول الله عليه الصلاة والسلام، وقراءة كلام أهل العلم الموثوق بهم من أهل السنة والجماعة كل هذا طيب، ولا حرج في الكذب على أهلك حتى لا يلزموك بالكلية، وأنت بهذا بخير وعلى خير، والكذب إذا كان في مثل هذا لا يترتب عليه ضرر وإنما يحصل به إصلاح فلا بأس، يقول النبي ﷺ: ليس الكذاب الذي يقول خيرًا وينمي خيرًا وفي اللفظ الآخر: ليس الكذاب الذي يصلح بين الناس فيقول خيرا وينمي خيرًا.\nفالحاصل: أنه إذا كان الأمر كما قلت فلا حرج عليك في ذلك بل أنت محسنة ولك أجر كبير، ونسأل الله لك التوفيق على الحق والثبات عليه.\nالشيخ: اللهم آمين. سيكتشف الأهل ذلك، بم تنصحونها إذا حدث ذلك شيخ عبدالعزيز؟\nالشيخ: إن اكتشفوا فعليك بالبيان الوافي وأن هذا شيء يلزمك من جهة الدين، وأنه لا طاعة لمخلوق في معصية الخالق، يقول النبي ﷺ: إنما الطاعة في المعروف ويقول ﷺ: لا طاعة لمخلوق في معصية الخالق فليس للابن ولا للبنت أن يطيعا الأم أو الأب في معصية، وإنما الطاعة في المعروف، ولا ريب أن التصوير حرام وأن عدم الحجاب حرام عن الرجال الأجانب، والذهاب إلى الكلية يفضي إلى هذا وهذا. نعم.","link":"https://binbaz.org.sa/fatwas/7453/حكم-الدراسة-في-كلية-الفنون-الجميلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_184/18405.mp3","categories":["الصور والتصوير"]},{"id":9441,"question":"الأخ السائل (ن. ع) من حمص من سوريا في الحقيقة رجل غيور جزاه الله خيراً، فهو ذكر هنا عدة قضايا تتعلق باختلاف الفتوى في أمور هامة، ويذكر أنها في قضية مثل قضية الموسيقى والغناء، ويذكر أن مجلة عربية تصدر في بلد عربي أفتت بأنه لا يفتي بتحريم الغناء أو الموسيقى إلا متزمت جهول، ثم يسوق أيضاً ألواناً في أعداد مختلفة من هذه المجلة تبيح السفور المحتشم، هكذا قالت هذه المجلة في غير تبرج أو خلاعة، وأن الإسلام لا يدعو إلى الحجاب المتزمت الذي نراه في الكثير من البلاد العربية والبلاد الإسلامية، ثم يسوق أيضاً قضية حول مسألة التصوير، وأن هذه المجلة تشكك في الحديث الذي ورد في صحيح البخاري وتدعي أنه مدسوس في كتب الحديث، وما شأن المصورين حتى يكون عذابهم يوم القيامة أشد من القتلة أو من الزناة أو اللصوص، وإذا كان التصوير حراماً فلماذا لم ينه القرآن عنه صراحةً إلى غير ذلك، ويقول الأخ السائل: لماذا يسمح لمثل هذه المجلات بالتطاول على الإسلام، ويسأل عن الحكم الشرعي الصريح في هذه القضايا الثلاث؟","title":"بيان القول في حكم: الموسيقى والسفور والتصوير","answer":"الجواب: هذه المجلة وأشباهها ينبغي أن تمنع، وينبغي أن يقضى عليها؛ لأن هؤلاء المتكلمين فيها بهذا الكلام ليس عندهم علم ولا بصيرة ولا أدب شرعي، حتى الأدب الشرعي ليس عندهم أدب شرعي، هذه المسائل بينها أهل العلم وأقاموا عليها الدليل، فلا وجه للاعتراض من جاهل مركب لا درى ولا درى أنه ما درى، هذا جهل مركب أو متعمد للباطل والفسق، فالموسيقى والأغاني أمرهما معلوم، فالموسيقى من آلات الملاهي كالعود والطنبور والغناء من أخبث الملاهي فكلاهما محرم، والشعر العربي لا يدخل في ذلك، الأشعار العربية بلحون العرب فيما أباح الله، كشعر حسان وكعب بن مالك وغيرهما ممن بعدهم من الشعراء، على الطريقة العربية فيما أحل الله لا بأس به، أما الأغاني من النساء أو من أشباه النساء بالألحان والتطريب، وذكر حالات النساء من جمال وحب وغرام، هذا محرم عند أهل العلم، بل حكاه بعضهم إجماعاً، ولم يخالف فيه إلا من لا يعتد بخلافه، فالموسيقى وآلات الملاهي من العود والطنبور والرباب كلها محرمة وكلها شر، وهكذا الأغاني من النساء وغير النساء فيما يتعلق بالحب والغرام وذكر صفات النساء وما يتعلق بهذه الأمور، أو مدح الخمر أو مدح ما حرم الله كله محرم.\nوهكذا مسألة السفور منكر وقد دلت الأدلة على منعه، ومن ذلك قوله : وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53].\nفربنا  يأمر بالحجاب ويخبرنا أنه أطهر لقلوب الجميع، ويقول سبحانه في كتابه العظيم: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ [النور:31] إلى آخر الآية، فكيف يقال في هذا: أنه متزمت، وإنما هذا كلام إنسان لا يعقل، أو لا يستحي.\nفالحاصل: أن هذا منكر.. السفور منكر، لو قال: إن هناك بعض الأدلة تدل على إباحة السفور وترك القول بالتزمت لكان هذا من طريق أهل العلم، هناك من يقول بالسفور إذا كان لا يضر، أما سفور فيه الزينة والجمال وفيه وضع الأصباغ على الوجه ونحو ذلك فلا يبيحه أحد، بل هو منكر عند أهل العلم، وإنما أباح بعض الناس السفور الذي ليس معه زينة في الوجه لا كحل ولا أشياء من الزينة في الوجه، وهو قول ضعيف أيضاً ومرجوح، والصواب: أنه محرم، وأن الواجب الحجاب مطلقاً، ولو كانت لم تفعل شيئاً في الوجه من أنواع الزينة من أصباغ وكحل ونحو ذلك، فإن الوجه هو زينة المرأة وهو عنوانها، وقد كن يكشفن الوجه قبل الحجاب، فلما نزل الحجاب أمر الله النساء بالحجاب، وأمرهن النبي صلى الله عليه وسلم بالحجاب، وثبت في الصحيحين عن عائشة رضي الله عنها قالت: لما سمعت صوت صفوان -حين وجدها ليس عندها أحد- يقول: إنا لله وإنا إليه راجعون، قالت: فخمرت وجهي، وكان قد رآني قبل الحجاب فعرفني لما رآني، فلما سمعت صوته خمرت وجهي، فدل ذلك على أنهن قبل الحجاب يكشفن الوجه، وبعد الحجاب أمرن بستر الوجه مع عموم الآية التي تلونا سابقاً وهي قوله سبحانه: وَإِذَا سَأَلْتُمُوهُنَّ مَتَاعًا فَاسْأَلُوهُنَّ مِنْ وَرَاءِ حِجَابٍ [الأحزاب:53]، ولم يقل: إلا الوجه، ثم قال: ذَلِكُمْ أَطْهَرُ لِقُلُوبِكُمْ وَقُلُوبِهِنَّ [الأحزاب:53] ، وقال: وَلا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ [النور:31]، ولم يقل: إلا الوجه فلا بأس بإبدائه مطلقاً.\nفهذا الكلام الذي قاله صاحب المجلة كلام سقيم، كلام رديء لا ينبغي لعاقل أن يقوله.\nوأما التصوير فقد جاء فيه عدة أحاديث، ليست عند البخاري وحده، بل عند البخاري وعند مسلم وعند أهل السنن الأربعة، وعند الإمام أحمد في مسنده وعند مالك في موطئه، وعند الدارمي في سننه، رواها الأئمة بأسانيد صحيحة عن أبي هريرة وعن ابن عباس وعن عائشة وعن علي بن أبي طالب وعن جماعة آخرين، وعن أبي جحيفة كلها تدل على تحريم التصوير لذوات الأرواح، في الصحيحين من حديث عائشة ومن حديث ابن عباس: أشد الناس عذاباً يوم القيامة المصورون، وفي حديث عائشة أيضاً: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحييوا ما خلقتم، وفي حديث أبي جحيفة يقول : إن الرسول ﷺ لعن آكل الربا وموكله ولعن المصور، ويقول في حديث علي: لا تدع صورة إلا طمستها ولا قبراً مشرفاً إلا سويته، ويقول في حديث ابن عباس: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ، ويقول في حديث ابن عباس أيضاً عند الصحيحين عند البخاري ومسلم: كل مصور في النار ، يجعل له بكل صورة صورها نفس يعذب بها في جهنم.\nوالعلة في هذا والحكمة في ذلك معلومة، فإن الصور من وسائل الشرك، من وسائل عبادة غير الله، وكان النصارى إذا مات فيهم الميت الصالح بنوا على قبره مسجداً، وصوروا فيه صورته كما قاله النبي ﷺ ، وكانوا يصورون عظماءهم وينصبونها في الطرقات وفي كنائسهم وفي بيعهم، فهذا من وسائل العبادة لغير الله سبحانه وتعالى، ثم إذا كان المصور امرأة أو أمرد كان أيضاً من وسائل الفاحشة، من وسائل الفتنة، فالتصوير فيه فتنة وفيه شر عظيم، فلهذا حرمه الله ، فلا يجوز لعاقل أو لمسلم أن يقول: لماذا أو لماذا أو يعترض على شرع الله سبحانه وتعالى، بل يجب التسليم والانقياد لشرع الله، والطاعة لأمر الله ورسوله.\nهذا هو الواجب على كل مسلم، لكن ذكر بعض العلماء أنه يجوز التصوير عند الضرورة التي تدعو لهذا، مثل ما قد يضطر الإنسان إلى أخذ الحفيظة -حفيظة النفوس- التي تسمى التابعية إذا كانت الدولة لا تسمح بإعطائه إياها إلا بصورة فيكون مضطراً في هذه الحالة، وقد قال الله سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] أو إعطاء رخصة القيادة للسيارات إذا لم يعط رخصة إلا بصورة في دولته فهو مضطر إلى هذا الشيء، والله يعلم من قلبه أنه يكره الصور، فإذا أخذ ذلك مع كراهته لذلك إنما هو لأجل الإكراه والضرورة فلا حرج عليه في ذلك.\nالمقصود أن الاعتراض على شرع الله أمر لا يجوز وأمر منكر، بل يجب التسليم لشرع الله والبحث عما أشكل على الإنسان، إذا أشكل عليه أن يبحث، يسأل أهل العلم: ما حكمة كذا.. ما دليل كذا، والله المستعان ولا حول ولا قوة إلا بالله. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7606/بيان-القول-في-حكم-الموسيقى-والسفور-والتصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23907.mp3","categories":["الصور والتصوير","الشعر والأغاني"]},{"id":9509,"question":"أخيراً يسأل: ما هي أنواع الصور التي لا يجوز وجودها في البيوت؟","title":"أنواع الصور المحرم وجودها في البيوت","answer":"الجواب: الصور المنصوبة التي تنصب على الجدران أو على الأبواب أو تجعل في الستور التي على الأبواب أو الجدران، أو في براويز تجعل على الجدار هذه لا تجوز، أما إذا كانت الصورة في الفراش الذي يوطأ أو في السرر التي يجلس عليها أو الوسائد فلا حرج فيها؛ لأنها ممتهنة، وقد ثبت عنه ﷺ أنه رأى ستراً عند عائشة فيه تصاوير فغضب، وأمر بهتكه، فجعلت منه عائشة وسادتين كان يرتفق بهما عليه الصلاة والسلام، وثبت في حديث أبي هريرة عند النسائي وغيره أن جبرائيل عليه الصلاة والسلام كان له موعد مع النبي ﷺ، فلما حضر وجد في البيت تمثالاً وستراً فيه تصاوير وكلباً،لم يعلمه النبي ﷺ، فتوقف جبرائيل ولم يدخل حتى أخبره جبرائيل بذلك، فقال له: مر برأس التمثال أن يقطع، وبالستر أن يتخذ منه وسادتان منتبذتان توطأان وبالكلب أن يخرج، فأمر به النبي ﷺ فأخرج الكلب، كان تحت نضد للحسن أو الحسين، وأمر بالستر أن يتخذ منه وسادتان منتبذتان توطأان، وأمر بالتمثال أن يقطع رأسه، فدخل جبرائيل عليه الصلاة والسلام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7675/انواع-الصور-المحرم-وجودها-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24309.mp3","categories":["الصور والتصوير"]},{"id":9514,"question":"أخيراً يسأل: ما هي أنواع الصور التي لا يجوز وجودها في البيوت؟","title":"أنواع الصور المحرم وجودها في البيوت","answer":"الجواب: الصور المنصوبة التي تنصب على الجدران أو على الأبواب أو تجعل في الستور التي على الأبواب أو الجدران، أو في براويز تجعل على الجدار هذه لا تجوز، أما إذا كانت الصورة في الفراش الذي يوطأ أو في السرر التي يجلس عليها أو الوسائد فلا حرج فيها؛ لأنها ممتهنة، وقد ثبت عنه ﷺ أنه رأى ستراً عند عائشة فيه تصاوير فغضب، وأمر بهتكه، فجعلت منه عائشة وسادتين كان يرتفق بهما عليه الصلاة والسلام، وثبت في حديث أبي هريرة عند النسائي وغيره أن جبرائيل عليه الصلاة والسلام كان له موعد مع النبي ﷺ، فلما حضر وجد في البيت تمثالاً وستراً فيه تصاوير وكلباً،لم يعلمه النبي ﷺ، فتوقف جبرائيل ولم يدخل حتى أخبره جبرائيل بذلك، فقال له: مر برأس التمثال أن يقطع، وبالستر أن يتخذ منه وسادتان منتبذتان توطأان وبالكلب أن يخرج، فأمر به النبي ﷺ فأخرج الكلب، كان تحت نضد للحسن أو الحسين، وأمر بالستر أن يتخذ منه وسادتان منتبذتان توطأان، وأمر بالتمثال أن يقطع رأسه، فدخل جبرائيل عليه الصلاة والسلام. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7675/انواع-الصور-المحرم-وجودها-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_243/24309.mp3","categories":["الصور والتصوير"]},{"id":9613,"question":"هذه رسالة وردتنا من (عبدالرحمن . ف. ع) من الرياض، يقول: انتشر في هذه الأيام استعمال آنية الذهب والفضة، وخاصةً بين الموسرين من الناس، بل وصل الأمر عند بعضهم إلى أن يشتري أطقماً من المواد الصحية كخلاطات الحمامات أو المسابح، أو مواسير المياه أو مساكاتها، كلها من الذهب الخالص، ولا يزكون هذا الذهب، ولا ينظرون إلى قيمته والمعلوم أن هذا ممنوع، فما رأي سماحتكم في ذلك، وهل يمكن التوجيه بمنع بيع مثل هذه الأجهزة للمسلمين الذين يجهلون حكمها، بارك الله فيكم؟","title":"حكم استعمال آنية الذهب والفضة والتجارة فيهما","answer":"الجواب: الأواني من الذهب والفضة محرمة بالنص والإجماع، قد ثبت عن رسول الله عليه الصلاة والسلام أنه قال: لا تشربوا في آنية الذهب والفضة، ولا تأكلوا في صحافها، فإنها لهم في الدنيا ولكم في الآخرة وثبت أيضاً عنه ﷺ أنه قال: الذي يشرب فيي إناء الذهب والفضة إنما يجرجر في بطنه نار جهنم وفي لفظ آخر: الذي يأكل ويشرب في إناء الذهب والفضة إنما يجرجر في بطنه نار جهنم فالذهب والفضة لا يجوز استعمالها أواني، ولا الأكل فيها، ولا الشرب فيها، ولا الوضوء فيها، ولا الغسل فيها، هذا كله محرم، بنص الحديث عن رسول الله عليه الصلاة والسلام، والواجب منع بيعها حتى لا يستعملها المسلم، وقد حرم الله عليه استعمالها، فلا تستعمل في الشراب ولا في الأكل، ولا يجوز أن يتخذ منها ملاعق، ولا أكواب للشاهي، ولا أكواب للقهوة كل هذا ممنوع لأنها نوع من الأواني.\nفالواجب على المسلم: أن يحذر ما حرم الله عليه، وأن يبتعد عن الإسراف والتبذير، والتلاعب بالأموال، إذا كان عنده سعة من المال فعنده الفقراء يتصدق عليهم، عنده المجاهدون في سبيل الله كالمجاهدين .. الأفغان وغيرهم، يعطي في سبيل الله يتصدق لا يلعب بالمال، المال له حاجة، وله من هو محتاج.\nفالواجب على المؤمن أن يصرف المال في جهته الخيرية، في مواساة الفقراء والمحاويج، في تعمير المساجد والمدارس، في إصلاح الطرقات، في إصلاح القناطر، في مساعدة المجاهدين والمهاجرين الفقراء، في كل وجه من وجوه الخير، في قضاء دين المدينين العاجزين، في تزويج من لا يستطيع الزواج يعينهم، هذه طرق كلها خيرية، كلها من سبل السلام، من سبل الخير، أما التلاعب بها في أواني أو ملاعق أو أكواب أو مواصير، هذا كله منكر، يجب تركه والحذر منه، ويجب على من له شأن في البلاد التي فيها هذا العمل إنكار ذلك، من العلماء والأمراء، وأن يحولوا بين المسرفين، وبين هذا التلاعب، والله المستعان. نعم.\nالمقدم: بارك الله فيكم، الحقيقة -سماحة الشيخ- تأييداً لكلام السائل فقد كثر تساهل كثير من الناس، حتى في بلاد المسلمين، وأصبح الأمر عادياً عندهم، فيعمد إلى أن يشتري مثلاً أحواض للسباحة، أو شيء فيها، يعني: صنابير وخلاطات ماء من الذهب ...... قيمتها إلى عشرين وثلاثين ألف ريال.\nالشيخ: نسأل الله العافية، هذا منكر، لا شك منكر، ويجب على الدولة إنكار ذلك.\nالمقدم: وناقشنا بعض الباعة، يقولون: نحن نخبرهم أنه لا يجوز، وأنه حرام، وبهذا يرتفع الإثم هل هذا صحيح؟\nالشيخ: لا، يعينهم على الإثم، لا يبيعها لا يتولى بيعها، إذا جاءت للبيع يردها، يعطيه الله أبرك منها، لكن يقدم حاجته لأجل السعي، ولأجل الفلوس الذي يأخذها ولا يبالي، الله يقول: وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2] فلا يعين على ما حرم الله، ولو قال لهم: أن هذا لا يجوز لا يعين، لا يبيع عليهم، يقول لمن دفعها إليه: أنا لا أبيع هذه، ولا أتوسط في بيعها، وأبرأ إلى الله من هذا العمل، حتى يكون أعان على الخير، الله يقول: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى وَلا تَعَاوَنُوا عَلَى الإِثْمِ وَالْعُدْوَانِ [المائدة:2]. نعم.\nالمقدم: بارك الله فيكم، إذاً الحكم في المنع عام، لأن هناك من يقول: يقتصر على الأكل والشرب فقط؟\nالشيخ: لا، لا.\nالمقدم: في مقابض الأبواب والسيارات.\nالشيخ: نعم. من باب أولى..\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7771/حكم-استعمال-انية-الذهب-والفضة-والتجارة-فيهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_271/27104.mp3","categories":["الآنية","الصور والتصوير"]},{"id":9876,"question":"وهذه الرسالة وردت إلينا من عمر حامد أحمد مسعد من القاهرة في جمهورية مصر العربية يقول في رسالته: ما حكم الشرع في نحت الصور وتعليقها على الحيطان وتعليقها كمناظر في البيوت، ومع الأسف هي موجودة في شوارع كثير من المدن الإسلامية، إما صور زعماء أو صور عظماء، فما حكمها؟ بارك الله فيكم.","title":"حكم نحت صور الزعماء والقادة أو تصويرها بالكاميرا وتعليقها","answer":"الجواب: كل ذلك محرم، نحت الصور وتصويرها بالكاميرا أو بغير ذلك كل ذلك لا يجوز، كما لا يجوز نصبها في البيوت، ولا في المكاتب، ولا في الشوارع كل ذلك محرم، ووجودها في شوارع بعض الأمصار الإسلامية ليس بحجة، بل هو خطأ ممن فعله وغلط ممن فعله.\nوالواجب على حكام المسلمين إزالة ذلك، لقول النبي ﷺ: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم ولقوله ﷺ: كل مصور في النار، يجعل له بكل صورة صورها نفس يعذب بها في جهنم ولقوله عليه الصلاة والسلام: من صور صورة في الدنيا كلف أن ينفخ فيها الروح وليس بنافخ ولقوله عليه الصلاة والسلام أيضاً: أشد الناس عذاباً يوم القيامة المصورون.\nولأن الصور من أسباب الشرك والغلو، ولا سيما صور المعظمين، فقد يعبدون من دون الله، كما قد وقع في الجاهلية وكما قد وقع لقوم نوح لما صوروا وداً وسواعـاً ويغوث ويعوق ونسراً ، وكانوا رجالاً صالحين في قوم نوح ، فلما زين لهم الشيطان تصويرهم صوروهم، ثم عبدوا من دون الله بعد ذلك -ولا حول ولا قوة إلا بالله-.\nفالواجب على حكام المسلمين طمس هذه الصور وإزالتها، وعلى كل مسلم أن لا يبقي الصور في بيته، في مكتبه، ولا في مكتبته، وألا يعلقها في غرفته ولا في غير ذلك، لقول النبي ﷺ لا تدع صورة إلا طمستها، ولا قبراً مشرفاً إلا سويته رواه مسلم في الصحيح من حديث علي .\nولما روى الترمذي وغيره عن جابر  عن النبي ﷺ أنه: نهى عن الصورة في البيت، وأن يصنع ذلك.\nفالواجب على المسلمين جميعاً التعاون في هذا الأمر، وعلى حكام المسلمين أيضاً تنفيذ ما أمر به النبي عليه الصلاة والسلام، لكن إذا دعت الحاجة إلى هذا الشيء مثل المسلم الذي يحتاج إلى الرعوية الجنسية ولا يعطاها إلا بالصورة فلا حرج عليه لأنه كالمكره، وكذلك الدولة إذا رأت أن ذلك لا بد منه حتى لا تشتبه أمور الناس، وحتى يعرف الناس فيما عندهم من الحفائظ التي فيها صورتهم، إذا دعت الضرورة إلى هذا فلا حرج في ذلك للمصلحة العامة، ولقول الله : وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119].\nالمقصود أن الناس في هذه المسائل قد يضطرون إلى بعض الصور، فإذا دعت الضرورة إلى ذلك مثلما تقدم في الحفيظة يعني: التابعية الرعوية، أو مثل الشهادة العلمية إذا كانت مؤسسة لا تعطي الشهادة إلا بصورة فإنه مضطر إلى ذلك، وهكذا المجرمون إذا احتيج إلى تصويرهم حتى يعرفوا وحتى يمسكوا أينما كانوا، فهذه مسائل تدعو لها الضرورة ولا حرج في ذلك. نعم.\nالمقدم: أثابكم الله وبارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8036/حكم-نحت-صور-الزعماء-والقادة-او-تصويرها-بالكاميرا-وتعليقها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_263/26304.mp3","categories":["الصور والتصوير"]},{"id":9982,"question":"وهذا سعد أحمد محمد مرزوق من جمهورية مصر العربية الفيوم يعمل بالعراق، بعث إلينا بهذه الرسالة ضمنها بعض الأسئلة، يقول: أصلي في غرفة بها صور كصورة صديق لي معلقة على الحائط أو صورة إنسان آخر، وقد قال لي بعض الإخوة: إن صلاتك باطلة بسبب مقابلتك للصور أو استقبال هذه الصور، فكيف أفعل في المدة الماضية وما حكم صلاتي؟ بارك الله فيكم.","title":"حكم الصلاة في مكان فيه صور، وتعليق الصور","answer":"الجواب: لا، غلط، اللي قال لك: إنها باطلة غلط، الصلاة صحيحة، ولكن يكره الصلاة في هذه الحجرة إذا تيسر غيرها، وإلا فالصلاة صحيحة لأنك لا تعبد الصورة إنما صليت لله فصلاتك صحيحة، ولا يجوز نصب الصور في الحجر، نصب الصور في المكاتب والحجر لا يجوز الواجب إزالتها، فعليك أن تنصح أخاك أن يزيل هذه الصور المعلقة وألا يبقيها في البيت، يقول النبي ﷺ: لا تدخل الملائكة بيتاً فيه صورة ولا كلب ويقول ﷺ: لا تدع صورة إلا طمستها ولا قبراً مشرفاً إلا سويته هكذا قال نبينا ﷺ لـعلي : لا تدع صورة إلا طمستها ولا قبراً مشرفاً إلا سويته ولما رأى ستراً عند عائشة رضي الله عنها فيه تصاوير هتكه وغضب عليه الصلاة والسلام، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم.\nفأنت تنصح أخاك حتى يزيل الصورة المعلقة، وأما الصلاة فصحيحة، ولكن يكره الصلاة في المحل الذي فيه التصاوير إلا عند الحاجة، إذا ما تيسر غيره فلا بأس. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/8142/حكم-الصلاة-في-مكان-فيه-صور-وتعليق-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_274/27412.mp3","categories":["الصور والتصوير"]},{"id":10233,"question":"رسالة وصلت إلى البرنامج من المستمع محمد أحمد عسيري من محايل عسير، ضمنها أربعة أسئلة في أحد أسئلته يقول: ما حكم اقتناء الأواني المطلية بطلاء الذهب، أو الأواني التي يعتقد أنها مصنوعة من فضة؟ وهل يجوز الشرب فيها، أم لا؟ وهل يجوز اقتناء الأواني المطلية بماء الذهب في البيت لمجرد الزينة؟","title":"حكم اقتناء أو استعمال الأواني المطلية بالذهب أو الفضة","answer":"الجواب: الأواني من الذهب والفضة لا يجوز اقتناؤها ولا الشرب فيها ولا الأكل؛ لأن الرسول ﷺ نهى عن ذلك، الرسول ﷺ نهى عن الأكل والشرب في أواني الذهب والفضة، قال: لا تشربوا في آنية الذهب والفضة، ولا تأكلوا في صحافهما فإنها لهم في الدنيا -يعني: الكفرة- ولكم في الآخرة وقال عليه الصلاة والسلام: الذي يشرب أو يأكل في إناء الذهب والفضة إنما يجرجر في بطنه نار جهنم.\nفلا يجوز اقتناء الأواني من الذهب والفضة، ولا المطلي بشيء من ذلك والمموه بشيء من ذلك؛ لأن الرسول ﷺ نهى عن ذلك كما سمعت في الحديث الصحيح المتفق عليه أن النبي عليه السلام قال: لا تشربوا في آنية الذهب والفضة، ولا تأكلوا في صحافهما، فإنها لهم في الدنيا -يعني: الكفار- ولكم في الآخرة وقال أيضًا عليه الصلاة والسلام: الذي يأكل أو يشرب في إناء الذهب والفضة إنما يجرجر في بطنه نار جهنم رواه مسلم في الصحيح، والمموه من جنس الذهب الصرف والفضة الصرف، والمطلي كذلك، كلها ممنوعة، حتى ولو للزينة؛ لأنها وسيلة إلى الشرب فيها والأكل فيها، ولو أنها وضعت للزينة، فالواجب ترك ذلك، وهكذا لو كانت من الملاعق أو الأكواب الشاي أو القهوة تمنع؛ لأنها أواني. فلا يجوز اتخاذ شيء من الأواني صغيرة أو كبيرة من الذهب والفضة، ولا الشيء المطلي بهما سواء في ذلك أواني الشرب أو الأكل، سواء كانت أواني صغيرة كالملاعق والأكواب للشاي والقهوة أو كبيرة، لا فرق في ذلك لعموم الأدلة. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8399/حكم-اقتناء-او-استعمال-الاواني-المطلية-بالذهب-او-الفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_335/33508.mp3","categories":["الآنية","الصور والتصوير"]},{"id":10740,"question":"نعود مع مطلع هذه الحلقة إلى رسالة الأخت المستمعة (مريم . م. ز. ج) من تبوك، أختنا في الله عرضنا بعض أسئلة لها في حلقة مضت، وبقي لها في هذه الحلقة سؤال واحد تقول فيه: ما حكم أواني النحاس المطعمة بالفضة مثل الكاسات، هل حكمها حكم الذهب والفضة أم لا؟","title":"حكم استعمال الأواني المطلية بالذهب والفضة","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فجميع الأواني التي من الفضة ومن الذهب أو مطعمة بالذهب والفضة أو مموهة بذلك كلها ممنوعة ولا يجوز استعمالها، لقول النبي ﷺ: لا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافها، فإنها لهم في الدنيا -يعني: الكفرة- ولكم في الآخرة فقوله ﷺ: لا تشربوا في آنية الذهب والفضة ولا تأكلوا في صحافها يعم المطعمة والمموهة، والتي كلها من الذهب والفضة، وهكذا قوله ﷺ: الذي يشرب في إناء الذهب والفضة إنما يجرجر في بطنه نار جهنم رواه مسلم في الصحيح، وفي لفظ آخر في غير مسلم بإسناد صحيح عند الدارقطني وغيره: الذي يشرب في إناء الذهب والفضة أو في إناء فيه شيء من ذلك فهذا يدل على التعميم وأنه لا يجوز استعمال الأواني المطعمة بالذهب والفضة أو المموهة بالذهب والفضة أو التي هي من الذهب والفضة من باب أولى، ويدخل في ذلك أكواب الشاي وأكواب القهوة والملاعق كلها داخلة في هذا، ويستثنى من ذلك شيء واحد وهو الضبة التي يضبب بها القدح، الإناء إذا انكسر أو انشعب يجعل فيه ضبة فقط فعلها النبي ﷺ يعني: يربط بشيء من الفضة قليل لا بأس بذلك؛ لأنه ثبت عنه ﷺ: أنه كان له قدح فانشعب فجعل فيه ضبة من فضة رواه البخاري في الصحيح من حديث أنس ، فاحتج بذلك العلماء على أن الضبة اليسيرة من الفضة إذا انشعب القدح -إذا انشلخ­- كونه يربط بها لا حرج في ذلك، أما أن يتخذ إناء من الذهب والفضة أو يطعم بالذهب والفضة للزينة والجمال هذا كله لا يجوز، ولو كان ذلك في الأواني الصغيرة كالأكواب ونحوها. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8910/حكم-استعمال-الاواني-المطلية-بالذهب-والفضة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_345/34501.mp3","categories":["الآنية","الصور والتصوير"]},{"id":10742,"question":"تقول: لي أخوات صغيرات وأقوم بصنع عرائس لهن من القطن والقماش، وأقوم برسم أوجه لهذه العرائس بما يلزمها من أعين وأنوف وشفاه، فهل ما أقوم به مباح، أم أنه حرام؟ أفيدوني أفادكم الله.","title":"حكم صنع عرائس للأطفال من القطن والقماش","answer":"الجواب: لا، هذا ليس بصورة، الصورة أن تصور على الهيئة التي خلق عليها الإنسان، أما هذه الخياطات وهذه التي تفعلينها فليست بصورة هذه لعب لعب الأطفال التي يفعلها الناس بالقطن أو الصوف، أو تجعل عظام أو أعواد تلبسها ملابس كأنها صورة وليست صورة، كونها تخيط شيء يشبه الفم أو شيء يشبه العين أو تجعل خلق فيها كل هذا ليس بصورة في الحقيقة وإنما هي لعبة، لعبة تلهي الطفل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8922/حكم-صنع-عراىس-للاطفال-من-القطن-والقماش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34605.mp3","categories":["الصور والتصوير"]},{"id":10747,"question":"تقول: لي أخوات صغيرات وأقوم بصنع عرائس لهن من القطن والقماش، وأقوم برسم أوجه لهذه العرائس بما يلزمها من أعين وأنوف وشفاه، فهل ما أقوم به مباح، أم أنه حرام؟ أفيدوني أفادكم الله.","title":"حكم صنع عرائس للأطفال من القطن والقماش","answer":"الجواب: لا، هذا ليس بصورة، الصورة أن تصور على الهيئة التي خلق عليها الإنسان، أما هذه الخياطات وهذه التي تفعلينها فليست بصورة هذه لعب لعب الأطفال التي يفعلها الناس بالقطن أو الصوف، أو تجعل عظام أو أعواد تلبسها ملابس كأنها صورة وليست صورة، كونها تخيط شيء يشبه الفم أو شيء يشبه العين أو تجعل خلق فيها كل هذا ليس بصورة في الحقيقة وإنما هي لعبة، لعبة تلهي الطفل. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8922/حكم-صنع-عراىس-للاطفال-من-القطن-والقماش","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34605.mp3","categories":["الصور والتصوير"]},{"id":10750,"question":"نعود مع مطلع هذه الحلقة إلى رسالة الأخت المستمعة نجمة عبدالله محمد من العراق محافظة نينوى حي العامل، الأخت نجمة عرضنا بعض أسئلتها في حلقات مضت، وفي هذه الحلقة تسأل وتقول: هل صورة المتوفى عند وضعها في إطار وتعليقها على الحائط تضر المتوفى، وهل يلحقه إثم، وهل هذا حرام ممن يفعله أم لا؟","title":"حكم تعليق صور ذوات الأرواح وضرر ذلك على الأموات","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فتعليق الصور لا يجوز لا في المكاتب ولا في المجالس ولا في غير ذلك، أعني: صور ذوات الأرواح، كصورة الرجل أو الأسد أو الذئب أو القط أو غير ذلك كلها لا تجوز؛ لأن النبي ﷺ قال لـعلي: لا تدع صورة إلا طمستها، وقال عليه الصلاة والسلام لما رأى ستراً عند عائشة فيه تصاوير هتكه وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم، فلا يحوز للمسلم أن يعلق صورة، ولا لمسلمة أن تعلق صورة في بيت زوجها أو بيتها، أو في مكتب أو مجلس أو نحو ذلك.\nوأما الميت فلا يضره ذلك إذا كان لم يأمر بهذا ولم يرض بهذا إنما يضر من علقه، الإثم على من علقه، أما الميت الذي لم يرض بهذا ولم يأمر به فليس عليه من ذلك شيء؛ لأن الله سبحانه يقول: وَلا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَى [الأنعام:164] ولكن المعلق هو الذي يأثم بذلك. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8918/حكم-تعليق-صور-ذوات-الارواح-وضرر-ذلك-على-الاموات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34601.mp3","categories":["الصور والتصوير"]},{"id":11572,"question":"ما حكم لعب الأطفال التي تكون مجسمة على شكل حيوانات، أو شكل إنسان، هل هي جائزة، أو لا؟ جزاكم الله خيرًا.","title":"حكم ألعاب الأطفال المجسمة بأشكال الإنسان أو الحيوان","answer":"الجواب:  اختلف العلماء فيها، منهم من أجازها لأنها ممتهنة لما بمثابة الصورة التي في البساط والوسادة، قالوا: إن اللعبة هذه تكون ممتهنة، يلعب بها الأطفال، وقال آخرون من أهل العلم: إنها تحرم؛ لأنها صورة تعمها الأحاديث، وليست من جنس البساط ونحوه، فالأحوط تركها، وأن يدلهوا بشيء آخر، أو تقلع رؤوسها تكون صورة بلا رأس، حتى يلعبوا بها بدون رأس. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9755/حكم-العاب-الاطفال-المجسمة-باشكال-الانسان-او-الحيوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_386/38605.mp3","categories":["الصور والتصوير"]},{"id":12302,"question":"سمعت في هذا البرنامج بأن الملابس التي عليها رسم إنسان، أو حيوان حرام لبسها، فهل ينطبق هذا التحريم على ملابس الأطفال؟ وإذا كانت الإجابة بنعم، وعندي مجموعة كبيرة من ملابس الأطفال التي عليها رسوم للإنسان والحيوان، فهل يجب علي التخلص منها؟ وهل يجوز التصدق بها على الفقراء والمحتاجين، أم لا؟ أفيدونا أفادكم الله.","title":"حكم لبس الملابس التي عليها صور إنسان أو حيوان","answer":"الجواب:  لا يجوز لبس الملابس التي فيها صور حيوان من إنسان، أو أسد، أو ذئب، أو كلب، أو قط، أو غير ذلك، لا للرجل ولا للمرأة ولا للطفل ولا للكبير؛ لأن وجودها في الملابس فيه نوع من التعظيم لها، والرسول ﷺ نهى عن الصور، ولعن المصورين، وقال ﷺ: لا تدع صورة إلا طمستها وقال: لا تدخل الملائكة بيتًا فيه صورة إلا إذا كانت صور ممتهنة في البساط، أو الوسادة؛ هذا لا بأس، لا تمنع، إذا كانت ممتهنة في مثل البساط الذي يوطأ، في مثل الوسادة، في مثل الكنبة التي يجلس عليها؛ فهذه ممتهنة، أما الملابس لا، لكن إذا جعلت وسائد هذه الملابس، جعلت وسائد، أو لحفًا تمتهن؛ فلا بأس، أو جعل على الرأس شيئًا يزيله، رقعة تزيله، وتخفيه، وتستره؛ فلا بأس بذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10502/حكم-لبس-الملابس-التي-عليها-صور-انسان-او-حيوان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45308.mp3","categories":["الصور والتصوير"]},{"id":12303,"question":"حدثونا لو تكرمتم عن ألعاب الأطفال التي تكون مجسمة، إما على شكل إنسان أو حيوان، هل يجوز شراؤها من أجل تسلية الأطفال، ومن أجل أن يلعبوا بها، أم لا؟","title":"حكم شراء الألعاب المجسمة للأطفال","answer":"الجواب:  هذه المسألة فيها خلاف بين أهل العلم، منهم من أجازها لما فيها من الامتهان والتسلية للأطفال، وتمرين البنات على حضانة الأطفال، وتربية الأطفال، واحتجوا على هذا بما ورد في الحديث الصحيح عن عائشة -رضي الله عنها-: \"أنه كان لها بنات تلعب بهن، وكان يأتي إليها البنات يلعبن معها في ذلك\" وكان النبي يقرهن على ذلك، عليه الصلاة والسلام. وقال آخرون من أهل العلم: بل يجب منع ذلك ..... منع هذه الصور المجسمة، وقالوا: إن البنات اللاتي عند عائشة ليست مجسمة، وإنما هي على عادة العرب في إيجاد لعب من عظام، أو أعواد تلبس ملابس كأنها صورة، وليست مصورة. فالأحوط للمؤمن عدم هذه الألعاب المصورة، الأحوط والأقرب أنه ينبغي تركها؛ حذرًا مما جاء في الأحاديث الصحيحة من اللعن على ذلك، والشدة في ذلك، فالنبي ﷺ لما دخل على عائشة، ورأى عندها سترًا فيه تصاوير؛ غضب وهتكه، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم وقال لعلي : لا تدع صورة إلا طمستها.  فالمسلم يتباعد عن الشيء الذي نهى الله عنه، وهذه التي تسمى اللعب يخشى أن تدخل في ذلك، فالأحوط للمؤمن تركها، أما الجزم بتحريمها فهو محل نظر... فهو محل نظر، ولكنها بكل حال أقل ما فيها أنها مشتبهة، وقد قال -عليه الصلاة والسلام-: دع ما يريبك إلى ما لا يريبك وقال -عليه الصلاة والسلام-: من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه نسأل الله للجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10503/حكم-شراء-الالعاب-المجسمة-للاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_453/45309.mp3","categories":["الصور والتصوير"]},{"id":12418,"question":"مستمعة تقول المرسلة (ب. س) من الرياض، أيضًا تسأل جمعًا من الأسئلة في أحدها تقول: المفارش والبطانيات التي فيها صور ذوات الأرواح، هل تعتبر من الأشياء المهانة، وهل في بقائها في غرف النوم حرج؟ وجهونا جزاكم الله خيرًا.","title":"حكم الفرش والبطانيات التي عليها صور","answer":"الجواب: المفارش والوسائد واللحف ونحوه مما يمتهن لا يضر وجود الصورة فيها، وقد ثبت عن عائشة -رضي الله عنها- أن النبي ﷺ لما رأى في ستر عندها صورة؛ هتك ذلك، وأنكره قالت: فاتخذنا منه وسادتين يتكئ عليهما النبي -عليه الصلاة والسلام- وفي سنن النسائي وغيره أن النبي ﷺ واعد جبرائيل، فتأخر عن وعده، فلما جاءه سأله النبي ﷺ فقال: إن في البيت سترًا فيه تصاوير وتمثالًا وكلبًا، فمر برأس التمثال أن يقطع، وبالستر أن يجعل منه وسادتان منتبذتان توطأان، ومر بالكلب أن يخرج ففعل النبي ﷺ فأمر بقطع رأس التمثال، وجعل الستر وسادتين، وأمر بالكلب أن يخرج، وكان الكلب جروًا تحت نضد له، أدخله الحسن، أو الحسين. فالمقصود: أن هذا يدل على أن جعل الستر وسادة كافٍ مما يمتهن، فإذا كانت الصورة في بساط، أو في وسادة، أو في كرسي يمتهن؛ فلا حرج في ذلك، أما إذا كانت تعلق على الجدران، أو على الأبواب؛ فهذا منكر لا يجوز، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10623/حكم-الفرش-والبطانيات-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40211.mp3","categories":["الصور والتصوير"]},{"id":12714,"question":"يقول: أنا أعرف أن الملائكة لا تدخل بيتًا فيه كلب، ولا صورة، هل المقصود من الصورة هي الوثن، أو صورة الكاميرا؟","title":"عموم النهي عن اتخاذ الصور","answer":"الجواب:  الحديث عام، يعم الصورة القائمة والمجسمة، كالأصنام المعروضة، ويعم الصورة التي تكون بالكاميرا، أو غير الكاميرا، إذا كانت صورة معلقة، أو منصوبة في مكان، أما إذا كانت ممتهنة في الفراش، أو في الكرسي، أو في الوسائد هذه ممتهنة لا تمنع، لقول النبي ﷺ في الحديث الصحيح لما كان على موعد من جبرائيل، فتأخر، فخرج إليه ﷺ فقال: إن في البيت سترًا به تصاوير، وتمثالًا وكلبًا، فأمر برأس التمثال أن يقطع حتى يكون كهيئة الشجرة، وأمر بالستر أن يتخذ منه وسادتان منتبذتان توطأان، وأمر بالكلب أن يخرج فأمر الرسول ﷺ بالكلب أن يخرج، وكان جروًا تحت نضد لهم للحسن أو الحسين، وأمر برأس التمثال أن يقطع، وأمر بالستر أن يتخذ منه وسادتان. فدل على أن ما كان في وسادة وبساط لا يمنع من دخول الملائكة؛ لأنه ممتهن، أما شيء معلق على الجدار، أو على الباب، أو على الكرسي، معلق أو منصوب؛ فهذا كونه يمنع، ولا يجوز بقاؤه، لقوله ﷺ: لا تدع صورة إلا طمستها. وهكذا التصاوير تحفظ للذكرى، يجب إزالتها، طمسها، ولا يغفر من ذلك إلا ما كان في الوسائد، والبسط، والكراسي، ونحوه مما يمتهن. نعم. المقدم: هل من كلمة -لو تكرمتم- تنوهون حول الصورة للضرورة؟ الشيخ: نعم أما اتخاذ الصورة للضرورة؛ فلا بأس؛ لأن الله قال سبحانه: وَقَدْ فَصَّلَ لَكُمْ مَا حَرَّمَ عَلَيْكُمْ إِلَّا مَا اضْطُرِرْتُمْ إِلَيْهِ [الأنعام:119] مثل اتخاذ الصورة في التابعية، أو في الجواز للحاجة، أو الشهادة العلمية إذا لم يحصل له ذلك إلا بالصورة؛ فلا حرج في ذلك؛ لأنه قد تدعو الحاجة إليها؛ لعدم التزوير. فالمقصود: أنه إذا كان لحاجة شرعية؛ فلا بأس بذلك، كالتابعية، والجواز، ونحو ذلك. نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10927/عموم-النهي-عن-اتخاذ-الصور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46002.mp3","categories":["الصور والتصوير"]},{"id":12728,"question":"هل الصلاة تجوز على بسط، أو سجاد مرسوم عليها صور حيوانات، أو إنسان، أو نبات، أو غير ذلك؟","title":"حكم الصلاة على بساط فيه تصاوير","answer":"الجواب:  نعم تصح الصلاة؛ لأنها ممتهنة، لكن تركها أولى، كونه يلتمس سجادة، أو بساطًا ما فيه صور، ولا نقوش؛ يكون أفضل، حتى لا تشوش؛ لأن النقوش والصور قد تشوش عليه صلاته وفكره، قد يشتغل بها بعض الشيء، فإذا كان هناك فراش، ليس فيه نقوش، ولا صور؛ يكون أفضل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10941/حكم-الصلاة-على-بساط-فيه-تصاوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46016.mp3","categories":["المساجد ومواضع السجود","الصور والتصوير"]},{"id":12793,"question":"تقول: في كثير من البطاطين صورة نمر، أو أسد، فما رأيكم في هذا؟","title":"حكم الصور على الفرش والبطانيات ونحوها","answer":"الجواب:  إذا كانت ممتهنة فلا بأس في البطاطين التي يلتحف بها، أو في الفرش التي يوطأ عليها، والكراسي لا بأس بذلك؛ لأنها ممتهنة، وقد دلت أحاديث النبي ﷺ على جواز ذلك، وإذا تيسر له خير منها؛ فهو أفضل، وإلا فلا حرج فيها، والحمد لله. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11007/حكم-الصور-على-الفرش-والبطانيات-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_461/46113.mp3","categories":["الصور والتصوير"]},{"id":12885,"question":"هل يجوز للمرأة أن تلبس الذهب وفيه رسم للطيور؟","title":"حكم الذهب الذي عليه تصاوير","answer":"الجواب:  لا يجوز لبس ما فيه الصور، بل يزال، يحك، أو يبدل فص بفص آخر إن كان فصوصًا. المقصود: لا يلبس هذا إلا بإزالة هذه الصورة صورة الحيوان، سواء في الثياب، أو في الطاقية، أو في الغترة، أو في القميص، أو في الخاتم، أو في الساعة، نعم.","link":"https://binbaz.org.sa/fatwas/11100/حكم-الذهب-الذي-عليه-تصاوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46617.mp3","categories":["الصور والتصوير"]},{"id":13341,"question":"نعود مع مطلع هذه الحلقة إلى رسالة وصلت إلى البرنامج من الجمهورية اليمنية، وباعثتها إحدى الأخوات من هناك تقول المستمعة (ج. ع) أختنا عرضنا بعض أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها بعض الأسئلة من بينها سؤال يقول: إذا كان في الحلي بعض صور الحيوانات، فهل يجوز لبسه؟","title":"حكم لبس النساء الحلي التي عليها صور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فلا يجوز للمرأة أن تلبس حليًا، أو ملابس أخرى فيها صور الحيوانات، لا أسود، ولا نمور، ولا ذئاب، ولا رجال، ولا نساء، الواجب أن يزال الرأس، فإذا أزيل الرأس بأي طريقة؛ جاز اللبس؛ لأن الرسول ﷺ أمر بإزالة الرأس حتى يكون كهيئة الشجرة، ولما رأى سترًا عند عائشة فيه صورة؛ هتكه، وغضب -عليه الصلاة والسلام- وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم فالواجب أن تزال هذه الصورة بالطريقة الممكنة، ويكفي أن يزال الرأس، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11627/حكم-لبس-النساء-الحلي-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_477/47701.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة","قضايا المرأة"]},{"id":13376,"question":"السائل يقول: احتار كثير من الآباء والأمهات في حكم ألعاب الأطفال المجسمة، والمشهورة باسم العرائس بين محلل لها، وبين محرم، ما هو حكم الشرع في نظركم -سماحة الشيخ- في هذه المسألة؟ نأمل بسط الجواب مفصلًا بأدلته الشرعية؛ وذلك لتعم الفائدة، ويحصل النفع، جزاكم الله خيرًا.","title":"حكم ألعاب الأطفال المجسمة","answer":"الجواب: اللعب المصورة لاشك أنها داخلة في الأحاديث الصحيحة، الرسول لعن المصورين، وقال -عليه الصلاة والسلام-: أشد الناس عذابًا يوم القيامة المصورون فالواجب على المسلم تركها. أما وجود لعب ليس فيها تصوير، لعب عادية من العهن، من الصوف، من الخرق، يحصل بها تشغيل الأطفال، وعدم إتعابهم لأهليهم، هذا لا يسمى صورة، مثلما كان في عهد الصحابة ..... أولادهم بصور من العهن، من الصوف، أو من القطن، أو نحو ذلك، تجعل لها كأنها صورة إنسان في عود، أو في عظم، أو في كذا، يخيط عليها كذا، وتخيط عليها كذا كأنها صورة تلهي بها الطفل. أما الصور المعروفة التي فيها صورة لذوات الأرواح، فالذي يظهر من الأدلة الشرعية تحريمها، وأما ما ورد عن عائشة أنها كان عندها لعب، فهو محمول على عادة الصحابة اللعب من العهن وأشباهها، على عادة الصحابة في تصوير ما يلهي الأطفال من العهن والصوف ونحو ذلك؛ لتشغيلهم، وإلهائهم حتى لا يشغلوا أهليهم بالصياح ونحو ذلك. لأن الجمع بين النصوص أمر لازم، والنصوص صريحة في تحريم الصور؛ صور ذوات الأرواح صريحة في ذلك، فلا يجوز أن تعارض بشيء ليس بصريح فيما يروى عن عائشة -رضي الله عنها- نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11666/حكم-العاب-الاطفال-المجسمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52503.mp3","categories":["الصور والتصوير"]},{"id":13457,"question":"نختم أسئلة هذا السائل: محمد مصري ويعمل بالسعودية بهذا السؤال يقول: هل الأغطية التي على السرير وبها صور الطاووس، أو الطيور في المنزل هل في ذلك حرج؟","title":"حكم الصور الموجودة على البسط","answer":"الجواب: الصور في البساط ونحوه لا حرج فيها؛ لما ثبت عن عائشة -رضي الله عنها-: أنها قالت: \"لما أزال النبي ﷺ الستر الذي في الصورة قالت: اتخذنا منه وسادتين كان يرتفق بهما -عليه الصلاة والسلام-\" وفي سنن النسائي وغيره بإسناد صحيح، عن أبي هريرة  \"أن النبي ﷺ كان بينه وبين جبريل موعد، فجاء جبريل، ولم يدخل، فسأله النبي ﷺ عن السبب، فقال: إن في البيت سترًا فيه تصاوير وعظامًا وتمثالًا وكلبًا، فَمُرْ برأس التمثال أن يقطع حتى يكون كهيئة الشجرة، وَمُرْ  بالستر حتى يتخذ منه وسادتان توطأان أو ممتهنتان، وَمُرْ  بالكلب أن يخرج، فأمر النبي ﷺ بالتمثال فقطع رأسه، والستر فجُعل منه وسادتان، والكلب أخرج، كان جروًا وجدوه تحت نضد لهم، أدخلاه الحسن، أوالحسين\". فدل على أن السجود على الممتهن لا حرج، لكن لا يجوز التصوير لا في المخيوطة ولا غيرها، التصوير لا يجوز، لكن إذا وجد شيء مصور في بساط، أو وسادة تمتهن؛ فلا حرج، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11760/حكم-الصور-الموجودة-على-البسط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51705.mp3","categories":["الصور والتصوير"]},{"id":13931,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول المرسلة (ح. ع. أ)، أختنا تسأل في أحد أسئلتها وتقول: هل يجوز للمرأة أن تصلي بالثوب الذي يوجد به صور؟ نرجو التوضيح في هذه المسألة، وإفادتنا بالخير جزاكم الله خيرًا.","title":"حكم الصلاة في ثوب فيه صور","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد:\nفقد دلت الأحاديث الصحيحة عن رسول الله ﷺ على تحريم التصوير وعلى لعن المصورين، ولما رأى عند عائشة رضي الله عنها سترًا فيه تصاوير هتكه وغضب عليه الصلاة والسلام وقال: يا عائشة إن أصحاب هذه الصور يعذبون يوم القيامة ويقال: أحيوا ما خلقتم. فلا يجوز للمرأة أن تصلي في ثوب فيه تصاوير سواءً كانت تصاوير لبني آدم أو لحيوانات أخرى، لكن لو صلت صحت الصلاة مع الإثم، الصحيح: أنها تصح الصلاة لكن مع الإثم، لا تعيد الصلاة لكن عليها التوبة إلى الله، ولا تعود تصلي في ثوب فيه تصاوير لا في فنيلة ولا في قميص ولا في سراويل ولا في خمار يجب ترك ذلك. وهكذا الرجل لا يصلي في ثوب فيه تصاوير لا فنيلة ولا قميص ولا غترة ولا سراويل ولا بشت، يجب ترك ذلك؛ لأن هذا أعظم من الستر اللي على الجدار، نسأل الله السلامة. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12318/حكم-الصلاة-في-ثوب-فيه-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_482/48206.mp3","categories":["الصور والتصوير","مسائل متفرقة في الصلاة"]},{"id":15400,"question":"السائلة (مريم . م) تقول في ثاني أسئلتها: ما حكم رسم الجهاز الهضمي والتنفسي للإنسان؟ نحن نطالب برسم ذلك في مادة الأحياء، أفيدونا سماحة الشيخ.","title":"ما حكم رسم الجهاز الهضمي والتنفسي للإنسان؟","answer":"الجواب: إن كان رسم صورة.\nالمقدم: صورة، نعم يا شيخ. الشيخ: إن كان صورة كاملة لا يجوز، إن كان رسم صورة بطنه، أو صورة أمعائه، فلا بأس، أما صورته التامة برأسه ووجهه ما يجوز. المقدم: تقصد الأمعاء والبطن والكلية.\nالشيخ: ... الأمعاء لا بأس وحدها، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13898/ما-حكم-رسم-الجهاز-الهضمي-والتنفسي-للانسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56720.mp3","categories":["الصور والتصوير"]},{"id":16483,"question":"هذه سائلة للبرنامج، حقيقة أختكم في الله أم سارة تقول في هذه الرسالة: أفيدوني يا سماحة الشيخ عن وضع الألعاب البلاستيكية عند الأبناء الصغار، مثل الأرنب، وهل وضعها حرام؟ وبعض الصور الموجودة على بعض الألعاب؟","title":"حكم الألعاب المصورة للأطفال","answer":"الجواب: تركها أحوط، ترك الصور بالنسبة للأطفال أحوط، وأولى، وبعض أهل العلم يرخص بها للصبية الصغار، والبنات الصغار، ولكن تركها أحوط، إذا تيسر أن يلعب الأطفال بشيء آخر ما فيه صورة؛ فهو أحوط، وأحسن، وإلا فالأمر فيه واسع؛ لأنه ثبت عن عائشة أنه كان عندها لعب تلعب بهن في حياة النبي ﷺ لأنه كان تزوجها وهي صغيرة، تزوجها وهي بنت تسع -رضي الله عنها- وكان عندها لعب أقرها -عليه الصلاة والسلام- نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15188/حكم-الالعاب-المصورة-للاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58212.mp3","categories":["الصور والتصوير"]},{"id":17293,"question":"يقول السائل: هل يجوز شراء ألعاب الأطفال التي تأتي على شكل حيوان، أو إنسان؟","title":"حكم شراء الألعاب التي على شكل حيوان أو إنسان","answer":"الجواب: ترك ذلك أحوط لعموم الأحاديث؛ لأن الرسول ﷺ عظم شأن التصوير، وبيَّن أن أهله أشد الناس عذابًا يوم القيامة، فقال -عليه الصلاة والسلام-: أشد الناس عذابًا يوم القيامة المصورون، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم وفي الحديث الصحيح: أنه ﷺ لعن: آكل الربا، وموكله، والواشمة، والمستوشمة، ولعن المصور، وقال لعلي : لا تدع صورة إلا طمستها ولما دخل الكعبة يوم الفتح طمس ما في جدرانها من الصور. وبعض أهل العلم أجاز اللعب؛ لأنها تمتهن للصبيان الصغار، والبنات الصغار؛ لأنها تمتهن، وتعلقوا بما جاء عن عائشة -رضي الله عنها- أنها كان عندها لعب، وكان من بينها خيل لها أجنحة، قالوا: هذا يدل على جواز اللعب للأطفال المصورة. والجواب عن هذا: أن هذا -والله أعلم- كان قبل التحريم، قبل النهي حين كانت صغيرة في أول الهجرة، فإنه نكحها ﷺ ودخل بها وهي بنت تسع صغيرة، فلعل هذا كان قبل التحريم من الصور، فهو ﷺ في حياته في المدينة شدد في هذا الأمر، ومن ذلك أنه ﷺ دخل ذات يوم على عائشة، ورأى عندها سترًا فيه تصاوير، فهتكه، وقال: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم فالأحوط للمؤمن ألا يتخذ للصبية الصغار شيئًا منها الصور، ولكن يأتي بلعب أخرى غير مصورة، هذا هو الأحوط للمؤمن. نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/16136/حكم-شراء-الالعاب-التي-على-شكل-حيوان-او-انسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76902.mp3","categories":["الصور والتصوير"]},{"id":18227,"question":"إحدى الأخوات المستمعات بعثت برسالة ضمنتها عددًا كبيرًا من الأسئلة مجموعها سبعة عشر سؤالًا، أختنا تسأل في عدة قضايا سنحاول توزيع هذه الأسئلة على مجموعة من الحلقات، فتقول في سؤال لها: هل الصور والتصوير حرام؟","title":"حكم الصور والتصوير","answer":"الجواب: نعم، تصوير ذوات الأرواح من بني آدم، أو من البهائم، أو الطيور، لا يجوز؛ لقول النبي ﷺ: أشد الناس عذابًا يوم القيامة المصورون ولقوله عليه الصلاة والسلام: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم ولما ثبت عنه عليه الصلاة والسلام من حديث أبي جحيفة  قال: لعن رسول الله ﷺ آكل الربا، وموكله، والواشمة، والمستوشمة، ولعن المصور رواه البخاري في صحيحه. هذا يدل على أن التصوير من الكبائر كما أن أكل الربا من الكبائر، وهكذا الوشم من الكبائر، وهو ما يفعله بعض الناس من غرز يده أو خده بإبرة ونحوها؛ فإذا خرج الدم لطخه بشيء من النيل أو الكحل، أو نحو ذلك، يبقى علامة وشامة عليه، هذا يفعله بعض الناس، وهو غلط ومنكر وكبيرة من كبائر الذنوب. الحاصل: أن المصورين ملعونون بهذا الحديث الصحيح عن رسول الله عليه الصلاة والسلام، وهم من أشد الناس عذابًا يوم القيامة كما قاله النبي عليه الصلاة والسلام، والأحاديث في ذلك كثيرة، فالواجب على المسلم أن يحذر التصوير، سواءً كان التصوير لزوجته أو ولده أو غيرهما أو لحيوان كالإبل والبقر أو للطير كالحمام والعقاب والدجاج.. ونحو ذلك، كله ممنوع، كله محرم. ثم إن كان التصوير له ظل له جسم هذا محرم بالإجماع بإجماع المسلمين، لهذه الأحاديث الصحيحة، أما إن كان لا ظل له كالتصوير الشمسي في القرطاس ونحوه، هذا أيضًا محرم عند جمهور أهل العلم لعموم الأحاديث الدالة على ذلك، فلا يجوز للمسلم أن يتعاطى شيئًا من ذلك، وليس مع من أجاز التصوير الشمسي حجة بل هو قول باطل لا وجه له، فالتصوير كله ممنوع، في القرطاس أو في الألواح أو في الملابس أو في الجدران أو غير ذلك، من حديد أو خشب أو غير ذلك. والواجب طمس الصور إذا وجدت بقطع رءوسها أو محوها بالكلية، لقوله ﷺ في الحديث الصحيح لـعلي : لا تدع صورة إلا طمستها ولأنه ﷺ لما دخل الكعبة عام الفتح محا جميع الصور التي في الكعبة وكسر الأصنام وأخذ ماءً وثوبًا فمسح به ما بجدران الكعبة من الصور. لكن إذا أكره الإنسان على الصورة لأخذ التابعية الحفيظة مثلاً أو لأسباب أخرى ليس له فيها اختيار وهو محتاج إلى ذلك كالتابعية، والشهادة العلمية، وقيادة السيارة ونحو ذلك مما يلزم به وليس له مندوحة عنه فلا حرج عليه إذا أخذ ذلك من أجل الضرورة، وهو لا يحب ذلك، ولا يرضى ذلك لكن لأجل الحاجة والضرورة إلى هذا الشيء، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17276/حكم-الصور-والتصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85704.mp3","categories":["الصور والتصوير"]},{"id":18229,"question":"إحدى الأخوات المستمعات بعثت برسالة ضمنتها عددًا كبيرًا من الأسئلة مجموعها سبعة عشر سؤالًا، أختنا تسأل في عدة قضايا سنحاول توزيع هذه الأسئلة على مجموعة من الحلقات، فتقول في سؤال لها: هل الصور والتصوير حرام؟","title":"حكم الصور والتصوير","answer":"الجواب: نعم، تصوير ذوات الأرواح من بني آدم، أو من البهائم، أو الطيور، لا يجوز؛ لقول النبي ﷺ: أشد الناس عذابًا يوم القيامة المصورون ولقوله عليه الصلاة والسلام: إن أصحاب هذه الصور يعذبون يوم القيامة، ويقال لهم: أحيوا ما خلقتم ولما ثبت عنه عليه الصلاة والسلام من حديث أبي جحيفة  قال: لعن رسول الله ﷺ آكل الربا، وموكله، والواشمة، والمستوشمة، ولعن المصور رواه البخاري في صحيحه. هذا يدل على أن التصوير من الكبائر كما أن أكل الربا من الكبائر، وهكذا الوشم من الكبائر، وهو ما يفعله بعض الناس من غرز يده أو خده بإبرة ونحوها؛ فإذا خرج الدم لطخه بشيء من النيل أو الكحل، أو نحو ذلك، يبقى علامة وشامة عليه، هذا يفعله بعض الناس، وهو غلط ومنكر وكبيرة من كبائر الذنوب. الحاصل: أن المصورين ملعونون بهذا الحديث الصحيح عن رسول الله عليه الصلاة والسلام، وهم من أشد الناس عذابًا يوم القيامة كما قاله النبي عليه الصلاة والسلام، والأحاديث في ذلك كثيرة، فالواجب على المسلم أن يحذر التصوير، سواءً كان التصوير لزوجته أو ولده أو غيرهما أو لحيوان كالإبل والبقر أو للطير كالحمام والعقاب والدجاج.. ونحو ذلك، كله ممنوع، كله محرم. ثم إن كان التصوير له ظل له جسم هذا محرم بالإجماع بإجماع المسلمين، لهذه الأحاديث الصحيحة، أما إن كان لا ظل له كالتصوير الشمسي في القرطاس ونحوه، هذا أيضًا محرم عند جمهور أهل العلم لعموم الأحاديث الدالة على ذلك، فلا يجوز للمسلم أن يتعاطى شيئًا من ذلك، وليس مع من أجاز التصوير الشمسي حجة بل هو قول باطل لا وجه له، فالتصوير كله ممنوع، في القرطاس أو في الألواح أو في الملابس أو في الجدران أو غير ذلك، من حديد أو خشب أو غير ذلك. والواجب طمس الصور إذا وجدت بقطع رءوسها أو محوها بالكلية، لقوله ﷺ في الحديث الصحيح لـعلي : لا تدع صورة إلا طمستها ولأنه ﷺ لما دخل الكعبة عام الفتح محا جميع الصور التي في الكعبة وكسر الأصنام وأخذ ماءً وثوبًا فمسح به ما بجدران الكعبة من الصور. لكن إذا أكره الإنسان على الصورة لأخذ التابعية الحفيظة مثلاً أو لأسباب أخرى ليس له فيها اختيار وهو محتاج إلى ذلك كالتابعية، والشهادة العلمية، وقيادة السيارة ونحو ذلك مما يلزم به وليس له مندوحة عنه فلا حرج عليه إذا أخذ ذلك من أجل الضرورة، وهو لا يحب ذلك، ولا يرضى ذلك لكن لأجل الحاجة والضرورة إلى هذا الشيء، والله ولي التوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/17276/حكم-الصور-والتصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_857/nour_85704.mp3","categories":["الصور والتصوير"]},{"id":18265,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الكويت، باعثة الرسالة إحدى الأخوات من هناك تقول المرسلة (ل. ش. أم محمد)، أختنا لها ستة أسئلة، في سؤالها الأول تسأل وتقول: ما حكم رؤية صور الحيوانات في الفيديو بدون موسيقى، وبمعنىً آخر: أود معرفة حكم الصور في الفيديو؟ جزاكم الله خيرًا.","title":"حكم مشاهدة الصور في الفيديو","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه، أما بعد: فلا أعلم شيئًا في رؤية الصور التي ليس معها آلة لهو، لا أعلم في هذا بأسًا إلا أن تكون الصور من الصور التي تثير الشهوات كصور النساء الخليعات، أو صور المردان؛ فينبغي للمؤمن أن يغض بصره عن ذلك وألا ينظر إليها. أما صور الحيوانات الأخرى كالإبل والبقر والغنم والأسود والظبا وأشباهها فلا بأس بذلك، لكن إذا كانت الصورة مما تثير الغريزة -تسبب الفتنة- كصور النساء الفاتنات، وصور المردان؛ فينبغي غض البصر عن ذلك، غض المرأة بصرها عن الرجال، وغض الرجل بصره عن النساء والمردان حتى لا تقع الفتنة. نسأل الله السلامة. نعم. المقدم: جزاكم الله خيرًا! هل ينتقل السؤال -سماحة الشيخ- إلى حكم التصوير حينئذٍ؟ الشيخ: التصوير له شأن آخر، التصوير لا يجوز إذا كان لذوات الأرواح، سواء كانت من بني آدم أو غير بني آدم؛ لقول النبي ﷺ: أشد الناس عذابًا يوم القيامة المصورون ولأنه عليه الصلاة والسلام: لعن آكل الربا، وموكله، ولعن المصور رواه البخاري في الصحيح. تصوير ذوات الأرواح من بني آدم أو من غيرهم أمر لا يجوز، لكن عند الضرورة التي ليس للإنسان فيها اختيار ولا رغبة، إنما ضرورة كتصوير المجرمين الذين يطلب إمساكهم حتى لا يضروا المسلمين، أو تصوير من يعطى الجنسية -يعني: تابعية.. حفيظة- إذا دعت الحاجة إلى ذلك؛ فلا حرج عليه إذا لم تحصل له إلا بالصورة؛ لأنها لمقصد معروف، وهو تمييزه ومعرفته عن غيره، فالمقصود إذا كانت الصورة لها حاجة ضرورية مثل ما ذكرنا فلا بأس.. للحاجة، ويكون داخلًا في قوله تعالى: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ [النحل:106] يعني: من جنس المكره. نعم.","link":"https://binbaz.org.sa/fatwas/17314/حكم-مشاهدة-الصور-في-الفيديو","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91001.mp3","categories":["الصور والتصوير"]},{"id":18339,"question":"هذه السائلة تقول يا فضيلة الشيخ! أسأل عن اقتناء لعب الأطفال على هيئة ذات الأرواح هل يجوز اقتناء؟","title":"حكم لعب الأطفال التي على شكل ذوات الأرواح","answer":"الجواب: الأحوط ترك ذلك؛ لعموم الأدلة المحرمة للصور، الأحوط ترك ذلك، بعض أهل العلم يرخص في اللعب، ولكن تركها أحوط يعطي الأطفال لعب ما فيها صور ما فيها رءوس. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17397/حكم-لعب-الاطفال-التي-على-شكل-ذوات-الارواح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91322.mp3","categories":["الصور والتصوير"]},{"id":18429,"question":"تسأل أختنا وتقول: يوجد لي بلوزة اشتريتها قبل أن أعلم أن الصور حرام، وعليها صورة وأريد أن أتلفها ولكنها غالية، ماذا أفعل؟","title":"كيفية العمل بالملابس التي عليها صور","answer":"الجواب: بالإمكان أن يزال رأس الصورة بشيء من الصبغ أو الخياطة، حتى يزول الرأس، فإذا زال الرأس بأي شيء من خياطة أو رقعة أو صبغ من الأصباغ، فلا حرج في بقاء بقية الجسم. نعم. المقدم: يعني لو نسجت على رأس الصورة صورة شجرة أو ما أشبه ذلك يكفي هذا؟ الشيخ: كفى. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17508/كيفية-العمل-بالملابس-التي-عليها-صور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_914/nour_91404.mp3","categories":["الصور والتصوير","قضايا المرأة"]},{"id":18869,"question":"نفس هذه الجماعة يقول أخونا: تبيح التصوير الشمسي لغير الضرورة مثل التصوير في الرحلات، والتصوير في الأفراح، وما شابه ذلك.","title":"حكم تصوير ذوات الأرواح","answer":"الجواب: التصوير محرم لا يجوز لذوات الأرواح، سواء شمسيًا أو غير شمسي، لا يجوز أن يصور شيئًا  من ذوات الأرواح، لكن إذا دعت الضرورة إلى ذلك كتصوير المجرمين حتى يقبض عليهم، أو ما تدعو له الضرورة كحفائظ النفوس إذا لم تحصل إلا بذلك. أما تصوير ذوات الأرواح لتعليقها في الجدران، أو للاحتفاظ بها، أو حفلات الأعراس، أو ما أشبه ذلك؛ هذا لا أصل له، ولا يجوز، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18012/حكم-تصوير-ذوات-الارواح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92212.mp3","categories":["الصور والتصوير"]},{"id":19380,"question":"ما صحة الحديث الآتي عن عائشة رضي الله عنها قالت: «كنت ألعب بالبنات فربما دخل علي رسول الله ﷺ وعندي الجواري، فإذا دخل خرجن، وإذا خرج دخلن» كيف نجمع بين هذا الحديث وبين تحريم المجسمات ذوات الأرواح؟ وهل يجوز اقتناء لعب الأطفال المجسمة باعتبارها مهانة؟","title":"حكم المجسمات من ذوات الأرواح من لعب الأطفال","answer":"الجواب: هذه المسألة اختلف فيها العلماء رحمة الله عليهم، فمنهم من أجاز ذلك احتجاجًا بحديث عائشة وما عندها من اللعب، وقالوا: إن النبي ﷺ أقرها وهو لا يقر على باطل، فدل على أنه يسمح باللعب للبنات، ليتمرن على خدمة الأولاد وتربية الأولاد بتمرنهن على هذه اللعب، ولأنها في حكم الامتهان والابتذال فرخصوا فيها. وقال آخرون: إن هذا كان قبل النهي، قبل نهيه ﷺ عن الصور، وقبل لعنه المصورين، وقبل أمره بطمس الصور، فلا يسمح لهن بذلك، وقالوا: إنما يسمح لهن بالشيء الذي ليس فيه صورة، كاللعب العادية التي بالأعواد والعظام، وتلبس بعض الثياب وهي ليست صورة إنما هي شبه صورة يعتادها البنات سابقًا من غير تصوير، وهذا القول محتمل وهو أحوط، ولكن قول من قال بالجواز من لعب البنات قول قوي. والأصل عدم النسخ، ويجمع بين النصوص بأن لعب البنات في حكم الامتهان؛ ولأن فيها تدريبًا لهن على خدمة الأطفال وتربية الأطفال، فيكون هذا مستثنى من الأحاديث العامة التي فيها النهي عن اقتناء الصور والأمر بطمسها، وتكون هذه في حكم الصور التي تكون في البسط والوسائد لها حكم الامتهان. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18602/حكم-المجسمات-من-ذوات-الارواح-من-لعب-الاطفال","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_934/nour_93410.mp3","categories":["الصور والتصوير"]},{"id":19448,"question":"يسأل أخونا من العراق أيضًا ويقول: ما هي الأدلة الواردة من الكتاب والسنة في تحريم الصورة أو الرسم؟","title":"أدلة تحريم التصوير","answer":"الجواب: الصور ممنوعة، لعن الرسول ﷺ المصورين، وقال: إنهم أشد الناس عذابًا يوم القيامة والمراد بالصورة: صورة الحيوان، كل ذي روح لا يجوز تصويره إلا للضرورة التي لا حيلة فيها، مثل تصوير المجرمين الذين يؤذون الناس ويضرونهم حتى يمسكوا حتى يطلبوا ويمسكوا، ومثل تصوير من أراد حفيظة للنفوس ورأت الدولة أنه لابد من صورة حتى لا يحصل تزوير هذا من باب الضرورة، والإنسان كالمكره في مثل هذا إذا احتاج إلى التابعية هو كالمكره فلا يعتبر ذلك حجة على جواز التصوير، هذه أمور تدعو لها الضرورة، هكذا إذا لم يحصل له الشهادة العلمية التي حصل عليها من كلية أو مدرسة أخرى إلا بصورة فهو مضطر في حكم المكره، لئلا تضيع عليه هذه المعلومات التي حصل عليها. فالمقصود أن التصوير منكر وممنوع إلا إذا دعت إليه الضرورة فالإنسان يعتبر حينئذ في حال الضرورة كالمكره، وقد صح عن رسول الله عليه الصلاة والسلام أنه قال: أشد الناس عذابًا يوم القيامة المصورون وقال: من صور صورة في الدنيا كلف أن ينفخ فيها الروح يوم القيامة وليس بنافخ وقال أيضًا عليه الصلاة والسلام: إن أصحاب هذه الصور يعذبون يوم القيامة ويقال لهم: أحيوا ما خلقتم. ولا فرق بين الصورة المجسمة المصنوعة بالآلة أو باليد وبين الصورة المرسومة بالكاميرا كلها داخلة في الحديث وكلها ممنوعة إلا للضرورة التي تقدمت الإشارة إليها. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18696/ادلة-تحريم-التصوير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_938/nour_93812.mp3","categories":["الصور والتصوير"]},{"id":19541,"question":"من فيصلية التوين بسدير رسالة بعثت بها إحدى الأخوات من هناك تقول: أم المهند ، أم المهند لها ستة أسئلة، تسأل أولًا وتقول: ما حكم وجود الجرائد في المنازل مع العلم أن بها الكثير من الصور، وإذا كان وجودها في المنزل حرام ويمنع دخول الملائكة، فهل الشطب بالقلم على الصورة يبيح وجودها في المنزل؟","title":"حكم وجود المجلات والبسط والوسائد التي فيها صور في البيوت","answer":"الجواب: الجرائد والكتب التي فيها الصور ليست من جنس الصورة المعلقة على الجدران أو المنصوبة في المحل، بل لها حكم آخر، فإذا غطيت أو كانت الكتب مصفودة والصورة في داخلها فليس هناك صورة منصوبة، ولكن من باب الاحتياط أن يشطب الرأس، يعني: يمحى الرأس ويجعل عليه شيئًا من الحبر أو غيره حتى يزول، حتى يذهب الرأس وتبقى بقية الصورة في المجلة أو في الجريدة أو في الكتاب هذا يكون أحوط للمسلم، وأبعد عن خطر عدم دخول الملائكة. وهكذا الصورة التي في البساط الذي يفرش في الأرض، أو الوسائد، هذه لا تمنع دخول الملائكة، لما ثبت عنه ﷺ أن عائشة رضي الله عنها لما أنكر عليها النبي ﷺ القرام الذي فيه التصاوير جعلته وسائد يرتفق بها النبي عليه الصلاة والسلام، وثبت أيضًا عنه ﷺ: «أنه واعد يومًا جبرائيل أن يأتيه فتأخر عن موعده، فسأله عن ذلك لما جاء، فقال: إنه كان في البيت تمثال، وكان فيه ستر فيه تصاوير وكان فيه كلب، ثم قال جبرائيل للنبي ﷺ: مر بالكلب أن يخرج، وبالتمثال أن يقطع رأسه حتى يكون كهيئة الشجرة، وبالستر أن يتخذ منه وسادتان منتبذتان توطئان، ففعل ذلك النبي ﷺ فدخل جبرائيل ، ووجدوا الكلب جروًا تحت نضد لهم أدخله بعض الصبية الحسن أو الحسين». فهذا يدل على أن الصورة في الوسادة والبساط ونحو ذلك لا تمنع من دخول الملائكة، فمثل ذلك الصورة التي في الكتاب؛ فإنها غير محترمة، ولا معلقة كالستر المعلق على الباب، بل هي مستورة بصفد الكتاب، ومستورة بصفد الجريدة وعدم إظهار الصورة، لكنها في بعض الأحيان قد تنشر وقد تظهر عند فتح الكتاب وتصفح الكتاب، وعند قراءة الجريدة، ففي هذه الحال ينبغي للمؤمن أن يحتاط لدينه وأن يمحو رأس الصورة يمحوه بشيء، فإذا محا الرأس كفى لهذا الحديث السابق. ولا يكفي الشخط بين الرأس وبين الجثة ما يسمى هذا قطع الرأس، إنما يمحى الرأس بالكلية يطمس، وبهذا يزول الحكم، والله المستعان، نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18787/حكم-وجود-المجلات-والبسط-والوساىد-التي-فيها-صور-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_940/nour_94002.mp3","categories":["الصور والتصوير"]},{"id":19716,"question":"أخيرًا يسأل: ما هي أنواع الصور التي لا يجوز وجودها في البيوت؟","title":"ما الصور التي لا يجوز وجودها في البيوت؟","answer":"الجواب:\nالصور المنصوبة التي تنصب على الجدران، أو على الأبواب، أو تجعل في الستور التي على الأبواب، أو على الجدران، أو في براويز تجعل على الجدران، فهذه لا تجوز. أما إذا كانت الصورة للفراش الذي يوطئ، أو ...... التي يجلس عليها، أو الوسائد، فلا حرج فيها؛ لأنهما ممتهنة. فثبت عنه ﷺ أنه رأى ستراً عند عائشة فيه تصاوير فغضب وأمر بهتكه، فجعلت منه عائشة وسادتين، كان ....... بهما -عليه الصلاة والسلام- وثبت في حديث أبي هريرة عند النسائي وغيره أن جبرائيل -عليه الصلاة والسلام- كان له موعد مع النبي ﷺ، فلما حضر وجد في البيت تمثالاً وستراً فيه تصاوير وكلباً لم يعلمه النبي ﷺ، فتوقف جبرائيل ولم يدخل حتى أخبره جبرائيل بذلك، فقال له: مر برأس التمثال فيقطع، وبالستر أن يتخذ منه وسادتان منتبذتان توطئان، وبالكلب أن يخرج فأمر به النبي ﷺ فأخرج الكلب، كان ...... الحسن أو الحسين، وأمر بالستر أن يتخذ منه وسادتان منتبذتان توطئان، وأمر بالتمثال أن يقطع رأسه، فدخل جبرائيل -عليه الصلاة والسلام-.\nالمقدم: بارك الله فيكم","link":"https://binbaz.org.sa/fatwas/27603/ما-الصور-التي-لا-يجوز-وجودها-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A7%D9%84%D8%B5%D9%88%D8%B1%20%D8%A7%D9%84%D8%AA%D9%8A%20%D9%84%D8%A7%20%D9%8A%D8%AC%D9%88%D8%B2%20%D8%AA%D8%B9%D9%84%D9%8A%D9%82%D9%87%D8%A7%20%D9%81%D9%8A%20%D8%A7%D9%84%D8%AC%D8%AF%D8%B1%D8%A7%D9%86.mp3","categories":["الصور والتصوير"]},{"id":19717,"question":"أخيرًا يسأل: ما هي أنواع الصور التي لا يجوز وجودها في البيوت؟","title":"ما الصور التي لا يجوز وجودها في البيوت؟","answer":"الجواب: الصور المنصوبة التي تنصب على الجدران، أو على الأبواب، أو تجعل في الستور التي على الأبواب، أو على الجدران، أو في براويز تجعل على الجدران، فهذه لا تجوز. أما إذا كانت الصورة للفراش الذي يوطأ، أو في السرر التي يجلس عليها، أو الوسائد، فلا حرج فيها؛ لأنهما ممتهنة، فثبت عنه ﷺ أنه رأى سترًا عند عائشة فيه تصاوير فغضب وأمر بهتكه، فجعلت منه عائشة وسادتين، كان يرتفق عليهما -عليه الصلاة والسلام-. وثبت في حديث أبي هريرة عند النسائي وغيره أن جبرائيل -عليه الصلاة والسلام- كان له موعد مع النبي ﷺ فلما حضر وجد في البيت تمثالًا وسترًا فيه تصاوير وكلبًا لم يعلمه النبي ﷺ فتوقف جبرائيل ولم يدخل حتى أخبره جبرائيل بذلك، فقال له: مر برأس التمثال فيقطع، وبالستر أن يتخذ منه وسادتان منتبذتان توطئان، وبالكلب أن يخرج فأمر به النبي ﷺ فأخرج الكلب، كان تحت نضَدٍ للحسن أو الحسين، وأمر بالستر أن يتخذ منه وسادتان منتبذتان توطئان، وأمر بالتمثال أن يقطع رأسه، فدخل جبرائيل -عليه الصلاة والسلام-. المقدم: بارك الله فيكم","link":"https://binbaz.org.sa/fatwas/27602/ما-الصور-التي-لا-يجوز-وجودها-في-البيوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/%D8%A7%D9%84%D8%B5%D9%88%D8%B1%20%D8%A7%D9%84%D8%AA%D9%8A%20%D9%84%D8%A7%20%D9%8A%D8%AC%D9%88%D8%B2%20%D8%AA%D8%B9%D9%84%D9%8A%D9%82%D9%87%D8%A7%20%D9%81%D9%8A%20%D8%A7%D9%84%D8%AC%D8%AF%D8%B1%D8%A7%D9%86.mp3","categories":["الصور والتصوير"]}]
